            "ios.rules.cover.no2": "Higher value, wrong suit - that covers nothing.",
            "ios.rules.throw.h": "Throwing in",
            "ios.rules.throw.b": "As the defender is covering, every other player may \"throw in\" additional attack cards that the defender must additionally cover. The rule for attacking is simple yet can take a while to grasp. If you see the VALUE (such as A, 6, 10) of a card you have on the table, and you are an attacker, you may add that card to the table as a separate new attack. Do not worry about the suits AT ALL. The only limit is the number of cards currently in the defender’s hand. The number of uncovered attacks on the table may not be more than the number of cards the defender holds. Imagine that the defender must be able to match each attack card with a single defense card. If there are too many attack cards, this is physically impossible, and thus not allowed. You may wonder if this could potentially cause the number of attack cards to quickly multiply. You’d be correct, and it is part of the fun of the game. To attack, tap a card or any set of cards where each card in the set has its value appear on the table, and press attack. Or you may drag cards from your hand to the table.",
            "ios.rules.throw.ok1": "A 9 is on the table, so your 9 can go in - suits don’t matter.",
            "ios.rules.throw.ok2": "Both 6s at once - two new attacks.",
            "ios.rules.throw.ok3": "Or the 6 and the 9 together - each value is already out there.",
            "ios.rules.throw.no1": "No 8 and no Jack on the table - nothing to throw in.",
            "ios.rules.throw.no2": "The defender holds one card and one attack is already waiting - no room for another.",
            "ios.rules.pickup.h": "Picking up",
            "ios.rules.pickup.b": "If a defender cannot cover all cards or does not want to cover, they may press the pickup button. This will cause the defender to pick up every card on the table, even if it is already covered. And their turn will be skipped, so the person to their left will start attacking in the next round. So think carefully about choosing to pick up.",
            "ios.rules.pickup.cap": "Pick up here and all three cards go to your hand - the covered pair too.",
            "ios.rules.round.h": "Round end",
            "ios.rules.round.b": "When all cards have been covered and all attackers have agreed to not throw in anymore, all cards on the table go to the discard pile. Players then draw starting from the first attacker, going clockwise through all attackers, drawing cards until they have at least 6 cards. Then the defender draws. This is done automatically by the game. If the deck runs out, then players may start to get rid of their cards and avoid ending up the fool. The round may also end if the defender chooses to pick up: the table goes to their hand instead of the discard, and everyone draws in the same order afterwards - the defender last, which usually means not at all, since they are holding more than six.",
            "ios.rules.pass.h": "Passing",
            "ios.rules.pass.b": "In a game where переводной or \"passing\" is allowed, the defender also has a choice to pass the attack away from them, and to the player on their left. To do this, no card on the table must be covered, and they must have a card of the same VALUE as all the attack cards on the table. Then they may place that card down, and the defender icon will move clockwise to the player on their left. However, similar to how there is a limit on how many cards can be attacked, a pass may not be done if the player to the left has fewer cards than there would be attack cards after the pass. For instance, if there are two attack cards on the table, and the player to the left holds two cards, passing is not possible as passing would result in at least 3 cards on the table (2 + 1 more to pass). This is more than the cards they hold and thus not allowed. To pass, you may tap the card of a matching value and press the pass button. Or drag the card with a matching value to an empty space on the table.",
            "ios.rules.pass.ok1": "An 8 is attacking and you hold an 8 - lay it down and the shield moves on.",
            "ios.rules.pass.no1": "Something is already covered - too late to pass.",
            "ios.rules.pass.no2": "No 8 in your hand - this one is yours to defend.",
            "ios.rules.pass.no3": "Passing would make three attacks, and the next player only holds two cards.",
            "ios.rules.end.h": "Game end",
            "ios.rules.end.b": "Once the draw deck is empty, the game continues playing. If someone gets rid of all their cards they are safe from being the fool. Whoever is the last player still left with cards becomes the fool.",
            // Round-9 (owner): the simpler pre-game rulebook the setup/lobby
            // screens open (RulesView scope .lobby) - how the lobby works, then
            // the goal section above as the quick what-is-this-game.
            "ios.rules.lobby.h": "How the lobby works",
            "ios.rules.lobby.b": "Add your name to join. Once at least two players have joined, anyone can press Start. After the game starts, no one else can join.",
            "ios.rules.variant.h": "Passing",
            "ios.rules.variant.b": "The lobby chooses which Durak this table plays, and the box says which. Ticked is the passing game (perevodnoy): a defender holding a card of the same rank as the attack can put it down and pass the whole attack on to the next player, who now has to defend it. Cleared is the throw-in game (podkidnoy): there is no passing, so a defender either covers every card on the table or picks it all up. Anyone at the table can change it while the lobby is open; once the game starts it is fixed.",
            "ios.rules.fool.h": "The fool pays for it",
            "ios.rules.fool.b": "Normally the lowest power suit card decides who attacks first. There is one exception, and it is the oldest kind of Durak justice: if you press New game after a game ends and the exact same players line up again, the lowest trump decides nothing. The player sitting to the right of the last fool opens instead, which means the fool is the first one attacked. Lose, and the next game comes straight at you. If anyone joins or leaves before Start, the table has changed and the normal rule comes back.",
            "ios.lobby.passing": "Passing",
            "ios.rules.lbl.table": "on the table",
            "ios.rules.lbl.hand": "your hand",
