            "ios.rej.defending": "Вы защищаетесь - кройте или берите.",
            "ios.rej.notyours": "Этой карты нет в вашей руке.",
            "ios.rej.addrank": "Подкинуть можно только карту того достоинства, которое уже есть на столе.",
            "ios.rej.cover": "Так не побить - сыграйте старше или козырем.",
            "ios.rej.capacity": "Слишком много атак для руки защитника.",
            "ios.rej.passrank": "Переводить можно только картой того же достоинства.",
            "ios.rej.mustattack": "Первый атакующий обязан атаковать.",
            "ios.rej.alreadygood": "Вы уже сказали «бито».",
            "ios.rej.notake": "Брать нечего.",
            "ios.help": "Правила",
            "ios.settings.title": "Настройки",
            "ios.settings.table": "Стол",
            "ios.settings.table.wool": "Шерсть",
            "ios.settings.table.felt": "Зелёное сукно",
            "ios.rules.title": "Как играть",
            "ios.rules.goal.h": "Цель игры",
            "ios.rules.goal.b": "Главная цель - как можно скорее избавиться от всех своих карт. Кто остался с картами в конце, тот и есть дурак.",
            "ios.rules.setup.h": "Подготовка",
            "ios.rules.setup.b": "Если игроков четверо или меньше, играют картами от шестёрки до туза - двойки, тройки, четвёрки и пятёрки убирают из игры. Туз - старшая карта. Каждому сдают по шесть карт, затем ещё одну открывают и кладут под колоду. МАСТЬ этой карты - козырная. Козырь особенный, об этом - в защите.",
            "ios.rules.setup.cap": "Одну карту открывают и кладут под колоду - её масть и есть козырь. Во всех примерах на этой странице козыри червы.",
            "ios.rules.start.h": "Начало игры",
            "ios.rules.start.b": "Первым ходит тот, у кого младший козырь. Вживую это выясняют вопросами - у кого шестёрка? а семёрка? - здесь игра определяет это сама. Этот игрок - первый атакующий раунда.",
            "ios.rules.sword": "Меч отмечает атакующего, который открывает раунд.",
            "ios.rules.shield": "Щит отмечает защитника.",
            "ios.rules.attack.h": "Атака",
            "ios.rules.attack.b": "Первый атакующий может выложить любую карту - или несколько карт ОДНОГО достоинства - в сторону игрока слева (по часовой). Тот становится защитником и должен разобраться с атакой. Коснитесь карт, чтобы выбрать их, и нажмите «Атака», когда выбор складывается в допустимый ход, - или просто перетащите карты из руки на стол.",
            "ios.rules.attack.ok1": "Можно атаковать одной дамой.",
            "ios.rules.attack.ok2": "Или оба короля разом - достоинство одно.",
            "ios.rules.attack.no1": "Но не семёрка с десяткой вместе - достоинства разные.",
            "ios.rules.defend.h": "Защита",
            "ios.rules.defend.b": "Защитник всегда один, и все карты, выложенные остальными, - его забота. Защитник может только крыть, взять или перевести (если перевод разрешён) - сам он не атакует. Все остальные - атакующие, и крыть они не могут.",
            "ios.rules.defend.b.nopass": "Защитник всегда один, и все карты, выложенные остальными, - его забота. Защитник может только крыть или взять - сам он не атакует. Все остальные - атакующие, и крыть они не могут.",
            "ios.rules.cover.h": "Покрытие",
            "ios.rules.cover.b": "Защитник кроет карты на столе: каждую - старшей картой той же масти либо любым козырем. Именно это делает козырную масть особенной. Чтобы крыть, выберите карту и нажмите «Крыть». Или перетащите карту с руки на ту, которую хотите покрыть. Частая ошибка - думать, что уже покрытую карту можно покрыть третьей. Нельзя: стопок из трёх карт на столе не бывает. Считайте карту атаки мечом, а карту защиты - щитом: атака остановлена, а значит, закончена. Можно только атаковать заново, отдельными стопками.",
            "ios.rules.cover.ok1": "Кроет старшая карта той же масти.",
            "ios.rules.cover.ok2": "Любой козырь кроет любую другую масть - даже младший.",
            "ios.rules.cover.no1": "Козырную атаку кроют старшим козырем - эта семёрка слишком мала.",
            "ios.rules.cover.no2": "Старше, но не той масти - ничего не кроет.",
            "ios.rules.throw.h": "Подкидывание",
            "ios.rules.throw.b": "Пока защитник отбивается, остальные могут подкидывать. Правило простое, но к нему привыкают: если ДОСТОИНСТВО карты из вашей руки (например, туз, шестёрка, десятка) уже есть где-то на столе, её можно подкинуть как новую отдельную атаку. О мастях не думайте ВООБЩЕ. Ограничение одно - рука защитника: непокрытых атак не может быть больше, чем у него карт, - на каждую атаку он должен суметь ответить картой. Если атак слишком много, это физически невозможно, а значит нельзя. Может показаться, что так стол разрастается стремительно. Так и есть - и в этом часть азарта. Чтобы подкинуть, коснитесь карты или карт, достоинство каждой из которых уже есть на столе, и нажмите «Атака». Или перетащите карты из руки на стол.",
            "ios.rules.throw.ok1": "Девятка есть на столе - значит, ваша девятка идёт в ход, масть не важна.",
            "ios.rules.throw.ok2": "Обе шестёрки разом - две новые атаки.",
            "ios.rules.throw.ok3": "Или шестёрка с девяткой вместе - оба достоинства уже на столе.",
            "ios.rules.throw.no1": "Ни восьмёрки, ни валета на столе - подкинуть нечего.",
            "ios.rules.throw.no2": "У защитника одна карта, и одна атака уже ждёт - больше некуда.",
            "ios.rules.pickup.h": "Взятие",
            "ios.rules.pickup.b": "Если защитник не может покрыть всё - или не хочет - он нажимает «Взять» и забирает в руку ВСЕ карты со стола, включая уже покрытые. Его ход пропускается: следующий раунд открывает игрок слева. Так что брать или нет - решайте с умом.",
            "ios.rules.pickup.cap": "Возьмёте здесь - и все три карты уйдут в руку, покрытая пара тоже.",
            "ios.rules.round.h": "Конец раунда",
            "ios.rules.round.b": "Когда все карты покрыты и никто больше не подкидывает, всё со стола уходит в отбой. Потом добирают: первым - первый атакующий, дальше по часовой стрелке через всех атакующих, каждый до шести карт на руках. Защитник добирает последним. Игра делает это сама. Раунд кончается и тогда, когда защитник берёт: карты со стола уходят к нему в руку, а не в отбой, и дальше добирают в том же порядке - защитник последним, а значит обычно вовсе не добирает, потому что у него уже больше шести. Когда колода опустела, добора больше нет - игроки избавляются от карт и уходят из игры, спасаясь от роли дурака.",
            "ios.rules.pass.h": "Перевод",
            "ios.rules.pass.b": "В игре с переводом у защитника есть ещё один выход: перевести атаку дальше. Если на столе ещё ничего не покрыто и у вас есть карта ТОГО ЖЕ достоинства, что и карты атаки, положите её - и щит перейдёт к игроку слева от вас. Ограничение знакомое: перевести нельзя, если у следующего игрока меньше карт, чем станет атак после перевода. Например: на столе две карты атаки, а игрок слева держит две карты - переводить нельзя, ведь после перевода на столе будет минимум три карты (2 + 1 переводная), а это больше, чем у него в руке. Коснитесь подходящей карты и нажмите «Пас» - или перетащите её на свободное место стола.",
            "ios.rules.pass.ok1": "Атакуют восьмёркой, и у вас есть восьмёрка - кладите, щит двинется дальше.",
            "ios.rules.pass.no1": "Что-то уже покрыто - переводить поздно.",
            "ios.rules.pass.no2": "Восьмёрки в руке нет - эта атака ваша.",
            "ios.rules.pass.no3": "После перевода атак станет три, а у следующего игрока всего две карты.",
            "ios.rules.end.h": "Конец игры",
            "ios.rules.end.b": "Когда колода пуста, игра продолжается. Избавились от карт - вы в безопасности. Последний, кто остался с картами, - дурак.",
            "ios.rules.lobby.h": "Как работает лобби",
            "ios.rules.lobby.b": "Впишите своё имя, чтобы войти. Как только соберутся хотя бы двое, любой может нажать «Начать игру». После начала игры войти уже нельзя.",
            "ios.rules.variant.h": "Переводной",
            "ios.rules.variant.b": "В лобби выбирают, в какого дурака играет этот стол, и галочка говорит, в какого. Галочка стоит - играем в переводного: защищающийся с картой того же достоинства, что и атака, может положить её и перевести всю атаку на следующего игрока, и отбиваться теперь ему. Галочки нет - играем в подкидного: перевода нет, защищающийся либо кроет всё, что на столе, либо забирает. Пока лобби открыто, поменять может любой за столом; после начала игры правило зафиксировано.",
            "ios.rules.fool.h": "Дурак платит",
            "ios.rules.fool.b": "Обычно младший козырь решает, кто атакует первым. Есть одно исключение, и это самый старый закон дурака: если после конца игры нажать «Новая игра» и за столом окажутся ровно те же игроки, младший козырь не решает ничего. Первым ходит сосед справа от прошлого дурака - то есть дурака атакуют первым. Проиграли - и следующая игра пойдёт прямо на вас. Если до старта кто-то вошёл или вышел, стол изменился и возвращается обычное правило.",
            "ios.lobby.passing": "Переводной",
            "ios.rules.lbl.table": "на столе",
