            "ios.rej.turn": "아직 차례가 아닙니다.",
            "ios.rej.pickone": "먼저 카드를 선택하세요.",
            "ios.rej.defending": "방어 중입니다 - 공격을 막거나 가져오세요.",
            "ios.rej.notyours": "그 카드는 손패에 없습니다.",
            "ios.rej.addrank": "테이블에 이미 있는 숫자만 추가할 수 있습니다.",
            "ios.rej.cover": "그걸로는 못 이깁니다 - 더 높거나 으뜸패를 내세요.",
            "ios.rej.capacity": "방어자 손패에 비해 공격이 너무 많습니다.",
            "ios.rej.passrank": "같은 숫자로만 넘길 수 있습니다.",
            "ios.rej.mustattack": "첫 공격자는 공격해야 합니다.",
            "ios.rej.alreadygood": "이미 완료를 선언했습니다.",
            "ios.rej.notake": "가져올 카드가 없습니다.",
            "ios.help": "규칙",
            "ios.settings.title": "설정",
            "ios.settings.table": "테이블",
            "ios.settings.table.wool": "모직",
            "ios.settings.table.felt": "그린 펠트",
            "ios.rules.title": "게임 방법",
            "ios.rules.goal.h": "게임의 목표",
            "ios.rules.goal.b": "궁극의 목표는 손의 카드를 최대한 빨리 없애는 것입니다. 끝까지 카드를 들고 있는 사람이 дурак - 러시아어로 ‘바보’입니다.",
            "ios.rules.setup.h": "게임 준비",
            "ios.rules.setup.b": "플레이어가 네 명 이하면 6부터 에이스까지의 카드만 씁니다 - 2, 3, 4, 5는 뺍니다. 에이스가 가장 높습니다. 각자 여섯 장을 받은 뒤, 카드 한 장을 더 뽑아 앞면으로 뒤집어 뽑을 더미 아래에 둡니다. 그 카드의 무늬가 으뜸 무늬입니다. 으뜸 무늬는 특별하며, ‘수비’에서 설명합니다.",
            "ios.rules.setup.cap": "뽑을 더미 아래에 카드 한 장을 뒤집어 둡니다 - 그 무늬가 으뜸 무늬입니다. 이 페이지의 모든 예시는 하트입니다.",
            "ios.rules.start.h": "게임 시작",
            "ios.rules.start.b": "가장 낮은 으뜸 무늬 카드를 든 사람이 먼저 합니다. 실제 게임에서는 6 있나요? 7은요? 하고 물어 가며 정하지만, 여기서는 게임이 자동으로 정합니다. 그 사람이 이번 라운드의 첫 공격자입니다.",
            "ios.rules.sword": "검은 라운드를 여는 공격자를 나타냅니다.",
            "ios.rules.shield": "방패는 방어자를 나타냅니다.",
            "ios.rules.attack.h": "공격",
            "ios.rules.attack.b": "첫 공격자는 아무 카드 한 장, 또는 값이 같은 카드 여러 장을 왼쪽(시계 방향) 플레이어 쪽으로 낼 수 있습니다. 그 플레이어가 방어자가 되어 공격을 처리해야 합니다. 카드를 탭해 고르고, 유효한 공격이 되면 나타나는 공격 버튼을 누르세요 - 아니면 손에서 테이블로 끌어다 놓아도 됩니다.",
            "ios.rules.attack.ok1": "이 플레이어는 퀸으로 공격할 수 있습니다.",
            "ios.rules.attack.ok2": "킹 두 장을 한꺼번에 - 값이 같으니까요.",
            "ios.rules.attack.no1": "7과 10을 같이는 안 됩니다 - 값이 다릅니다.",
            "ios.rules.defend.h": "방어",
            "ios.rules.defend.b": "지금 공격을 받는 플레이어, 즉 방패 아이콘이 붙은 사람이 방어자입니다. 방어자는 한 번에 한 명뿐이고, 다른 플레이어들이 낸 카드는 전부 방어자의 몫입니다. 방어자는 막기, 가져오기, 넘기기(허용된 경우)만 할 수 있고 - 스스로 공격할 수는 없습니다. 나머지는 모두 공격자이며, 공격자는 막을 수 없습니다.",
            "ios.rules.defend.b.nopass": "지금 공격을 받는 플레이어, 즉 방패 아이콘이 붙은 사람이 방어자입니다. 방어자는 한 번에 한 명뿐이고, 다른 플레이어들이 낸 카드는 전부 방어자의 몫입니다. 방어자는 막기와 가져오기만 할 수 있고 - 스스로 공격할 수는 없습니다. 나머지는 모두 공격자이며, 공격자는 막을 수 없습니다.",
            "ios.rules.cover.h": "막기",
            "ios.rules.cover.b": "방어자는 각 공격 카드를 같은 무늬의 더 높은 카드, 또는 아무 으뜸패로나 막습니다 - 이것이 으뜸 무늬의 힘입니다. 카드를 선택하고 막기 버튼을 누르거나, 막고 싶은 카드 위로 끌어다 놓으세요. 흔한 오해 하나: 이미 막힌 카드는 다시 막을 수 없습니다 - 석 장짜리 더미는 없습니다. 공격은 검, 막은 카드는 방패입니다: 막힌 공격은 끝난 것입니다. 새 공격은 새 더미로 놓입니다.",
            "ios.rules.cover.ok1": "같은 무늬의 더 높은 카드로 막습니다.",
            "ios.rules.cover.ok2": "으뜸패는 값이 낮아도 다른 무늬를 다 막습니다.",
            "ios.rules.cover.no1": "으뜸패 공격은 더 높은 으뜸패로만 - 이 7은 낮습니다.",
            "ios.rules.cover.no2": "값은 높아도 무늬가 다르면 못 막습니다.",
            "ios.rules.throw.h": "추가 공격",
            "ios.rules.throw.b": "방어자가 막는 동안 다른 플레이어들은 공격을 더 던져 넣을 수 있습니다. 규칙은 간단하지만 익숙해지는 데 시간이 좀 걸립니다: 손에 든 카드의 값(예: A, 6, 10)이 테이블 위 어디든 이미 있다면, 그 카드를 새로운 별도의 공격으로 낼 수 있습니다. 무늬는 전혀 신경 쓰지 마세요. 한도는 방어자의 손 하나뿐입니다: 막지 않은 공격 수가 방어자가 든 카드 수를 넘을 수 없습니다 - 공격마다 카드 한 장으로 답할 수 있어야 하니까요. 공격이 너무 많으면 물리적으로 불가능하니 허용되지 않습니다. 이러면 테이블이 순식간에 불어나지 않을까요? 맞습니다. 그게 이 게임의 재미입니다. 던져 넣으려면 값이 테이블에 이미 있는 카드들을 탭하고 공격을 누르거나, 손에서 테이블로 끌어다 놓으세요.",
            "ios.rules.throw.ok1": "테이블에 9가 있으니 당신의 9를 낼 수 있습니다 - 무늬는 상관없습니다.",
            "ios.rules.throw.ok2": "6 두 장을 한꺼번에 - 새 공격 둘.",
            "ios.rules.throw.ok3": "6과 9를 같이 - 두 값 모두 이미 나와 있습니다.",
            "ios.rules.throw.no1": "테이블에 8도 잭도 없으니 던질 게 없습니다.",
            "ios.rules.throw.no2": "방어자 손엔 한 장, 이미 공격 하나가 기다립니다 - 더는 안 됩니다.",
            "ios.rules.pickup.h": "가져오기",
            "ios.rules.pickup.b": "다 막을 수 없거나 막고 싶지 않다면, 방어자는 가져오기 버튼을 누릅니다. 그러면 테이블의 모든 카드를 - 이미 막힌 것까지 - 손에 가져오고, 다음 차례를 건너뜁니다: 다음 라운드는 왼쪽 플레이어가 엽니다. 그러니 가져올지는 신중히 정하세요.",
            "ios.rules.pickup.cap": "여기서 가져오면 석 장 모두 - 막힌 쌍까지 - 손에 들어옵니다.",
            "ios.rules.round.h": "라운드 종료",
            "ios.rules.round.b": "모든 공격이 막히고 공격자들이 더 던지지 않기로 하면, 테이블의 카드는 전부 버린 더미로 갑니다. 그다음 손패가 최소 여섯 장이 되도록 뽑습니다 - 첫 공격자부터 시계 방향으로 공격자들이 먼저, 방어자가 마지막이며, 이미 여섯 장 이상이면 뽑지 않습니다. 게임이 자동으로 처리합니다. 방어자가 가져오기를 택해도 라운드는 끝나지만, 이때 테이블의 카드는 버린 더미가 아니라 방어자의 손패로 갑니다. 그 뒤에도 같은 순서로 뽑으며, 방어자가 마지막입니다 - 이미 여섯 장이 넘으므로 보통은 뽑지 않습니다. 덱이 비면 더 뽑지 않고, 손패를 먼저 비운 사람은 바보를 면하고 게임에서 빠집니다.",
            "ios.rules.pass.h": "넘기기",
            "ios.rules.pass.b": "переводной - ‘넘기기’가 허용된 게임에서는 방어자에게 선택지가 하나 더 있습니다: 공격을 옆으로 넘기는 것. 테이블에 막힌 카드가 하나도 없고, 공격 카드들과 같은 값의 카드를 들고 있다면, 그 카드를 내려놓으세요 - 방패가 왼쪽 플레이어에게 넘어갑니다. 익숙한 한도가 그대로 적용됩니다: 넘긴 뒤의 공격 수가 다음 플레이어의 카드 수보다 많아지면 넘길 수 없습니다. 예를 들어 테이블에 공격 카드가 두 장이고 왼쪽 플레이어가 두 장만 들고 있다면, 넘기면 테이블에 최소 석 장(2 + 넘기는 1장)이 되어 그가 든 카드보다 많아지므로 안 됩니다. 값이 맞는 카드를 탭하고 패스를 누르거나, 테이블의 빈자리로 끌어다 놓으세요.",
            "ios.rules.pass.ok1": "8이 공격 중인데 8을 들고 있다면 - 내려놓으세요, 방패가 넘어갑니다.",
            "ios.rules.pass.no1": "이미 막힌 카드가 있으면 - 넘기기엔 늦었습니다.",
            "ios.rules.pass.no2": "손에 8이 없으니 - 이번엔 직접 막아야 합니다.",
            "ios.rules.pass.no3": "넘기면 공격이 셋, 다음 플레이어 카드는 두 장뿐입니다.",
            "ios.rules.end.h": "게임 종료",
            "ios.rules.end.b": "뽑을 더미가 비어도 게임은 계속됩니다. 손을 다 비우면 바보가 될 일은 없습니다. 마지막까지 카드를 들고 있는 사람이 바보입니다.",
            "ios.rules.lobby.h": "로비 안내",
            "ios.rules.lobby.b": "이름을 입력해 참가하세요. 두 명 이상 모이면 누구나 게임 시작을 누를 수 있습니다. 게임이 시작되면 더 이상 참가할 수 없습니다.",
            "ios.rules.variant.h": "넘기기",
            "ios.rules.variant.b": "이 테이블이 어떤 두라크를 하는지는 로비에서 정하며, 체크 상자가 그것을 알려줍니다. 체크되어 있으면 넘기기 게임(페레보드노이)입니다. 방어자가 공격 카드와 같은 숫자의 카드를 가지고 있으면 그것을 내려놓고 공격 전체를 다음 사람에게 넘길 수 있고, 이제 그 사람이 막아야 합니다. 체크가 없으면 던지기 게임(포드키드노이)입니다. 넘기기가 없으므로 방어자는 테이블 위의 모든 카드를 막거나 전부 가져가야 합니다. 로비가 열려 있는 동안에는 테이블에 앉은 누구나 바꿀 수 있고, 게임이 시작되면 고정됩니다.",
            "ios.rules.fool.h": "바보가 값을 치릅니다",
            "ios.rules.fool.b": "보통은 가장 낮은 으뜸패를 가진 사람이 먼저 공격합니다. 예외가 하나 있는데, 두라크에서 가장 오래된 방식의 정의입니다. 게임이 끝난 뒤 새 게임을 누르고 똑같은 사람들이 다시 앉으면 낮은 으뜸패는 아무것도 결정하지 않습니다. 지난 판 바보의 오른쪽에 앉은 사람이 먼저 공격하고, 따라서 바보가 가장 먼저 공격을 받습니다. 지면 다음 판이 바로 당신에게 옵니다. 시작 전에 누군가 들어오거나 나가면 판이 달라진 것이므로 원래 규칙으로 돌아갑니다.",
            "ios.lobby.passing": "넘기기",
