            "ios.rej.turn": "还没轮到你。",
            "ios.rej.pickone": "先选一张牌。",
            "ios.rej.defending": "你在防守 —— 盖住这次进攻，或者把牌拿走。",
            "ios.rej.notyours": "这张牌不在你手里。",
            "ios.rej.addrank": "只能加桌上已经出现过的点数的牌。",
            "ios.rej.cover": "盖不住 —— 要同花色更大的牌，或者一张主牌。",
            "ios.rej.capacity": "桌上没盖住的进攻不能超过防守方的手牌数。",
            "ios.rej.passrank": "只能用点数相同的牌转移。",
            "ios.rej.mustattack": "首攻必须先进攻。",
            "ios.rej.alreadygood": "你已经过了。",
            "ios.rej.notake": "没有牌可拿。",
            "ios.help": "规则",
            "ios.settings.title": "设置",
            "ios.settings.table": "牌桌",
            "ios.settings.table.wool": "羊毛",
            "ios.settings.table.felt": "绿毡",
            "ios.rules.title": "玩法",
            "ios.rules.goal.h": "目标",
            "ios.rules.goal.b": "游戏的最终目标是尽快把手里的牌全部打出去。最后还剩着牌的人就是 дурак，俄语里的“傻瓜”。",
            "ios.rules.setup.h": "开局准备",
            "ios.rules.setup.b": "四人或四人以下时，只用 6 到 A 这些牌，2、3、4、5 全部拿掉。A 在这个游戏里最大。每人发 6 张牌，然后再翻出一张明牌，压在牌堆下面。这张明牌的花色就是主牌花色。主牌花色很特别，防守那一节会讲到。",
            "ios.rules.setup.cap": "牌堆下面压着一张翻开的牌 —— 它的花色就是主牌花色。本页所有例子里都是红桃。",
            "ios.rules.start.h": "谁先出牌",
            "ios.rules.start.b": "手里主牌最小的人先出。面对面玩的时候，大家会问谁有 6，然后问谁有 7，以此类推。在这里由游戏自动判定。这个人就是这一轮的首攻。",
            "ios.rules.sword": "剑的图标标记开这一轮的首攻。",
            "ios.rules.shield": "盾的图标标记防守方。",
            "ios.rules.attack.h": "进攻",
            "ios.rules.attack.b": "带剑图标的首攻可以从手里选一张牌，或者选一组点数完全相同的牌，打到左边（顺时针方向）那位玩家面前。那位玩家现在就是防守方，带盾图标，必须应对这次进攻。出牌时点一下选中牌，选中的牌构成合法进攻时进攻按钮就会出现；也可以直接把牌从手里拖到桌上。",
            "ios.rules.attack.ok1": "这位玩家可以用 Q 进攻。",
            "ios.rules.attack.ok2": "也可以两张 K 一起打出去，因为点数相同。",
            "ios.rules.attack.no1": "但不能用 7 和 10 一起进攻，点数不一样。",
            "ios.rules.defend.h": "防守",
            "ios.rules.defend.b": "带盾图标、正在被进攻的那位玩家是防守方。同一时刻只会有一个防守方，别人打到桌上的牌都要由他来应对。防守方只能盖牌、拿牌，或者转移（如果这一桌允许）。防守方不能自己进攻。其他所有人都是进攻方，只能进攻，不能去盖桌上的牌。",
            "ios.rules.defend.b.nopass": "带盾图标、正在被进攻的那位玩家是防守方。同一时刻只会有一个防守方，别人打到桌上的牌都要由他来应对。防守方只能盖牌或者拿牌。防守方不能自己进攻。其他所有人都是进攻方，只能进攻，不能去盖桌上的牌。",
            "ios.rules.cover.h": "盖牌",
            "ios.rules.cover.b": "防守方可以用同花色更大的牌，或者任意一张主牌，把桌上的牌一张张盖住。这就是主牌花色特别的地方。盖牌时选中一张牌再点盖牌按钮，或者把手里的牌拖到桌上想盖的那张牌上。常见的误会是以为已经盖住的牌还能被第三张牌再盖一次 —— 并不是这样，你永远不会在桌上看到三张一摞。把进攻牌想成一把剑，盖牌想成一面盾：挡下来了，这一摞就结束了。要打只能另起一摞新的进攻。",
            "ios.rules.cover.ok1": "同花色更大的牌可以盖住。",
            "ios.rules.cover.ok2": "主牌能盖住任何别的花色 —— 哪怕点数更小。",
            "ios.rules.cover.no1": "主牌的进攻要用更大的主牌来盖 —— 这张 7 太小了。",
            "ios.rules.cover.no2": "点数更大，但花色不对 —— 盖不住。",
            "ios.rules.throw.h": "加牌",
            "ios.rules.throw.b": "防守方盖牌的时候，其他每一位玩家都可以往桌上“加牌”，防守方必须把这些牌也一并防住。规则本身很简单，但要真正想明白得花点时间：如果桌上已经出现了某个点数（比如 A、6、10），而你是进攻方，手里又有这个点数的牌，你就可以把它作为新的一摞进攻加到桌上。完全不用管花色。唯一的限制是防守方手里的牌数：桌上没被盖住的进攻，数量不能超过防守方手里的牌数。可以这样想 —— 防守方必须能用一张牌应对一张进攻牌；如果进攻牌太多，这在物理上就不可能，因此也不允许。你可能会想，这样进攻牌岂不是会迅速变多？没错，这正是这个游戏好玩的地方。加牌时点一下那张牌，或者点一组每张点数都已经在桌上出现过的牌，然后按进攻；也可以直接把牌从手里拖到桌上。",
            "ios.rules.throw.ok1": "桌上有 9，所以你的 9 可以加进去 —— 花色无所谓。",
            "ios.rules.throw.ok2": "两张 6 一起 —— 两摞新的进攻。",
            "ios.rules.throw.ok3": "6 和 9 一起也行 —— 这两个点数桌上都已经有了。",
            "ios.rules.throw.no1": "桌上没有 8 也没有 J —— 没有能加的牌。",
            "ios.rules.throw.no2": "防守方只剩一张牌，桌上已经有一次进攻等着 —— 再加就放不下了。",
            "ios.rules.pickup.h": "拿牌",
            "ios.rules.pickup.b": "如果防守方盖不住所有的牌，或者不想盖，可以按拿牌按钮。这样桌上所有的牌都会进他的手里，已经被盖住的也一样。而且下一轮会跳过他，下一轮由他左边的人开始进攻。所以要不要拿牌，得想清楚。",
            "ios.rules.pickup.cap": "这里拿牌的话，三张牌都进你手里 —— 那对盖住的也一样。",
            "ios.rules.round.h": "一轮结束",
            "ios.rules.round.b": "当桌上所有牌都被盖住，而且所有进攻方都表示不再加牌时，桌上的牌全部进弃牌堆。然后从首攻开始，顺时针轮到每一位进攻方补牌，补到至少 6 张为止，最后才轮到防守方补牌。这些都由游戏自动完成。牌堆摸完之后，大家就可以开始清手里的牌，争取不做最后那个傻瓜。防守方选择拿牌时，这一轮同样结束，进攻方也照样补牌。",
            "ios.rules.pass.h": "转移",
            "ios.rules.pass.b": "在允许 переводной（也就是“转移”）的牌局里，防守方还有一个选择：把这次进攻转移给左边的玩家。要这样做，桌上不能有任何一张牌已经被盖住，而且他手里要有一张与桌上所有进攻牌点数相同的牌。把那张牌放下，盾的图标就会顺时针移到左边那位玩家身上。不过，和进攻牌数有上限一样，如果左边那位玩家手里的牌比转移之后的进攻牌数还少，就不能转移。举个例子：桌上已经有两张进攻牌，左边那位手里只有两张牌，那就不能转移 —— 因为转移之后桌上至少会有三张进攻牌（原来的 2 张加上你放下的 1 张），比他手里的牌还多。转移时点一下点数相同的那张牌再按转移按钮，或者把它拖到桌上的空处。",
            "ios.rules.pass.ok1": "桌上是一张 8，你手里也有 8 —— 放下去，盾就移走了。",
            "ios.rules.pass.no1": "已经有牌被盖住了 —— 来不及转移了。",
            "ios.rules.pass.no2": "你手里没有 8 —— 这次只能你自己防。",
            "ios.rules.pass.no3": "转移之后会变成三次进攻，而下一位手里只有两张牌。",
            "ios.rules.end.h": "游戏结束",
            "ios.rules.end.b": "牌堆摸完之后，游戏继续进行。谁把手里的牌全部打完，谁就不会是傻瓜。最后一个手里还有牌的人就是傻瓜。",
            "ios.rules.lobby.h": "房间怎么用",
            "ios.rules.lobby.b": "写上你的名字就算加入。至少两个人加入之后，任何人都可以按开始。游戏一旦开始，就不能再有人加入了。",
            "ios.rules.variant.h": "转移",
            "ios.rules.variant.b": "这一桌玩哪一种傻瓜牌，由房间里决定，勾选框会告诉你玩的是哪一种。勾上就是转移玩法（переводной）：防守方手里如果有和进攻牌点数相同的牌，可以放下去，把整次进攻转移给下一位，改由他来防守。不勾就是加牌玩法（подкидной）：没有转移，防守方要么把桌上的牌全部盖住，要么全部拿走。房间开着的时候，桌上任何人都可以改；游戏一开始就固定了。",
            "ios.rules.fool.h": "傻瓜要付出代价",
            "ios.rules.fool.b": "通常由最小的主牌决定谁先进攻。只有一个例外，也是最古老的一种傻瓜牌规矩：如果一局结束后你按了新游戏，而且原班人马一个不差地又坐了下来，那么最小的主牌就说了不算了 —— 改由上一局那个傻瓜右边的人先出，也就是说傻瓜是第一个被进攻的。输了，下一局就直接冲你来。如果在按开始之前有人加入或离开，这一桌就变了，规则也就恢复正常。",
            "ios.lobby.passing": "转移",
