            "ios.tut_1": "欢迎来玩傻瓜牌。主牌花色里最小的那张牌决定谁先进攻。主牌大过其他所有花色。",
            "ios.tut_2": "进攻时点一下手里的牌。对手必须盖住它 —— 否则就得把牌全拿走。",
            "ios.tut_3": "防守时先点你的一张牌，再点它要盖的那次进攻。同花色更大的牌，或者任意一张主牌，都能盖住。",
