            "ios.settings.table": "Mặt bàn",
            "ios.settings.table.wool": "Len",
            "ios.settings.table.felt": "Nỉ xanh",
            "ios.rules.title": "Cách chơi",
            "ios.rules.goal.h": "Mục tiêu",
            "ios.rules.goal.b": "Mục tiêu cuối cùng là đánh hết bài trên tay càng sớm càng tốt. Ai còn bài sau cùng thì người đó là дурак, tiếng Nga nghĩa là kẻ ngốc.",
            "ios.rules.setup.h": "Chuẩn bị ván",
            "ios.rules.setup.b": "Nếu có từ bốn người trở xuống, ván chỉ dùng các lá từ 6 đến Át; 2, 3, 4 và 5 được bỏ ra. Át là lá lớn nhất trong trò này. Mỗi người được chia 6 lá, sau đó rút thêm một lá, lật ngửa và đặt xuống dưới nọc. CHẤT của lá lật ngửa đó chính là chất chủ. Chất chủ rất đặc biệt, phần đỡ bài sẽ nói rõ.",
            "ios.rules.setup.cap": "Một lá được lật ngửa dưới nọc - chất của nó là chất chủ. Trong mọi ví dụ ở trang này là cơ.",
            "ios.rules.start.h": "Bắt đầu ván",
            "ios.rules.start.b": "Ai giữ lá chủ nhỏ nhất thì đi trước. Chơi ngoài đời thì mọi người hỏi ai có 6, rồi ai có 7, và cứ thế. Ở đây ứng dụng tự xác định. Người đó là người mở vòng.",
            "ios.rules.sword": "Thanh kiếm đánh dấu người mở vòng tấn công.",
            "ios.rules.shield": "Cái khiên đánh dấu người đỡ.",
            "ios.rules.attack.h": "Tấn công",
            "ios.rules.attack.b": "Người mở vòng, có biểu tượng thanh kiếm, được chọn một lá bất kỳ hoặc một bộ lá CÙNG HẠNG trong tay và đặt về phía người bên trái mình (theo chiều kim đồng hồ). Người đó bây giờ là người đỡ, có biểu tượng khiên, và phải xử lý đòn tấn công. Để đánh, chạm chọn bài rồi bấm nút tấn công hiện ra khi các lá đã chọn hợp lệ. Hoặc chỉ cần kéo bài từ tay ra bàn.",
            "ios.rules.attack.ok1": "Người này có thể tấn công bằng lá Q.",
            "ios.rules.attack.ok2": "Cũng có thể đánh cả hai lá K cùng lúc, vì chúng cùng hạng.",
            "ios.rules.attack.no1": "Nhưng KHÔNG được đánh lá 7 với lá 10 cùng lúc, vì khác hạng.",
            "ios.rules.defend.h": "Đỡ bài",
            "ios.rules.defend.b": "Người đang bị tấn công, có biểu tượng khiên, là người đỡ. Mỗi lúc chỉ có một người đỡ, và mọi lá người khác đặt xuống bàn đều là việc của người đỡ. Người đỡ chỉ được chặn, bốc, hoặc chuyển (nếu bàn cho phép). Người đỡ KHÔNG được tự tấn công. Tất cả những người còn lại là bên tấn công, chỉ được tấn công và KHÔNG được chặn bất kỳ lá nào trên bàn.",
            "ios.rules.defend.b.nopass": "Người đang bị tấn công, có biểu tượng khiên, là người đỡ. Mỗi lúc chỉ có một người đỡ, và mọi lá người khác đặt xuống bàn đều là việc của người đỡ. Người đỡ chỉ được chặn hoặc bốc. Người đỡ KHÔNG được tự tấn công. Tất cả những người còn lại là bên tấn công, chỉ được tấn công và KHÔNG được chặn bất kỳ lá nào trên bàn.",
            "ios.rules.cover.h": "Chặn bài",
            "ios.rules.cover.b": "Người đỡ chặn bài trên bàn bằng cách phủ mỗi lá bằng một lá cùng chất nhưng lớn hơn, hoặc bằng một lá chủ bất kỳ. Đó là điều làm chất chủ đặc biệt. Để chặn, chọn một lá rồi bấm nút chặn. Hoặc kéo lá trong tay tới đúng lá trên bàn mà bạn muốn phủ. Một hiểu lầm thường gặp là tưởng lá đã bị phủ còn có thể bị phủ tiếp bằng lá thứ ba. Không phải vậy - bạn sẽ không bao giờ thấy chồng ba lá trên bàn. Hãy coi lá tấn công là thanh kiếm và lá chặn là cái khiên: đòn đã bị chặn, thế là xong. Chỉ có thể mở đòn tấn công mới, thành đống riêng.",
            "ios.rules.cover.ok1": "Lá cùng chất và lớn hơn thì chặn được.",
            "ios.rules.cover.ok2": "Lá chủ chặn được mọi chất khác - kể cả khi hạng nhỏ hơn.",
            "ios.rules.cover.no1": "Đòn bằng lá chủ phải chặn bằng lá chủ lớn hơn - lá 7 này nhỏ quá.",
            "ios.rules.cover.no2": "Hạng lớn hơn nhưng sai chất - không chặn được gì.",
            "ios.rules.throw.h": "Ném thêm bài",
            "ios.rules.throw.b": "Trong lúc người đỡ đang chặn, mọi người chơi khác đều có thể “ném thêm” bài tấn công mà người đỡ phải chặn nốt. Luật thì đơn giản nhưng phải một lúc mới ngấm: nếu bạn thấy HẠNG của một lá bạn đang cầm (ví dụ A, 6, 10) đã có trên bàn, và bạn thuộc bên tấn công, bạn được đặt lá đó xuống thành một đòn tấn công mới. Đừng bận tâm chút nào về chất. Giới hạn duy nhất là số bài hiện có trong tay người đỡ: số đòn chưa bị chặn trên bàn không được nhiều hơn số lá người đỡ đang cầm. Hãy hình dung người đỡ phải có một lá để đối lại mỗi lá tấn công; nếu bài tấn công quá nhiều thì điều đó là bất khả thi, nên không được phép. Bạn có thể thắc mắc liệu như vậy số bài tấn công có nhân lên rất nhanh không. Đúng vậy, và đó chính là cái hay của trò này. Để ném thêm, chạm một lá hoặc một bộ lá mà hạng của từng lá đều đã có trên bàn, rồi bấm tấn công. Hoặc kéo bài từ tay ra bàn.",
            "ios.rules.throw.ok1": "Trên bàn có lá 9, nên lá 9 của bạn ném vào được - chất không quan trọng.",
            "ios.rules.throw.ok2": "Cả hai lá 6 cùng lúc - hai đòn tấn công mới.",
            "ios.rules.throw.ok3": "Hoặc lá 6 với lá 9 cùng lúc - hạng nào cũng đã có sẵn trên bàn.",
            "ios.rules.throw.no1": "Trên bàn không có 8 cũng không có J - không có gì để ném vào.",
            "ios.rules.throw.no2": "Người đỡ còn một lá và đã có một đòn đang chờ - không còn chỗ cho đòn nào nữa.",
            "ios.rules.pickup.h": "Bốc bài",
            "ios.rules.pickup.b": "Nếu người đỡ không chặn nổi hết hoặc không muốn chặn, họ có thể bấm nút bốc. Khi đó người đỡ lấy hết bài trên bàn về tay, kể cả những lá đã bị phủ. Và lượt của họ bị bỏ qua, nên vòng sau người bên trái họ sẽ mở đòn. Vậy nên hãy cân nhắc kỹ trước khi bốc.",
            "ios.rules.pickup.cap": "Bốc ở đây thì cả ba lá đều về tay bạn - kể cả cặp đã bị phủ.",
            "ios.rules.round.h": "Hết vòng",
            "ios.rules.round.b": "Khi mọi lá đã bị chặn và không ai còn muốn ném thêm, toàn bộ bài trên bàn đi vào chỗ bài bỏ. Sau đó mọi người rút bài, bắt đầu từ người mở vòng rồi theo chiều kim đồng hồ qua hết bên tấn công, rút cho tới khi có ít nhất 6 lá. Người đỡ rút sau cùng. Việc này ứng dụng tự làm. Khi nọc đã cạn, mọi người bắt đầu đánh hết bài của mình để khỏi thành kẻ ngốc. Vòng cũng kết thúc nếu người đỡ chọn bốc; khi đó bên tấn công vẫn rút bài như trên.",
            "ios.rules.pass.h": "Chuyển đòn",
            "ios.rules.pass.b": "Ở ván có luật переводной, tức là “chuyển đòn”, người đỡ còn một lựa chọn nữa: đẩy đòn tấn công sang người bên trái mình. Muốn vậy, trên bàn chưa được có lá nào bị phủ, và họ phải có một lá CÙNG HẠNG với tất cả các lá tấn công đang trên bàn. Đặt lá đó xuống là biểu tượng khiên đi theo chiều kim đồng hồ sang người bên trái. Tuy nhiên, giống như có giới hạn về số lá tấn công, không được đẩy đòn nếu người bên trái cầm ít bài hơn số đòn sẽ có sau đó. Ví dụ, nếu trên bàn đã có hai lá tấn công và người bên trái chỉ cầm hai lá thì không được, vì sau đó bàn sẽ có ít nhất ba đòn (2 lá cũ cộng 1 lá vừa đặt), nhiều hơn số bài họ cầm. Để làm việc này, chạm lá cùng hạng rồi bấm nút chuyển, hoặc kéo lá cùng hạng ra chỗ trống trên bàn.",
            "ios.rules.pass.ok1": "Trên bàn là lá 8 và bạn cũng có lá 8 - đặt xuống là cái khiên đi tiếp.",
            "ios.rules.pass.no1": "Đã có lá bị phủ rồi - không chuyển đòn được nữa.",
            "ios.rules.pass.no2": "Trong tay không có lá 8 - đòn này bạn phải tự đỡ.",
            "ios.rules.pass.no3": "Làm vậy sẽ thành ba đòn, mà người kế tiếp chỉ cầm hai lá.",
            "ios.rules.end.h": "Kết thúc ván",
            "ios.rules.end.b": "Khi nọc đã cạn, ván vẫn tiếp tục. Ai đánh hết bài thì thoát, không phải là kẻ ngốc. Người cuối cùng còn cầm bài chính là kẻ ngốc.",
            "ios.rules.lobby.h": "Phòng chờ hoạt động thế nào",
            "ios.rules.lobby.b": "Thêm tên của bạn để vào. Khi đã có ít nhất hai người, ai cũng có thể bấm Bắt đầu. Sau khi ván bắt đầu thì không ai vào được nữa.",
            "ios.rules.variant.h": "Chuyển đòn",
            "ios.rules.variant.b": "Phòng chờ quyết định bàn này chơi kiểu Durak nào, và ô đánh dấu cho biết là kiểu nào. Có dấu tích là ván có chuyển đòn (переводной): người đỡ nếu cầm lá cùng hạng với đòn tấn công thì được đặt xuống và đẩy cả đòn sang người kế tiếp, và giờ người đó phải đỡ. Bỏ dấu tích là ván ném thêm (подкидной): không có lựa chọn đó, nên người đỡ phải chặn hết mọi lá trên bàn hoặc bốc tất cả lên. Khi phòng chờ còn mở, ai ngồi ở bàn cũng đổi được; ván bắt đầu là cố định.",
            "ios.rules.fool.h": "Kẻ ngốc phải trả giá",
            "ios.rules.fool.b": "Bình thường lá chủ nhỏ nhất quyết định ai tấn công trước. Có đúng một ngoại lệ, và đó là kiểu công lý Durak xưa nhất: nếu bạn bấm Ván mới sau khi một ván kết thúc và đúng những người đó lại ngồi vào, thì lá chủ nhỏ nhất chẳng quyết định gì cả. Người ngồi bên phải kẻ ngốc của ván trước sẽ mở đòn, nghĩa là kẻ ngốc bị tấn công đầu tiên. Thua là ván sau đánh thẳng vào bạn. Nếu có ai vào hoặc rời đi trước khi bấm Bắt đầu thì bàn đã khác, và luật thường quay lại.",
            "ios.lobby.passing": "Chuyển đòn",
