            "ios.tut_1": "Chào mừng đến với Durak. Lá nhỏ nhất của chất chủ quyết định ai tấn công trước. Lá chủ chặn được mọi chất khác.",
            "ios.tut_2": "Để tấn công, chạm một lá trong tay. Đối thủ phải chặn được nó - hoặc bốc hết lên.",
            "ios.tut_3": "Để đỡ, chạm một lá của bạn rồi chạm vào đòn mà nó chặn. Lá cùng chất lớn hơn, hoặc một lá chủ bất kỳ, đều phủ được.",
            "ios.tut_4": "Không chặn được hoặc không muốn chặn? Bấm Bốc để ôm hết bài lên. Không tấn công nữa? Bấm Xong.",
            "ios.tut_5": "Hãy đánh hết bài trước mọi người. Người cuối cùng còn cầm bài là kẻ ngốc. Chúc may mắn!",
