            "ios.rej.mustattack": "El primer atacante tiene que atacar.",
            "ios.rej.alreadygood": "Ya dijiste listo.",
            "ios.rej.notake": "No hay nada que recoger.",
            "ios.help": "Reglas",
            "ios.settings.title": "Ajustes",
            "ios.settings.table": "Mesa",
            "ios.settings.table.wool": "Lana",
            "ios.settings.table.felt": "Paño verde",
            "ios.rules.title": "Cómo se juega",
            "ios.rules.goal.h": "El objetivo",
            "ios.rules.goal.b": "El objetivo del juego es quedarte sin cartas lo antes posible. Quien se quede con cartas al final es el дурак, el tonto en ruso.",
            "ios.rules.setup.h": "Preparación",
            "ios.rules.setup.b": "Con cuatro jugadores o menos se juega solo con las cartas del 6 al As. Los 2, 3, 4 y 5 se retiran. El As es la carta más alta. Cada jugador recibe 6 cartas; luego se saca una carta más, se pone boca arriba y se coloca debajo del mazo. El PALO de esa carta es el palo de triunfo. Ese palo es especial, y se explica en la defensa.",
            "ios.rules.setup.cap": "Una carta se pone boca arriba bajo el mazo - su palo es el triunfo. Corazones, en todos los ejemplos de esta página.",
            "ios.rules.start.h": "Comienzo",
            "ios.rules.start.b": "Empieza quien tenga el triunfo más bajo. En una partida presencial se averigua preguntando quién tiene el 6, luego el 7, y así. Aquí lo hace el juego solo. Esa persona es el primer atacante de la ronda.",
            "ios.rules.sword": "La espada marca al atacante que abre la ronda.",
            "ios.rules.shield": "El escudo marca al defensor.",
            "ios.rules.attack.h": "Atacar",
            "ios.rules.attack.b": "El primer atacante de la ronda, marcado con una espada, puede elegir cualquier carta - o cualquier conjunto de cartas del mismo VALOR - de su mano y colocarla en la mesa, frente al jugador de su izquierda (sentido horario). Ese jugador pasa a ser el defensor, marcado con un escudo, y tiene que resolver el ataque. Para atacar, toca las cartas para seleccionarlas y pulsa el botón de ataque que aparece cuando la selección es una jugada válida. O simplemente arrastra cartas de tu mano a la mesa.",
            "ios.rules.attack.ok1": "Este jugador puede atacar con su Reina.",
            "ios.rules.attack.ok2": "También puede atacar con los dos Reyes a la vez, porque tienen el mismo valor.",
            "ios.rules.attack.no1": "NO puede atacar con su 7 y su 10, porque son valores distintos.",
            "ios.rules.defend.h": "Defender",
            "ios.rules.defend.b": "El jugador atacado, marcado con el escudo, es el defensor. Solo hay un defensor a la vez, y todas las cartas que pongan los demás son suyas para resolver. El defensor solo puede cubrir, llevarse las cartas o pasar (si está permitido). El defensor NO PUEDE atacar. Todos los demás son atacantes y solo pueden atacar. Los atacantes NO PUEDEN cubrir ninguna carta de la mesa.",
            "ios.rules.defend.b.nopass": "El jugador atacado, marcado con el escudo, es el defensor. Solo hay un defensor a la vez, y todas las cartas que pongan los demás son suyas para resolver. El defensor solo puede cubrir o llevarse las cartas. El defensor NO PUEDE atacar. Todos los demás son atacantes y solo pueden atacar. Los atacantes NO PUEDEN cubrir ninguna carta de la mesa.",
            "ios.rules.cover.h": "Cubrir",
            "ios.rules.cover.b": "El defensor puede cubrir las cartas de la mesa tapando cada una con una carta más alta del mismo palo, o con cualquier triunfo. Eso es lo que hace especial al palo de triunfo. Para cubrir, selecciona una carta y pulsa el botón de cubrir. También puedes arrastrar una carta de tu mano hasta la carta que quieres cubrir. Un error común es creer que una carta ya cubierta se puede volver a cubrir con una tercera. El juego no funciona así. Nunca verás montones de tres en la mesa. Piensa en la carta de ataque como una espada y en la carta de defensa como un escudo: el ataque queda bloqueado y terminado. Solo se pueden hacer ataques nuevos, en montones aparte.",
            "ios.rules.cover.ok1": "Una carta más alta del mismo palo cubre.",
            "ios.rules.cover.ok2": "Cualquier triunfo cubre cualquier otro palo - incluso con un valor menor.",
            "ios.rules.cover.no1": "Un ataque de triunfo necesita un triunfo más alto - este 7 se queda corto.",
            "ios.rules.cover.no2": "Valor más alto, palo equivocado - eso no cubre nada.",
            "ios.rules.throw.h": "Sumar cartas",
            "ios.rules.throw.b": "Mientras el defensor cubre, cualquier otro jugador puede \"sumar\" cartas de ataque que el defensor también tendrá que cubrir. La regla es simple, aunque cuesta un poco captarla: si ves en la mesa el VALOR (por ejemplo A, 6, 10) de una carta que tienes, y eres atacante, puedes poner esa carta como un ataque nuevo aparte. Los palos NO IMPORTAN EN ABSOLUTO. El único límite es el número de cartas que el defensor tiene en la mano: los ataques sin cubrir en la mesa no pueden ser más que las cartas que sostiene. Imagina que el defensor tiene que poder responder a cada carta de ataque con una carta de defensa; si hay demasiados ataques, es físicamente imposible, y por eso no se permite. Quizá te preguntes si esto puede hacer que los ataques se multipliquen deprisa. Así es, y es parte de la gracia del juego. Para atacar, toca una carta - o un conjunto en el que cada carta tenga su valor ya en la mesa - y pulsa atacar. O arrastra las cartas de tu mano a la mesa.",
            "ios.rules.throw.ok1": "Hay un 9 en la mesa, así que tu 9 puede entrar - los palos dan igual.",
            "ios.rules.throw.ok2": "Los dos 6 a la vez - dos ataques nuevos.",
            "ios.rules.throw.ok3": "O el 6 y el 9 juntos - los dos valores ya están en la mesa.",
            "ios.rules.throw.no1": "No hay ningún 8 ni ninguna Jota en la mesa - no hay nada que sumar.",
            "ios.rules.throw.no2": "El defensor tiene una carta y ya hay un ataque esperando - no cabe otro.",
            "ios.rules.pickup.h": "Recoger las cartas",
            "ios.rules.pickup.b": "Si el defensor no puede cubrir todas las cartas, o no quiere, puede pulsar el botón Recoger. Entonces se lleva todas las cartas de la mesa, incluso las que ya estaban cubiertas. Además pierde su turno, así que el jugador de su izquierda empezará atacando en la ronda siguiente. Piénsalo bien antes de llevártelas.",
            "ios.rules.pickup.cap": "Si te las llevas aquí, las tres cartas van a tu mano - también la pareja cubierta.",
            "ios.rules.round.h": "Fin de ronda",
            "ios.rules.round.b": "Cuando todas las cartas están cubiertas y ningún atacante quiere sumar más, todo lo que hay en la mesa va al descarte. Después se roba empezando por el primer atacante y siguiendo en sentido horario por todos los atacantes, hasta completar 6 cartas. El defensor roba el último. El juego lo hace solo. Si el mazo se agota, los jugadores pueden empezar a quedarse sin cartas y librarse de ser el tonto. La ronda también termina si el defensor se lleva las cartas; los atacantes roban igualmente.",
            "ios.rules.pass.h": "Pasar",
            "ios.rules.pass.b": "En una partida donde se permite el переводной o \"pase\", el defensor tiene además la opción de pasar el ataque al jugador de su izquierda. Para eso no puede haber ninguna carta cubierta en la mesa, y tiene que tener una carta del mismo VALOR que todas las cartas de ataque. Entonces la pone en la mesa y el escudo se mueve en sentido horario al jugador de su izquierda. Ahora bien, igual que hay un límite para atacar, no se puede pasar si el jugador de la izquierda tiene menos cartas de las que habría en la mesa después del pase. Por ejemplo: si hay dos ataques en la mesa y el jugador de la izquierda tiene dos cartas, no se puede pasar, porque el pase dejaría al menos 3 cartas (2 más la que se pasa). Eso es más de lo que sostiene, y por tanto no se permite. Para pasar, toca la carta del valor que coincide y pulsa el botón de pasar. O arrastra esa carta a un hueco libre de la mesa.",
            "ios.rules.pass.ok1": "Te atacan con un 8 y tienes un 8 - ponlo y el escudo sigue adelante.",
            "ios.rules.pass.no1": "Ya hay algo cubierto - es tarde para pasar.",
            "ios.rules.pass.no2": "No tienes ningún 8 - este ataque te toca defenderlo.",
            "ios.rules.pass.no3": "Pasar dejaría tres ataques, y el jugador siguiente solo tiene dos cartas.",
            "ios.rules.end.h": "Fin de la partida",
            "ios.rules.end.b": "Cuando el mazo se vacía, la partida continúa. Quien se queda sin cartas se salva de ser el tonto. El último jugador que aún tiene cartas es el tonto.",
            "ios.rules.lobby.h": "Cómo funciona la sala",
            "ios.rules.lobby.b": "Añade tu nombre para entrar. Cuando haya al menos dos jugadores, cualquiera puede pulsar Empezar a jugar. Una vez empezada la partida, ya no entra nadie más.",
            "ios.rules.variant.h": "Pasar",
            "ios.rules.variant.b": "La sala decide a qué Durak juega esta mesa, y la casilla dice cuál. Si está marcada, se juega con pase (perevodnoy): un defensor con una carta del mismo valor que el ataque puede ponerla y pasar todo el ataque al jugador siguiente, que ahora tiene que defenderse. Si está sin marcar, se juega a sumar cartas (podkidnoy): no hay pase, así que el defensor cubre todas las cartas de la mesa o se las lleva. Cualquiera en la mesa puede cambiarlo mientras la sala está abierta; en cuanto empieza la partida queda fijado.",
            "ios.rules.fool.h": "El tonto lo paga",
            "ios.rules.fool.b": "Normalmente el triunfo más bajo decide quién ataca primero. Hay una excepción, y es la clase más antigua de justicia del Durak: si pulsas Nueva partida al terminar una y se sientan exactamente los mismos jugadores, el triunfo más bajo no decide nada. Abre el jugador que está a la derecha del último tonto, lo que significa que el tonto es el primero en ser atacado. Si pierdes, la siguiente partida te llega directa. Si alguien entra o sale antes de Empezar, la mesa es otra y vuelve la regla normal.",
            "ios.lobby.passing": "Con pase",
