            "ios.rej.addrank": "Você só pode acrescentar um valor que já esteja na mesa.",
            "ios.rej.cover": "Isso não cobre - use uma carta mais alta do mesmo naipe, ou um trunfo.",
            "ios.rej.capacity": "Ataques demais para a mão do defensor.",
            "ios.rej.passrank": "Você só pode passar com uma carta do mesmo valor.",
            "ios.rej.mustattack": "O primeiro atacante tem que atacar.",
            "ios.rej.alreadygood": "Você já disse pronto.",
            "ios.rej.notake": "Não há nada para pegar.",
            "ios.help": "Regras",
            "ios.settings.title": "Ajustes",
            "ios.settings.table": "Mesa",
            "ios.settings.table.wool": "Lã",
            "ios.settings.table.felt": "Feltro verde",
            "ios.rules.title": "Como jogar",
            "ios.rules.goal.h": "O objetivo",
            "ios.rules.goal.b": "O objetivo do jogo é livrar-se de todas as suas cartas o mais rápido possível. Quem ficar com cartas no fim é o дурак, o bobo em russo.",
            "ios.rules.setup.h": "Preparação",
            "ios.rules.setup.b": "Com quatro jogadores ou menos, joga-se apenas com as cartas do 6 ao Ás. Os 2, 3, 4 e 5 saem do jogo. O Ás é a carta mais alta. Cada jogador recebe 6 cartas; depois mais uma carta é tirada, virada para cima e colocada sob o monte de compra. O NAIPE dessa carta virada é o naipe de trunfo. Esse naipe é especial, e será explicado na defesa.",
            "ios.rules.setup.cap": "Uma carta fica virada sob o monte - o naipe dela é o trunfo. Copas, em todos os exemplos desta página.",
            "ios.rules.start.h": "Começo do jogo",
            "ios.rules.start.b": "Começa quem tiver o trunfo mais baixo. Em partidas presenciais pergunta-se quem tem o 6, depois o 7, e assim por diante. Aqui o jogo faz isso sozinho. Essa pessoa é o primeiro atacante da rodada.",
            "ios.rules.sword": "A espada marca o atacante que abre a rodada.",
            "ios.rules.shield": "O escudo marca o defensor.",
            "ios.rules.attack.h": "Atacando",
            "ios.rules.attack.b": "O primeiro atacante da rodada, marcado por uma espada, pode escolher qualquer carta - ou qualquer conjunto de cartas do mesmo VALOR - da sua mão e colocá-la diante do jogador à sua esquerda (sentido horário). Esse jogador passa a ser o defensor, marcado por um escudo, e precisa resolver o ataque. Para atacar, toque nas cartas para selecioná-las e aperte o botão de ataque que aparece quando a seleção é uma jogada válida. Ou simplesmente arraste cartas da sua mão para a mesa.",
            "ios.rules.attack.ok1": "Este jogador pode atacar com a Dama.",
            "ios.rules.attack.ok2": "Também pode atacar com os dois Reis ao mesmo tempo, já que têm o mesmo valor.",
            "ios.rules.attack.no1": "NÃO pode atacar com o 7 e o 10 juntos, porque são valores diferentes.",
            "ios.rules.defend.h": "Defendendo",
            "ios.rules.defend.b": "O jogador sob ataque, marcado pelo escudo, é o defensor. Só existe um defensor por vez, e todas as cartas colocadas pelos outros são cartas que o defensor tem de resolver. O defensor só pode cobrir, pegar as cartas ou passar (se for permitido). O defensor NÃO PODE atacar. Todos os outros são atacantes e só podem atacar. Os atacantes NÃO PODEM cobrir nenhuma carta da mesa.",
            "ios.rules.defend.b.nopass": "O jogador sob ataque, marcado pelo escudo, é o defensor. Só existe um defensor por vez, e todas as cartas colocadas pelos outros são cartas que o defensor tem de resolver. O defensor só pode cobrir ou pegar as cartas. O defensor NÃO PODE atacar. Todos os outros são atacantes e só podem atacar. Os atacantes NÃO PODEM cobrir nenhuma carta da mesa.",
            "ios.rules.cover.h": "Cobrindo",
            "ios.rules.cover.b": "O defensor cobre as cartas da mesa tapando cada uma com uma carta mais alta do mesmo naipe, ou com qualquer trunfo. É isso que torna o naipe de trunfo especial. Para cobrir, selecione uma carta e toque o botão de cobrir. Ou arraste uma carta da sua mão até a carta que quer cobrir na mesa. Um erro comum é achar que uma carta já coberta pode ser coberta de novo por uma terceira. Não é assim que o jogo funciona. Você nunca verá pilhas de três na mesa. Pense na carta de ataque como uma espada e na de cobertura como um escudo: o ataque foi bloqueado, e portanto encerrado. Só é possível fazer ataques novos, em pilhas separadas.",
            "ios.rules.cover.ok1": "Uma carta mais alta do mesmo naipe cobre.",
            "ios.rules.cover.ok2": "Qualquer trunfo cobre qualquer outro naipe - mesmo com valor menor.",
            "ios.rules.cover.no1": "Um ataque de trunfo exige um trunfo mais alto - este 7 é baixo demais.",
            "ios.rules.cover.no2": "Valor mais alto, naipe errado - isso não cobre nada.",
            "ios.rules.throw.h": "Jogando junto",
            "ios.rules.throw.b": "Enquanto o defensor cobre, qualquer outro jogador pode \"jogar junto\" cartas de ataque extras que o defensor também terá de cobrir. A regra é simples, mas leva um tempo para cair a ficha. Se você vir na mesa o VALOR (por exemplo A, 6, 10) de uma carta que tem na mão, e você for atacante, pode colocar essa carta como um ataque novo e separado. Não se preocupe com os naipes NEM UM POUCO. O único limite é o número de cartas que o defensor tem na mão: os ataques descobertos na mesa não podem ser mais do que as cartas que ele segura. Imagine que o defensor precisa responder a cada carta de ataque com uma carta de defesa; se houver ataques demais, isso é fisicamente impossível, e por isso não é permitido. Talvez você se pergunte se isso pode fazer o número de ataques se multiplicar depressa. Pode mesmo, e faz parte da graça do jogo. Para atacar, toque numa carta - ou um conjunto em que cada carta tenha seu valor já na mesa - e aperte atacar. Ou arraste cartas da sua mão para a mesa.",
            "ios.rules.throw.ok1": "Há um 9 na mesa, então o seu 9 pode entrar - os naipes não importam.",
            "ios.rules.throw.ok2": "Os dois 6 de uma vez - dois ataques novos.",
            "ios.rules.throw.ok3": "Ou o 6 e o 9 juntos - os dois valores já estão lá.",
            "ios.rules.throw.no1": "Não há 8 nem Valete na mesa - não há o que jogar junto.",
            "ios.rules.throw.no2": "O defensor tem uma carta e já existe um ataque esperando - não cabe outro.",
            "ios.rules.pickup.h": "Pegando as cartas",
            "ios.rules.pickup.b": "Se o defensor não conseguir cobrir todas as cartas, ou não quiser, pode apertar o botão de pegar. Isso faz o defensor recolher todas as cartas da mesa, mesmo as que já estavam cobertas. E ele perde a vez, então quem está à sua esquerda começa atacando na rodada seguinte. Pense bem antes de pegar.",
            "ios.rules.pickup.cap": "Pegue aqui e as três cartas vão para a sua mão - inclusive o par já coberto.",
            "ios.rules.round.h": "Fim da rodada",
            "ios.rules.round.b": "Quando todas as cartas estiverem cobertas e nenhum atacante quiser jogar mais nada, tudo o que está na mesa vai para o descarte. Depois os jogadores compram, começando pelo primeiro atacante e seguindo no sentido horário por todos os atacantes, até completarem 6 cartas. O defensor compra por último. O jogo faz isso sozinho. Se o monte acabar, os jogadores podem começar a se livrar das cartas e escapar de ser o bobo. A rodada também termina se o defensor pegar as cartas; os atacantes compram do mesmo jeito.",
            "ios.rules.pass.h": "Passando",
            "ios.rules.pass.b": "Numa partida em que o переводной, ou \"passe\", é permitido, o defensor também pode passar o ataque adiante, para o jogador à sua esquerda. Para isso, nenhuma carta da mesa pode estar coberta, e ele precisa ter uma carta do mesmo VALOR de todas as cartas de ataque na mesa. Então ele coloca essa carta e o ícone de defensor anda no sentido horário para o jogador à esquerda. Só que, do mesmo jeito que existe um limite para atacar, o passe não é permitido se o jogador à esquerda tiver menos cartas do que haveria ataques depois do passe. Por exemplo: se há dois ataques na mesa e o jogador à esquerda tem duas cartas, passar é impossível, porque o passe deixaria pelo menos 3 cartas (2 mais 1 do passe). Isso é mais do que ele segura, e portanto não é permitido. Para passar, toque a carta de valor igual e aperte o botão de passar. Ou arraste essa carta para um espaço vazio da mesa.",
            "ios.rules.pass.ok1": "Um 8 está atacando e você tem um 8 - coloque-o e o escudo segue adiante.",
            "ios.rules.pass.no1": "Já há uma carta coberta - tarde demais para passar.",
            "ios.rules.pass.no2": "Nenhum 8 na sua mão - este é seu para defender.",
            "ios.rules.pass.no3": "Passar deixaria três ataques, e o próximo jogador só tem duas cartas.",
            "ios.rules.end.h": "Fim do jogo",
            "ios.rules.end.b": "Depois que o monte acaba, o jogo continua. Quem fica sem cartas está a salvo de ser o bobo. O último jogador que ainda tiver cartas vira o bobo.",
            "ios.rules.lobby.h": "Como funciona a sala",
            "ios.rules.lobby.b": "Coloque seu nome para entrar. Assim que pelo menos dois jogadores entrarem, qualquer um pode apertar Começar. Depois que a partida começa, ninguém mais entra.",
            "ios.rules.variant.h": "Passe",
            "ios.rules.variant.b": "A sala escolhe qual Durak esta mesa joga, e a caixinha diz qual. Marcada é o jogo com passe (perevodnoy): um defensor com uma carta do mesmo valor do ataque pode colocá-la e passar o ataque inteiro ao próximo jogador, que agora precisa defendê-lo. Desmarcada é o jogo de jogar junto (podkidnoy): não há passe, então o defensor cobre todas as cartas da mesa ou pega tudo. Qualquer um na mesa pode mudar isso enquanto a sala está aberta; assim que a partida começa, fica fixo.",
            "ios.rules.fool.h": "O bobo paga por isso",
            "ios.rules.fool.b": "Normalmente o trunfo mais baixo decide quem ataca primeiro. Há uma exceção, e é o tipo mais antigo de justiça do Durak: se você apertar Nova partida quando uma acaba e exatamente os mesmos jogadores se sentarem de novo, o trunfo mais baixo não decide nada. Quem abre é o jogador à direita do último bobo, o que significa que o bobo é o primeiro a ser atacado. Perdeu, e a próxima partida vem direto para cima de você. Se alguém entrar ou sair antes de Começar, a mesa mudou e a regra normal volta.",
            "ios.lobby.passing": "Com passe",
            "ios.rules.lbl.table": "na mesa",
            "ios.rules.lbl.hand": "sua mão",
            "ios.rules.defender": "Defensor",
            "ios.rules.nextplayer": "Próximo jogador",
