            "ios.rej.notake": "Il n'y a rien à ramasser.",
            "ios.help": "Règles",
            "ios.settings.title": "Réglages",
            "ios.settings.table": "Tapis",
            "ios.settings.table.wool": "Laine",
            "ios.settings.table.felt": "Feutre vert",
            "ios.rules.title": "Comment jouer",
            "ios.rules.goal.h": "Le but",
            "ios.rules.goal.b": "Le but du jeu est de se débarrasser de toutes ses cartes le plus vite possible. Celui à qui il reste des cartes à la fin est le дурак, l’idiot en russe.",
            "ios.rules.setup.h": "Mise en place",
            "ios.rules.setup.b": "À quatre joueurs ou moins, on joue uniquement avec les cartes du 6 à l’As. Les 2, 3, 4 et 5 sont retirés du jeu. L’As est la carte la plus forte. Chaque joueur reçoit 6 cartes, puis une carte de plus est tirée, retournée face visible et glissée sous la pioche. La COULEUR de cette carte retournée donne la couleur d’atout. Cette couleur est particulière, et c’est expliqué dans la défense.",
            "ios.rules.setup.cap": "Une carte est retournée sous la pioche - sa couleur est l'atout. Dans tous les exemples de cette page, l'atout est à cœur.",
            "ios.rules.start.h": "Début de partie",
            "ios.rules.start.b": "Celui qui détient le plus petit atout commence. Autour d'une vraie table, on le détermine en demandant qui a un 6, puis un 7, et ainsi de suite. Ici, le jeu le fait tout seul. Cette personne est le premier attaquant de la manche.",
            "ios.rules.sword": "L'épée désigne l'attaquant qui ouvre la manche.",
            "ios.rules.shield": "Le bouclier désigne le défenseur.",
            "ios.rules.attack.h": "Attaquer",
            "ios.rules.attack.b": "Le premier attaquant de la manche, marqué d’une épée, peut choisir dans sa main n’importe quelle carte - ou n’importe quel groupe de cartes de même VALEUR - et les poser devant le joueur à sa gauche (sens horaire). Ce joueur devient le défenseur, marqué d’un bouclier, et doit répondre à l’attaque. Pour attaquer, touche les cartes pour les sélectionner et appuie sur le bouton Attaquer qui apparaît quand la sélection forme un coup valide. Ou fais simplement glisser des cartes de ta main vers la table.",
            "ios.rules.attack.ok1": "Ce joueur peut attaquer avec sa Dame.",
            "ios.rules.attack.ok2": "Il peut aussi attaquer avec ses deux Rois en même temps, puisqu’ils ont la même valeur.",
            "ios.rules.attack.no1": "Il ne peut PAS attaquer avec son 7 et son 10, car ce sont des valeurs différentes.",
            "ios.rules.defend.h": "Défendre",
            "ios.rules.defend.b": "Le joueur attaqué, marqué du bouclier, est le défenseur. Il n’y a qu’un défenseur à la fois, et toutes les cartes posées par les autres sont des cartes dont il doit s’occuper. Le défenseur peut seulement couvrir, ramasser, ou transférer (si c’est autorisé). Le défenseur NE PEUT PAS attaquer. Tous les autres sont attaquants et ne peuvent qu’attaquer. Les attaquants NE PEUVENT PAS couvrir de carte sur la table.",
            "ios.rules.defend.b.nopass": "Le joueur attaqué, marqué du bouclier, est le défenseur. Il n’y a qu’un défenseur à la fois, et toutes les cartes posées par les autres sont des cartes dont il doit s’occuper. Le défenseur peut seulement couvrir ou ramasser. Le défenseur NE PEUT PAS attaquer. Tous les autres sont attaquants et ne peuvent qu’attaquer. Les attaquants NE PEUVENT PAS couvrir de carte sur la table.",
            "ios.rules.cover.h": "Couvrir",
            "ios.rules.cover.b": "Le défenseur couvre les cartes de la table en posant sur chacune soit une carte plus forte de la même couleur, soit n’importe quel atout - un atout, lui, ne se couvre que par un atout plus fort. C’est ce qui rend la couleur d’atout particulière. Pour couvrir, sélectionne une carte et touche le bouton Couvrir. Tu peux aussi faire glisser une carte de ta main sur la carte à couvrir. Une erreur fréquente est de croire qu’une carte déjà couverte peut l’être encore par une troisième. Le jeu ne marche pas comme ça : tu ne verras jamais de pile de trois sur la table. Imagine la carte d’attaque comme une épée, et la carte qui couvre comme un bouclier : l’attaque est bloquée, donc terminée. Seules de nouvelles attaques sont possibles, dans des piles séparées.",
            "ios.rules.cover.ok1": "Une carte plus forte de la même couleur couvre.",
            "ios.rules.cover.ok2": "N'importe quel atout couvre une carte d'une autre couleur - même s'il est plus faible.",
            "ios.rules.cover.no1": "Une attaque à l’atout exige un atout plus fort - ce 7 est trop faible.",
            "ios.rules.cover.no2": "Valeur plus forte, mauvaise couleur - ça ne couvre rien.",
            "ios.rules.throw.h": "Ajouter des cartes",
            "ios.rules.throw.b": "Pendant que le défenseur couvre, tous les autres joueurs peuvent « ajouter » des cartes d’attaque supplémentaires que le défenseur devra couvrir en plus. La règle est simple, même si elle demande un peu de temps à assimiler. Si tu vois sur la table la VALEUR (par exemple A, 6, 10) d’une carte que tu as en main, et que tu es attaquant, tu peux poser cette carte comme une nouvelle attaque séparée. Ne te soucie PAS DU TOUT des couleurs. La seule limite est le nombre de cartes actuellement dans la main du défenseur : les attaques non couvertes sur la table ne peuvent pas être plus nombreuses que les cartes qu’il tient. Imagine que le défenseur doit pouvoir répondre à chaque carte d’attaque par une carte de défense ; s’il y a trop d’attaques, c’est physiquement impossible, donc interdit. Tu te demandes peut-être si le nombre d’attaques peut se multiplier très vite. C’est bien le cas, et cela fait partie du plaisir du jeu. Pour attaquer, touche une carte - ou un groupe dont chaque carte a sa valeur déjà sur la table - et appuie sur Attaquer. Tu peux aussi faire glisser des cartes de ta main vers la table.",
            "ios.rules.throw.ok1": "Il y a un 9 sur la table, donc ton 9 peut y aller - les couleurs n’ont pas d’importance.",
            "ios.rules.throw.ok2": "Les deux 6 d’un coup - deux nouvelles attaques.",
            "ios.rules.throw.ok3": "Ou le 6 et le 9 ensemble - chacune de ces valeurs est déjà sur la table.",
            "ios.rules.throw.no1": "Pas de 8 ni de Valet sur la table - rien à ajouter.",
            "ios.rules.throw.no2": "Le défenseur tient une carte et une attaque attend déjà - pas de place pour une autre.",
            "ios.rules.pickup.h": "Ramasser",
            "ios.rules.pickup.b": "Si le défenseur ne peut pas couvrir toutes les cartes, ou ne le veut pas, il peut appuyer sur le bouton Ramasser. Il ramasse alors toutes les cartes de la table, même celles déjà couvertes. Et son tour est sauté : le joueur à sa gauche ouvrira l’attaque à la manche suivante. Réfléchis bien avant de ramasser.",
            "ios.rules.pickup.cap": "Ramasse ici et les trois cartes rejoignent ta main - la paire couverte comprise.",
            "ios.rules.round.h": "Fin de la manche",
            "ios.rules.round.b": "Quand toutes les cartes sont couvertes et que plus aucun attaquant ne veut en ajouter, toutes les cartes de la table partent à la défausse. Les joueurs piochent ensuite en commençant par le premier attaquant, dans le sens horaire à travers tous les attaquants, jusqu’à avoir au moins 6 cartes. Le défenseur pioche en dernier. Le jeu le fait automatiquement. Quand la pioche est épuisée, les joueurs peuvent commencer à se débarrasser de leurs cartes et éviter d’être l’idiot. Le tour se termine aussi si le défenseur ramasse ; les attaquants piochent alors de la même façon.",
            "ios.rules.pass.h": "Transférer",
            "ios.rules.pass.b": "Dans une partie où le переводной, le « transfert », est autorisé, le défenseur a aussi la possibilité de renvoyer l’attaque au joueur à sa gauche. Pour cela, aucune carte de la table ne doit être couverte, et il doit posséder une carte de la même VALEUR que toutes les cartes d’attaque présentes. Il la pose alors, et le bouclier passe dans le sens horaire au joueur à sa gauche. Cependant, tout comme il y a une limite au nombre de cartes d’attaque, le transfert est impossible si le joueur de gauche a moins de cartes qu’il n’y aurait d’attaques après le transfert. Par exemple, s’il y a deux attaques sur la table et que le joueur de gauche tient deux cartes, le transfert est impossible : il y aurait alors au moins 3 attaques sur la table (les 2 déjà posées, plus la carte du transfert). C’est plus que ce qu’il tient, donc interdit. Pour transférer, touche la carte de valeur identique et appuie sur le bouton Transférer. Ou fais glisser cette carte vers un emplacement libre de la table.",
            "ios.rules.pass.ok1": "Un 8 attaque et tu as un 8 - pose-le et le bouclier passe au suivant.",
            "ios.rules.pass.no1": "Quelque chose est déjà couvert - trop tard pour transférer.",
            "ios.rules.pass.no2": "Pas de 8 dans ta main - celle-ci, c’est à toi de la défendre.",
            "ios.rules.pass.no3": "Le transfert ferait trois attaques, et le joueur suivant ne tient que deux cartes.",
            "ios.rules.end.h": "Fin de partie",
            "ios.rules.end.b": "Une fois la pioche vide, la partie continue. Celui qui se débarrasse de toutes ses cartes ne peut plus être l’idiot. Le dernier joueur à qui il reste des cartes devient l’idiot.",
            "ios.rules.lobby.h": "Comment marche le salon",
            "ios.rules.lobby.b": "Ajoute ton nom pour rejoindre. Dès que deux joueurs au moins ont rejoint, n’importe qui peut appuyer sur Lancer la partie. Une fois la partie commencée, plus personne ne peut rejoindre.",
            "ios.rules.variant.h": "Transfert",
            "ios.rules.variant.b": "Le salon choisit à quel Durak cette table joue, et la case ci-dessous indique lequel. Cochée, c’est le jeu avec transfert (perevodnoï) : un défenseur qui tient une carte de même valeur que l’attaque peut la poser et renvoyer toute l’attaque au joueur suivant, qui doit maintenant la défendre. Décochée, c’est le jeu avec ajout de cartes (podkidnoï) : pas de transfert, donc le défenseur couvre toutes les cartes de la table ou ramasse tout. N’importe qui à la table peut le changer tant que le salon est ouvert ; dès que la partie commence, c’est figé.",
            "ios.rules.fool.h": "L’idiot paie l’addition",
            "ios.rules.fool.b": "Normalement, le plus petit atout décide qui attaque en premier. Il y a une exception, et c’est la plus vieille des justices du Durak : si tu appuies sur Nouvelle partie après la fin d’une partie et que ce sont exactement les mêmes joueurs qui se réinstallent, le plus petit atout ne décide rien. C’est le joueur assis à la droite du dernier idiot qui ouvre, ce qui veut dire que l’idiot est le premier attaqué. Si tu perds, la partie suivante te tombe dessus. Si quelqu’un entre ou sort avant Lancer la partie, la table a changé et la règle normale revient.",
            "ios.lobby.passing": "Avec transfert",
