        "de": [
            // German. `Trumpf`, `decken` for covering, `aufnehmen` for taking the
            // table, and `schieben` for passing - which is also why the `pass`
            // label is not the word Pass, which means something else at a German
            // card table.
            // Cards are named suit-first (Pik Ass), so `cardfmt` and `a11y.card`
            // reorder their placeholders. Durak is played widely enough in German
            // that the loser keeps a German name, `Dummkopf`.
