            "ios.rej.mustattack": "Der erste Angreifer muss angreifen.",
            "ios.rej.alreadygood": "Du hast schon „Fertig“ gesagt.",
            "ios.rej.notake": "Es gibt nichts zu nehmen.",
            "ios.help": "Regeln",
            "ios.settings.title": "Einstellungen",
            "ios.settings.table": "Tisch",
            "ios.settings.table.wool": "Wolle",
            "ios.settings.table.felt": "Grüner Filz",
            "ios.rules.title": "So wird gespielt",
            "ios.rules.goal.h": "Das Ziel",
            "ios.rules.goal.b": "Das Ziel des Spiels ist, so schnell wie möglich alle Karten loszuwerden. Wer am Ende noch Karten hat, ist der дурак - der Durak, russisch für den Dummen.",
            "ios.rules.setup.h": "Aufbau",
            "ios.rules.setup.b": "Bei vier oder weniger Spielern wird nur mit den Karten von der 6 bis zum Ass gespielt. Zweien, Dreien, Vieren und Fünfen kommen aus dem Spiel. Das Ass ist die höchste Karte. Jeder Spieler bekommt 6 Karten, dann wird eine weitere Karte gezogen, offen hingelegt und unter den Nachziehstapel geschoben. Die FARBE dieser offenen Karte ist die Trumpffarbe. Diese Farbe ist besonders, und das wird beim Verteidigen erklärt.",
            "ios.rules.setup.cap": "Auf dieser Seite ist in allen Beispielen Herz Trumpf.",
            "ios.rules.start.h": "Spielbeginn",
            "ios.rules.start.b": "Wer den niedrigsten Trumpf hat, fängt an. Am echten Tisch fragt man dazu, ob jemand eine 6 hat, dann eine 7, und so weiter. Hier macht das Spiel es selbst. Diese Person ist der erste Angreifer der Runde.",
            "ios.rules.sword": "Das Schwert kennzeichnet den Angreifer, der die Runde eröffnet.",
            "ios.rules.shield": "Der Schild kennzeichnet den Verteidiger.",
            "ios.rules.attack.h": "Angreifen",
            "ios.rules.attack.b": "Der erste Angreifer einer Runde, mit einem Schwert markiert, darf eine beliebige Karte - oder beliebig viele Karten mit demselben WERT - aus seiner Hand wählen und vor den Spieler links von sich legen (im Uhrzeigersinn). Dieser Spieler ist jetzt der Verteidiger, mit einem Schild markiert, und muss mit dem Angriff fertigwerden. Zum Angreifen tippst du Karten an, um sie auszuwählen, und drückst dann den Knopf „Angriff“, der erscheint, sobald die Auswahl ein gültiger Zug ist. Oder du ziehst die Karten einfach von deiner Hand auf den Tisch.",
            "ios.rules.attack.ok1": "Dieser Spieler darf mit seiner Dame angreifen.",
            "ios.rules.attack.ok2": "Er darf auch mit beiden Königen gleichzeitig angreifen, weil sie denselben Wert haben.",
            "ios.rules.attack.no1": "Er darf NICHT mit seiner 7 und seiner 10 angreifen, denn das sind verschiedene Werte.",
            "ios.rules.defend.h": "Verteidigen",
            "ios.rules.defend.b": "Der gerade angegriffene Spieler, mit dem Schild markiert, ist der Verteidiger. Es gibt immer nur einen Verteidiger, und alle Karten, die die anderen hinlegen, muss der Verteidiger fertigwerden. Der Verteidiger darf nur decken, aufnehmen oder schieben (wenn es erlaubt ist). Der Verteidiger DARF NICHT angreifen. Alle anderen sind Angreifer und dürfen nur angreifen. Angreifer DÜRFEN KEINE Karte auf dem Tisch decken.",
            "ios.rules.defend.b.nopass": "Der gerade angegriffene Spieler, mit dem Schild markiert, ist der Verteidiger. Es gibt immer nur einen Verteidiger, und alle Karten, die die anderen hinlegen, muss der Verteidiger fertigwerden. Der Verteidiger darf nur decken oder aufnehmen. Der Verteidiger DARF NICHT angreifen. Alle anderen sind Angreifer und dürfen nur angreifen. Angreifer DÜRFEN KEINE Karte auf dem Tisch decken.",
            "ios.rules.cover.h": "Decken",
            "ios.rules.cover.b": "Der Verteidiger deckt die Karten auf dem Tisch, indem er jede einzelne mit einer höheren Karte derselben Farbe oder mit einem beliebigen Trumpf belegt. Genau das macht die Trumpffarbe besonders. Zum Decken wählst du eine Karte aus und tippst den Knopf „Decken“. Oder du ziehst eine Karte von deiner Hand auf die Karte, die du decken willst. Ein häufiger Irrtum ist, dass eine bereits gedeckte Karte noch von einer dritten gedeckt werden könnte. So funktioniert das Spiel nicht. Du wirst nie Dreierstapel auf dem Tisch sehen. Stell dir die Angriffskarte als Schwert und die Deckkarte als Schild vor: Der Angriff ist abgewehrt und damit erledigt. Möglich sind nur neue Angriffe, in eigenen Stapeln.",
            "ios.rules.cover.ok1": "Eine höhere Karte derselben Farbe deckt.",
            "ios.rules.cover.ok2": "Jeder Trumpf deckt jede andere Farbe - auch mit niedrigerem Wert.",
            "ios.rules.cover.no1": "Ein Trumpfangriff braucht einen höheren Trumpf - diese 7 ist zu niedrig.",
            "ios.rules.cover.no2": "Höherer Wert, falsche Farbe - das deckt gar nichts.",
            "ios.rules.throw.h": "Mitgeben",
            "ios.rules.throw.b": "Während der Verteidiger deckt, darf jeder andere Spieler weitere Angriffskarten „mitgeben“, die der Verteidiger zusätzlich decken muss. Die Regel ist einfach, braucht aber einen Moment. Wenn du auf dem Tisch den WERT (etwa A, 6, 10) einer Karte siehst, die du auf der Hand hast, und du bist Angreifer, dann darfst du diese Karte als eigenen neuen Angriff dazulegen. Um die Farben musst du dich ÜBERHAUPT NICHT kümmern. Die einzige Grenze ist die Zahl der Karten, die der Verteidiger gerade hält: Es dürfen nie mehr ungedeckte Angriffe auf dem Tisch liegen, als er Karten hat. Stell dir vor, der Verteidiger muss jede Angriffskarte mit genau einer Verteidigungskarte beantworten können; bei zu vielen Angriffen ist das schlicht unmöglich und deshalb nicht erlaubt. Vielleicht fragst du dich, ob sich die Angriffe so schnell vervielfachen können. Ganz genau, und das gehört zum Reiz des Spiels. Zum Angreifen tippst du eine Karte an - oder eine Auswahl, deren Werte alle schon auf dem Tisch liegen - und drückst auf „Angriff“. Oder du ziehst Karten von deiner Hand auf den Tisch.",
            "ios.rules.throw.ok1": "Eine 9 liegt auf dem Tisch, also darf deine 9 dazu - die Farben spielen keine Rolle.",
            "ios.rules.throw.ok2": "Beide 6er auf einmal - zwei neue Angriffe.",
            "ios.rules.throw.ok3": "Oder die 6 und die 9 zusammen - beide Werte liegen schon draußen.",
            "ios.rules.throw.no1": "Keine 8 und kein Bube auf dem Tisch - da gibt es nichts mitzugeben.",
            "ios.rules.throw.no2": "Der Verteidiger hält eine Karte und ein Angriff wartet schon - für einen zweiten ist kein Platz.",
            "ios.rules.pickup.h": "Aufnehmen",
            "ios.rules.pickup.b": "Wenn ein Verteidiger nicht alle Karten decken kann oder nicht decken will, darf er den Knopf „Nehmen“ drücken. Dann nimmt er jede Karte vom Tisch auf, auch die schon gedeckten. Und sein Zug fällt aus, also greift in der nächsten Runde der Spieler links von ihm an. Überleg dir das Aufnehmen also gut.",
            "ios.rules.pickup.cap": "Nimm hier auf, und alle drei Karten wandern auf deine Hand - das gedeckte Paar auch.",
            "ios.rules.round.h": "Rundenende",
            "ios.rules.round.b": "Sind alle Karten gedeckt und will kein Angreifer mehr etwas mitgeben, wandern alle Karten vom Tisch auf den Ablagestapel. Danach wird nachgezogen, beginnend beim ersten Angreifer und im Uhrzeigersinn durch alle Angreifer, bis jeder wieder 6 Karten auf der Hand hat (wer schon 6 oder mehr hat, zieht nicht). Danach zieht der Verteidiger. Das Spiel macht das automatisch. Ist der Stapel leer, können die Spieler anfangen, ihre Karten loszuwerden, um am Ende nicht der Durak zu sein. Die Runde endet auch, wenn der Verteidiger aufnimmt; die Angreifer ziehen dann ebenso nach.",
            "ios.rules.pass.h": "Schieben",
            "ios.rules.pass.b": "In einem Spiel, in dem переводной, also das \"Schieben\", erlaubt ist, hat der Verteidiger zusätzlich die Wahl, den Angriff von sich weg an den Spieler links von sich zu schieben. Dafür darf keine Karte auf dem Tisch gedeckt sein, und er braucht eine Karte mit demselben WERT wie alle Angriffskarten auf dem Tisch. Dann legt er diese Karte hin, und das Verteidigersymbol wandert im Uhrzeigersinn zum Spieler links von ihm. Genau wie es aber eine Grenze für die Zahl der Angriffe gibt, ist Schieben nicht möglich, wenn der linke Nachbar weniger Karten hat, als es nach dem Schieben Angriffe gäbe. Liegen zum Beispiel zwei Angriffskarten auf dem Tisch und der linke Nachbar hält zwei Karten, geht Schieben nicht: Danach lägen mindestens 3 Karten dort (2 plus die geschobene). Das ist mehr, als er auf der Hand hat, und darum nicht erlaubt. Zum Schieben tippst du die Karte mit dem passenden Wert an und drückst den Knopf „Schieben“. Oder du ziehst diese Karte auf eine freie Stelle des Tisches.",
            "ios.rules.pass.ok1": "Eine 8 greift an und du hast eine 8 - leg sie hin, und der Schild wandert weiter.",
            "ios.rules.pass.no1": "Es ist schon etwas gedeckt - zum Schieben zu spät.",
            "ios.rules.pass.no2": "Keine 8 auf deiner Hand - diese hier musst du verteidigen.",
            "ios.rules.pass.no3": "Schieben ergäbe drei Angriffe, und der nächste Spieler hält nur zwei Karten.",
            "ios.rules.end.h": "Spielende",
            "ios.rules.end.b": "Ist der Nachziehstapel leer, geht das Spiel weiter. Wer alle seine Karten loswird, kann nicht mehr der Durak werden. Der letzte Spieler, der noch Karten hat, wird der Durak.",
            "ios.rules.lobby.h": "So funktioniert die Lobby",
            "ios.rules.lobby.b": "Trag deinen Namen ein, um beizutreten. Sobald mindestens zwei Spieler dabei sind, kann jeder auf „Spiel starten“ drücken. Nach dem Start kommt niemand mehr dazu.",
            "ios.rules.variant.h": "Schieben",
            "ios.rules.variant.b": "Die Lobby entscheidet, welches Durak an diesem Tisch gespielt wird, und das Kästchen sagt welches. Angehakt ist das Spiel mit Schieben (perewodnoi): Ein Verteidiger mit einer Karte vom selben Wert wie der Angriff darf sie hinlegen und den ganzen Angriff an den nächsten Spieler weitergeben, der ihn nun verteidigen muss. Nicht angehakt ist das Spiel mit Mitgeben (podkidnoi): Es wird nicht geschoben, der Verteidiger deckt also jede Karte auf dem Tisch oder nimmt alles auf. Solange die Lobby offen ist, darf jeder am Tisch das ändern; mit dem Spielstart steht es fest.",
            "ios.rules.fool.h": "Der Durak zahlt dafür",
            "ios.rules.fool.b": "Normalerweise entscheidet der niedrigste Trumpf, wer zuerst angreift. Es gibt eine Ausnahme, und sie ist die älteste Form der Durak-Gerechtigkeit: Drückst du nach einem Spiel auf Neues Spiel und setzen sich genau dieselben Spieler wieder hin, entscheidet der niedrigste Trumpf gar nichts. Stattdessen eröffnet der Spieler rechts vom letzten Durak, was bedeutet, dass der Durak als Erster angegriffen wird. Verlierst du, kommt das nächste Spiel direkt auf dich zu. Kommt vor dem Start jemand dazu oder geht jemand, hat sich der Tisch geändert und die normale Regel gilt wieder.",
            "ios.lobby.passing": "Mit Schieben",
            "ios.rules.lbl.table": "auf dem Tisch",
