            "ios.tut_done": "Losspielen",
            "ios.tut_1": "Willkommen bei Durak. Die niedrigste Trumpfkarte entscheidet, wer zuerst angreift. Trumpf schlägt jede andere Farbe.",
            "ios.tut_2": "Zum Angreifen tippst du eine Karte auf deiner Hand an. Dein Gegner muss sie schlagen - oder alles aufnehmen.",
            "ios.tut_3": "Zum Verteidigen tippst du eine deiner Karten an und dann den Angriff, den sie schlägt. Eine höhere Karte derselben Farbe oder jeder Trumpf deckt sie.",
            "ios.tut_4": "Kannst oder willst du nicht verteidigen? Tippe auf Nehmen, um die Karten aufzunehmen. Fertig mit Angreifen? Tippe auf Fertig.",
            "ios.tut_5": "Werde deine Karten vor allen anderen los. Der letzte Spieler mit Karten ist der Durak. Viel Glück!",
