            "ios.settings.table.wool": "Lana",
            "ios.settings.table.felt": "Panno verde",
            "ios.rules.title": "Come si gioca",
            "ios.rules.goal.h": "Lo scopo",
            "ios.rules.goal.b": "Lo scopo del gioco è liberarsi di tutte le proprie carte il prima possibile. Chi alla fine resta con le carte in mano è il дурак, lo sciocco in russo.",
            "ios.rules.setup.h": "Preparazione",
            "ios.rules.setup.b": "Con quattro giocatori o meno si gioca solo con le carte dal 6 all’Asso. I 2, i 3, i 4 e i 5 escono dal mazzo. L’Asso è la carta più alta. Ogni giocatore riceve 6 carte, poi si pesca un’altra carta, la si gira scoperta e la si mette sotto il mazzo di pesca. Il SEME di questa carta scoperta indica il seme di briscola. Questo seme è speciale: lo spieghiamo nella sezione Difendere.",
            "ios.rules.setup.cap": "Una carta resta scoperta sotto il mazzo - il suo seme è quello di briscola. Cuori, in tutti gli esempi di questa pagina.",
            "ios.rules.start.h": "Inizio della partita",
            "ios.rules.start.b": "Comincia chi ha la briscola più bassa. Dal vivo lo si scopre chiedendo se qualcuno ha un 6, poi un 7, e così via. Qui lo fa il gioco da solo. Questa persona è il primo attaccante della mano.",
            "ios.rules.sword": "La spada indica l’attaccante che apre la mano.",
            "ios.rules.shield": "Lo scudo indica chi difende.",
            "ios.rules.attack.h": "Attaccare",
            "ios.rules.attack.b": "Il primo attaccante della mano, segnato da una spada, può scegliere dalla propria mano una carta qualsiasi - o un gruppo di carte tutte dello stesso VALORE - e metterla davanti al giocatore alla sua sinistra (in senso orario). Quel giocatore diventa il difensore, segnato da uno scudo, e deve occuparsi dell’attacco. Per attaccare, tocca le carte per selezionarle e premi il pulsante di attacco che compare quando la selezione è una mossa valida. Oppure trascina semplicemente le carte dalla mano al tavolo.",
            "ios.rules.attack.ok1": "Questo giocatore può attaccare con la sua Donna.",
            "ios.rules.attack.ok2": "Può anche attaccare con i due Re insieme, perché hanno lo stesso valore.",
            "ios.rules.attack.no1": "NON può attaccare con il 7 e il 10, perché sono valori diversi.",
            "ios.rules.defend.h": "Difendere",
            "ios.rules.defend.b": "Il giocatore sotto attacco, segnato dallo scudo, è il difensore. C’è un solo difensore alla volta, e tutte le carte messe dagli altri sono carte di cui deve occuparsi lui. Il difensore può solo coprire, prendere le carte o passare (se è permesso). Il difensore NON PUÒ attaccare. Tutti gli altri sono attaccanti e possono solo attaccare. Gli attaccanti NON POSSONO coprire nessuna carta sul tavolo.",
            "ios.rules.defend.b.nopass": "Il giocatore sotto attacco, segnato dallo scudo, è il difensore. C’è un solo difensore alla volta, e tutte le carte messe dagli altri sono carte di cui deve occuparsi lui. Il difensore può solo coprire o prendere le carte. Il difensore NON PUÒ attaccare. Tutti gli altri sono attaccanti e possono solo attaccare. Gli attaccanti NON POSSONO coprire nessuna carta sul tavolo.",
            "ios.rules.cover.h": "Coprire",
            "ios.rules.cover.b": "Il difensore può coprire le carte sul tavolo mettendo su ciascuna una carta più alta dello stesso seme, oppure una briscola qualsiasi. È questo che rende speciale il seme di briscola. Per coprire, seleziona una carta e tocca il pulsante Copri. In alternativa trascina una carta della tua mano sulla carta che vuoi coprire. Un errore comune è pensare che una carta già coperta possa essere coperta di nuovo da una terza. Il gioco non funziona così. Non vedrai mai pile da tre sul tavolo. Immagina la carta d’attacco come una spada e quella di copertura come uno scudo: l’attacco è bloccato, e quindi concluso. Si possono fare solo attacchi nuovi, in pile separate.",
            "ios.rules.cover.ok1": "Una carta più alta dello stesso seme copre.",
            "ios.rules.cover.ok2": "Una briscola qualsiasi copre ogni altro seme - anche con un valore più basso.",
            "ios.rules.cover.no1": "Un attacco di briscola richiede una briscola più alta - questo 7 è troppo basso.",
            "ios.rules.cover.no2": "Valore più alto, seme sbagliato - così non copri niente.",
            "ios.rules.throw.h": "Aggiungere carte",
            "ios.rules.throw.b": "Mentre il difensore copre, ogni altro giocatore può \"aggiungere\" altre carte d’attacco che il difensore dovrà coprire in più. La regola è semplice, anche se ci vuole un momento per farla propria. Se vedi sul tavolo il VALORE (per esempio A, 6, 10) di una carta che hai in mano, e sei un attaccante, puoi mettere quella carta come un nuovo attacco a parte. Dei semi non devi preoccuparti PER NULLA. L’unico limite è il numero di carte che il difensore ha in mano: gli attacchi non ancora coperti sul tavolo non possono essere più delle carte che tiene. Immagina che il difensore debba poter rispondere a ogni carta d’attacco con una carta di difesa; se gli attacchi sono troppi, è fisicamente impossibile, e quindi non è permesso. Forse ti chiedi se in questo modo il numero di attacchi possa moltiplicarsi in fretta. È proprio così, e fa parte del divertimento del gioco. Per attaccare, tocca una carta - o un gruppo in cui ogni carta ha il suo valore già sul tavolo - e premi Attacca. Oppure trascina le carte dalla mano al tavolo.",
            "ios.rules.throw.ok1": "Sul tavolo c’è un 9, quindi il tuo 9 può entrare - i semi non contano.",
            "ios.rules.throw.ok2": "Tutti e due i 6 insieme - due nuovi attacchi.",
            "ios.rules.throw.ok3": "Oppure il 6 e il 9 insieme - i due valori sono già sul tavolo.",
            "ios.rules.throw.no1": "Sul tavolo non c’è né un 8 né un Fante - non c’è niente da aggiungere.",
            "ios.rules.throw.no2": "Il difensore ha una carta e un attacco è già in attesa - non c’è posto per un altro.",
            "ios.rules.pickup.h": "Prendere le carte",
            "ios.rules.pickup.b": "Se il difensore non riesce a coprire tutte le carte, o non vuole farlo, può premere il pulsante Prendi. Così raccoglie ogni carta sul tavolo, comprese quelle già coperte. E salta il proprio turno, quindi nella mano successiva attaccherà il giocatore alla sua sinistra. Pensaci bene prima di prendere.",
            "ios.rules.pickup.cap": "Prendi qui e tutte e tre le carte finiscono nella tua mano - anche la coppia coperta.",
            "ios.rules.round.h": "Fine della mano",
            "ios.rules.round.b": "Quando tutte le carte sono coperte e nessun attaccante vuole aggiungerne altre, tutto ciò che è sul tavolo va nella pila degli scarti. Poi si pesca, a partire dal primo attaccante e proseguendo in senso orario fra tutti gli attaccanti, fino ad avere almeno 6 carte. Il difensore pesca per ultimo. Lo fa il gioco in automatico. Quando il mazzo si esaurisce, i giocatori possono cominciare a liberarsi delle carte ed non diventare lo sciocco. La mano finisce anche se il difensore prende le carte; gli attaccanti pescano allo stesso modo.",
            "ios.rules.pass.h": "Passare",
            "ios.rules.pass.b": "In una partita in cui è permesso il переводной, cioè il \"passaggio\", il difensore ha anche la possibilità di allontanare da sé l’attacco e passarlo al giocatore alla sua sinistra. Per farlo nessuna carta sul tavolo deve essere coperta, e lui deve avere una carta dello stesso VALORE di tutte le carte d’attacco sul tavolo. Allora può metterla giù, e l’icona del difensore si sposta in senso orario al giocatore alla sua sinistra. Però, proprio come c’è un limite al numero di carte d’attacco, il passaggio non si può fare se il giocatore alla sinistra ha meno carte di quanti sarebbero gli attacchi dopo il passaggio. Per esempio: se sul tavolo ci sono due carte d’attacco e il giocatore alla sinistra ne tiene due, passare è impossibile, perché dopo ci sarebbero almeno 3 carte (2 più quella passata). Sono più di quelle che ha in mano, e quindi non è permesso. Per passare, tocca la carta di valore uguale e premi il pulsante Passa. Oppure trascina quella carta in uno spazio libero del tavolo.",
            "ios.rules.pass.ok1": "Ti attacca un 8 e tu hai un 8 - mettilo giù e lo scudo va avanti.",
            "ios.rules.pass.no1": "Qualcosa è già coperto - troppo tardi per passare.",
            "ios.rules.pass.no2": "Nessun 8 tra le tue carte - questo attacco tocca a te.",
            "ios.rules.pass.no3": "Passare farebbe tre attacchi, e il giocatore successivo ha solo due carte.",
            "ios.rules.end.h": "Fine della partita",
            "ios.rules.end.b": "Una volta vuoto il mazzo di pesca, la partita continua. Chi si libera di tutte le carte è salvo e non può essere lo sciocco. L’ultimo giocatore rimasto con le carte diventa lo sciocco.",
            "ios.rules.lobby.h": "Come funziona la sala",
            "ios.rules.lobby.b": "Aggiungi il tuo nome per entrare. Quando sono entrati almeno due giocatori, chiunque può premere Inizia la partita. Dopo l’inizio della partita non entra più nessuno.",
            "ios.rules.variant.h": "Passaggio",
            "ios.rules.variant.b": "La sala sceglie a quale Durak si gioca a questo tavolo, e la casella dice quale. Con la spunta si gioca al Durak con il passaggio (perevodnoj): un difensore che ha una carta dello stesso valore dell’attacco può metterla giù e passare tutto l’attacco al giocatore successivo, che ora dovrà difendersi. Senza spunta si gioca al Durak con l’aggiunta di carte (podkidnoj): non si passa, quindi il difensore o copre ogni carta sul tavolo o prende tutto. Finché la sala è aperta chiunque al tavolo può cambiarlo; appena la partita inizia resta fisso.",
            "ios.rules.fool.h": "Lo sciocco la paga",
            "ios.rules.fool.b": "Di solito è la briscola più bassa a decidere chi attacca per primo. C’è un’eccezione, ed è la più antica forma di giustizia del Durak: se premi Nuova partita alla fine di una partita e si rimettono a sedere esattamente gli stessi giocatori, la briscola più bassa non decide niente. Apre invece il giocatore seduto alla destra dell’ultimo sciocco, il che significa che lo sciocco è il primo a essere attaccato. Perdi, e la partita dopo ti arriva addosso. Se qualcuno entra o esce prima di Inizia la partita, il tavolo è cambiato e torna la regola normale.",
            "ios.lobby.passing": "Con il passaggio",
            "ios.rules.lbl.table": "sul tavolo",
            "ios.rules.lbl.hand": "le tue carte",
            "ios.rules.defender": "Difensore",
            "ios.rules.nextplayer": "Giocatore successivo",
            "ios.msg.nametaken": "soprannome già preso in questa partita",
