            "ios.tut_next": "Ho capito",
            "ios.tut_done": "Inizia a giocare",
            "ios.tut_1": "Ti diamo il benvenuto a Durak. La carta di briscola più bassa decide chi attacca per primo. La briscola batte ogni altro seme.",
            "ios.tut_2": "Per attaccare, tocca una carta della tua mano. Il tuo avversario deve batterla - oppure prendere tutto.",
            "ios.tut_3": "Per difendere, tocca una delle tue carte e poi l’attacco che batte. La copre una carta più alta dello stesso seme, o una briscola qualsiasi.",
            "ios.tut_4": "Non puoi o non vuoi difendere? Tocca Prendi per raccogliere le carte. Hai finito di attaccare? Tocca Fatto.",
