            "ios.rej.turn": "あなたの番ではありません。",
            "ios.rej.pickone": "先にカードを選んでください。",
            "ios.rej.defending": "あなたは防御側です - 攻撃を上回るか、場のカードを取ってください。",
            "ios.rej.notyours": "そのカードは手札にありません。",
            "ios.rej.addrank": "場に出ているランクしか追加できません。",
            "ios.rej.cover": "それでは上回れません - 同じスートのより強いカードか、切り札を出してください。",
            "ios.rej.capacity": "防御側の手札に対して攻撃が多すぎます。",
            "ios.rej.passrank": "同じランクのカードでしかパスできません。",
            "ios.rej.mustattack": "最初の攻撃側は攻撃しなければなりません。",
            "ios.rej.alreadygood": "すでに完了と宣言しています。",
            "ios.rej.notake": "取るものがありません。",
            "ios.help": "ルール",
            "ios.settings.title": "設定",
            "ios.settings.table": "テーブル",
            "ios.settings.table.wool": "ウール",
            "ios.settings.table.felt": "緑のフェルト",
            "ios.rules.title": "遊び方",
            "ios.rules.goal.h": "目的",
            "ios.rules.goal.b": "このゲームの目的は、できるだけ早く手札をすべてなくすことです。最後までカードが残った人が дурак（ドゥラーク）、ロシア語で「愚か者」です。",
            "ios.rules.setup.h": "準備",
            "ios.rules.setup.b": "4人以下で遊ぶときは、6からエースまでのカードだけを使います。2、3、4、5は取り除きます。エースが一番強いカードです。各プレイヤーに6枚ずつ配り、さらに1枚引いて表向きにし、山札の下に差し込みます。この表向きのカードのスートが切り札のスートになります。この切り札のスートは特別で、防御のところで説明します。",
            "ios.rules.setup.cap": "山札の下に1枚が表向きに置かれ、そのスートが切り札のスートになります。このページの例ではすべてハートです。",
            "ios.rules.start.h": "ゲームの始め方",
            "ios.rules.start.b": "切り札の中で一番小さいカードを持つ人が先手です。対面で遊ぶときは「6を持っている人は？」「では7は？」と順に聞いて決めます。ここではゲームが自動で決めます。この人がそのラウンドの最初の攻撃側です。",
            "ios.rules.sword": "剣はそのラウンドを始める攻撃側を示します。",
            "ios.rules.shield": "盾は防御側を示します。",
            "ios.rules.attack.h": "攻撃",
            "ios.rules.attack.b": "剣の印が付いたラウンド最初の攻撃側は、手札から好きなカード1枚、または同じ数字のカードを何枚でも選び、左隣（時計回り）のプレイヤーの前に出せます。そのプレイヤーが盾の印が付いた防御側になり、攻撃に対処しなければなりません。攻撃するには、カードをタップして選び、選んだカードが有効な手になったときに現れる攻撃ボタンを押します。手札から場へカードをドラッグしても構いません。",
            "ios.rules.attack.ok1": "このプレイヤーはクイーンで攻撃できます。",
            "ios.rules.attack.ok2": "2枚のキングを同時に出して攻撃することもできます。ランクが同じだからです。",
            "ios.rules.attack.no1": "7と10を一緒に出して攻撃することはできません。ランクが違うからです。",
            "ios.rules.defend.h": "防御",
            "ios.rules.defend.b": "盾の印が付いた、いま攻撃を受けているプレイヤーが防御側です。防御側は常に1人だけで、ほかのプレイヤーが出したカードはすべて防御側が対処します。防御側にできるのは、受けるか、場のカードを取るか、（許されていれば）パスするかだけです。防御側は攻撃できません。ほかの全員は攻撃側で、攻撃しかできません。攻撃側は場のカードを受けられません。",
            "ios.rules.defend.b.nopass": "盾の印が付いた、いま攻撃を受けているプレイヤーが防御側です。防御側は常に1人だけで、ほかのプレイヤーが出したカードはすべて防御側が対処します。防御側にできるのは、受けるか、場のカードを取るかだけです。防御側は攻撃できません。ほかの全員は攻撃側で、攻撃しかできません。攻撃側は場のカードを受けられません。",
            "ios.rules.cover.h": "受ける",
            "ios.rules.cover.b": "防御側は、場の各カードに同じスートのより強いカードか、任意の切り札を重ねて防御します。これが切り札のスートを特別にしている点です。受けるには、カードを選んで「受ける」ボタンを押します。手札のカードを、場の受けたいカードへドラッグしても構いません。よくある勘違いは、すでに受けられたカードにさらに3枚目を重ねられると思うことです。このゲームはそうなっていません。場でカードが3枚重なることはありません。攻撃カードを剣、受けたカードを盾だと考えてください。攻撃は防がれ、そこで終わりです。できるのは別の山として新しく攻撃することだけです。",
            "ios.rules.cover.ok1": "同じスートのより強いカードで受けられます。",
            "ios.rules.cover.ok2": "切り札はほかのどのスートも受けられます - 数字が小さくても構いません。",
            "ios.rules.cover.no1": "切り札の攻撃には、より強い切り札が必要です - この7では足りません。",
            "ios.rules.cover.no2": "数字は上でもスートが違います - これでは何も受けられません。",
            "ios.rules.throw.h": "投げ込み（追加攻撃）",
            "ios.rules.throw.b": "防御側が受けている間、ほかのプレイヤーは全員、防御側がさらに受けなければならない攻撃カードを「投げ込む」ことができます。ルールは単純ですが、慣れるまで少しかかります。自分が持っているカードのランク（A、6、10など）が場に出ていて、自分が攻撃側なら、そのカードを別の新しい攻撃として場に加えられます。スートはまったく気にしなくて構いません。唯一の制限は、そのときの防御側の手札の枚数です。場にあるまだ受けていない攻撃の数が、防御側が持っているカードの枚数を超えてはいけません。防御側は攻撃カード1枚ごとに防御カード1枚で応じられなければならない、と考えてください。攻撃が多すぎるとそれは物理的に不可能なので、許されないのです。これでは攻撃カードがあっという間に増えてしまうのでは、と思うかもしれません。そのとおりで、それがこのゲームの面白さの一部です。攻撃するには、カード1枚、またはそれぞれの数字がすでに場に出ているカードの組をタップして、攻撃を押します。手札から場へドラッグしても構いません。",
            "ios.rules.throw.ok1": "場に9があるので、あなたの9も出せます - スートは関係ありません。",
            "ios.rules.throw.ok2": "2枚の6を同時に - 新しい攻撃が2つです。",
            "ios.rules.throw.ok3": "6と9を一緒でも構いません - どちらの数字もすでに場に出ています。",
            "ios.rules.throw.no1": "場に8もジャックもありません - 投げ込めるものがありません。",
            "ios.rules.throw.no2": "防御側の手札は1枚で、攻撃はすでに1つ待っています - もう1つ入る余地はありません。",
            "ios.rules.pickup.h": "場のカードを取る",
            "ios.rules.pickup.b": "防御側が場のカードをすべて受けられない、または受けたくないときは、「取る」ボタンを押せます。すると防御側は場のカードをすべて取ります。すでに受けられたカードも含めてです。さらに自分の番は飛ばされ、次のラウンドは左隣のプレイヤーから攻撃が始まります。取るかどうかはよく考えてください。",
            "ios.rules.pickup.cap": "ここで取ると、3枚とも手札に入ります - 受けられた2枚の組も一緒です。",
            "ios.rules.round.h": "ラウンドの終わり",
            "ios.rules.round.b": "場のカードがすべて受けられ、どの攻撃側もこれ以上追い出さないと決めたら、場のカードはすべて捨て札の山へ送られます。その後、最初の攻撃側から時計回りにすべての攻撃側が、手札が6枚になるまで山札から引きます（すでに6枚以上ある人は引きません）。そのあとで防御側が引きます。これはゲームが自動で行います。山札が尽きると、プレイヤーは手札を減らしてドゥラークにならないようにしていきます。防御側が場のカードを取った場合もラウンドは終わり、攻撃側は同じように引きます。",
            "ios.rules.pass.h": "パス",
            "ios.rules.pass.b": "переводной（ペレヴォドノイ）、つまり「パス」が許されているゲームでは、防御側には攻撃を自分から左隣のプレイヤーへ回すという選択肢もあります。そのためには、場のどのカードもまだ受けられていないことと、場のすべての攻撃カードと同じ数字のカードを持っていることが必要です。その条件を満たせばそのカードを場に置き、盾の印は時計回りに左隣のプレイヤーへ移ります。ただし、攻撃できる枚数に制限があるのと同じように、パスした後の攻撃の数より左隣のプレイヤーの手札が少ない場合はパスできません。たとえば、場に攻撃カードが2枚あり、左隣のプレイヤーの手札が2枚なら、パスはできません。パスすると場のカードが少なくとも3枚（2枚＋パスする1枚）になり、相手の手札より多くなってしまうからです。パスするには、同じ数字のカードをタップしてパスボタンを押します。そのカードを場の空いているところへドラッグしても構いません。",
            "ios.rules.pass.ok1": "8で攻撃されていて、あなたも8を持っています - 出せば盾は次の人へ移ります。",
            "ios.rules.pass.no1": "すでに受けられたカードがあります - パスするには遅すぎます。",
            "ios.rules.pass.no2": "手札に8がありません - この攻撃はあなたが防御します。",
            "ios.rules.pass.no3": "パスすると攻撃が3つになりますが、次のプレイヤーの手札は2枚しかありません。",
            "ios.rules.end.h": "ゲームの終わり",
            "ios.rules.end.b": "山札がなくなってもゲームは続きます。手札をすべてなくした人はドゥラークになりません。最後までカードが残った人がドゥラークです。",
            "ios.rules.lobby.h": "ロビーの仕組み",
            "ios.rules.lobby.b": "名前を入れると参加できます。2人以上そろえば、誰でも「ゲームを開始」を押せます。ゲームが始まると、あとから参加はできません。",
            "ios.rules.variant.h": "パス",
            "ios.rules.variant.b": "このテーブルがどのドゥラークで遊ぶかはロビーで決まり、チェックボックスがそれを示します。チェックありはパスありのゲーム（ペレヴォドノイ）です。攻撃と同じ数字のカードを持つ防御側は、それを出して攻撃全体を次のプレイヤーへ回せます。回された人が今度は防御します。チェックなしは投げ込みのゲーム（ポドキドノイ）です。パスはないので、防御側は場のカードをすべて受けるか、すべて取るかのどちらかです。ロビーが開いている間はテーブルの誰でも変更できます。ゲームが始まると固定されます。",
            "ios.rules.fool.h": "ドゥラークにはツケが回る",
            "ios.rules.fool.b": "普通は切り札の中で一番小さいカードが先手を決めます。例外がひとつあり、これはドゥラークで最も古い形の裁きです。ゲームが終わったあとに「新しいゲーム」を押し、まったく同じ顔ぶれがそろった場合、一番小さい切り札は何も決めません。代わりに、前回のドゥラークの右隣のプレイヤーが始めます。つまりドゥラークが最初に攻撃されます。負ければ、次のゲームはまっすぐ自分に向かってくるのです。開始前に誰かが入るか抜けるかすれば、テーブルが変わったことになり、通常のルールに戻ります。",
            "ios.lobby.passing": "パスあり",
