            "ios.rej.alreadygood": "Pas już zgłoszony.",
            "ios.rej.notake": "Nie ma czego brać.",
            "ios.help": "Zasady",
            "ios.settings.title": "Ustawienia",
            "ios.settings.table": "Stół",
            "ios.settings.table.wool": "Wełna",
            "ios.settings.table.felt": "Zielone sukno",
            "ios.rules.title": "Jak grać",
            "ios.rules.goal.h": "Cel gry",
            "ios.rules.goal.b": "Celem gry jest jak najszybsze pozbycie się wszystkich kart. Kto zostaje na końcu z kartami, ten jest дурак - po polsku dureń.",
            "ios.rules.setup.h": "Przygotowanie",
            "ios.rules.setup.b": "Przy czterech graczach lub mniej gra się tylko kartami od 6 do asa. Dwójki, trójki, czwórki i piątki wychodzą z talii. As jest najwyższą kartą. Każdy dostaje 6 kart, potem dobiera się jeszcze jedną, odkrywa ją i wsuwa pod talię. KOLOR tej odkrytej karty wyznacza kolor atutowy. Ten kolor jest wyjątkowy, a dlaczego - wyjaśnia się przy obronie.",
            "ios.rules.setup.cap": "Jedna karta leży odkryta pod talią - jej kolor to atut. Na tej stronie w każdym przykładzie są to kiery.",
            "ios.rules.start.h": "Początek gry",
            "ios.rules.start.b": "Zaczyna ten, kto ma najniższy atut. Przy prawdziwym stole ustala się to, pytając, czy ktoś ma szóstkę, potem siódemkę i tak dalej. Tutaj robi to sama gra. Ta osoba jest pierwszym atakującym w rundzie.",
            "ios.rules.sword": "Miecz oznacza atakującego, który otwiera rundę.",
            "ios.rules.shield": "Tarcza oznacza broniącego się.",
            "ios.rules.attack.h": "Atakowanie",
            "ios.rules.attack.b": "Pierwszy atakujący w rundzie, oznaczony mieczem, może wybrać z ręki dowolną kartę - albo dowolny zestaw kart o tej samej WARTOŚCI - i położyć je przed graczem po swojej lewej (zgodnie z ruchem wskazówek zegara). Ten gracz staje się broniącym się, oznaczonym tarczą, i musi poradzić sobie z atakiem. Żeby zaatakować, dotknij kart, aby je zaznaczyć, i naciśnij przycisk Atak, który pojawia się, gdy zaznaczenie jest poprawnym ruchem. Możesz też po prostu przeciągnąć karty z ręki na stół.",
            "ios.rules.attack.ok1": "Ten gracz może zaatakować damą.",
            "ios.rules.attack.ok2": "Może też zaatakować dwoma królami naraz, bo mają tę samą wartość.",
            "ios.rules.attack.no1": "NIE może zaatakować siódemką i dziesiątką, bo mają różne wartości.",
            "ios.rules.defend.h": "Obrona",
            "ios.rules.defend.b": "Gracz, który jest właśnie atakowany i oznaczony tarczą, to broniący się. W danej chwili broni się tylko jedna osoba, a wszystkie karty położone przez pozostałych są jej problemem. Broniący się może tylko kryć, wziąć karty albo odbić (jeśli wolno). Broniący się NIE MOŻE atakować. Wszyscy pozostali są atakującymi i mogą tylko atakować. Atakujący NIE MOGĄ kryć żadnej karty na stole.",
            "ios.rules.defend.b.nopass": "Gracz, który jest właśnie atakowany i oznaczony tarczą, to broniący się. W danej chwili broni się tylko jedna osoba, a wszystkie karty położone przez pozostałych są jej problemem. Broniący się może tylko kryć albo wziąć karty. Broniący się NIE MOŻE atakować. Wszyscy pozostali są atakującymi i mogą tylko atakować. Atakujący NIE MOGĄ kryć żadnej karty na stole.",
            "ios.rules.cover.h": "Krycie",
            "ios.rules.cover.b": "Broniący się kryje karty na stole, kładąc na każdą z nich wyższą kartę w tym samym kolorze albo dowolny atut. To właśnie czyni kolor atutowy wyjątkowym. Żeby kryć, zaznacz kartę i dotknij przycisku Kryj. Możesz też przeciągnąć kartę z ręki na tę, którą chcesz przykryć. Częsty błąd to przekonanie, że kartę już przykrytą można przykryć trzecią. Gra tak nie działa. Nigdy nie zobaczysz na stole stosów po trzy karty. Pomyśl o karcie ataku jak o mieczu, a o karcie krycia jak o tarczy: atak został zablokowany i tym samym zakończony. Można tylko atakować od nowa, na osobnych stosach.",
            "ios.rules.cover.ok1": "Wyższa karta w tym samym kolorze kryje.",
            "ios.rules.cover.ok2": "Dowolny atut kryje każdy inny kolor - nawet o niższej wartości.",
            "ios.rules.cover.no1": "Atak atutem wymaga wyższego atutu - ta siódemka jest za niska.",
            "ios.rules.cover.no2": "Wyższa wartość, ale zły kolor - to niczego nie kryje.",
            "ios.rules.throw.h": "Dorzucanie",
            "ios.rules.throw.b": "Kiedy broniący się kryje, każdy inny gracz może \"dorzucić\" kolejne karty ataku, które broniący się też będzie musiał przykryć. Zasada jest prosta, choć chwilę zajmuje jej zrozumienie. Jeśli widzisz na stole WARTOŚĆ (na przykład as, 6, 10) karty, którą masz w ręce, i jesteś atakującym, możesz dołożyć tę kartę jako osobny nowy atak. Kolorami nie przejmuj się ZUPEŁNIE. Jedynym ograniczeniem jest liczba kart, które broniący się ma właśnie w ręce. Niekrytych ataków na stole nie może być więcej niż kart w jego ręce. Wyobraź sobie, że broniący się musi móc odpowiedzieć na każdą kartę ataku jedną kartą obrony. Jeśli ataków jest za dużo, jest to fizycznie niemożliwe, a więc niedozwolone. Może się zastanawiasz, czy liczba kart ataku nie zacznie się przez to szybko mnożyć. Właśnie tak, i to część uroku tej gry. Żeby zaatakować, dotknij karty - albo zestawu, w którym każda karta ma swoją wartość już na stole - i naciśnij atak. Możesz też przeciągnąć karty z ręki na stół.",
            "ios.rules.throw.ok1": "Na stole leży dziewiątka, więc twoja dziewiątka może dołączyć - kolory nie mają znaczenia.",
            "ios.rules.throw.ok2": "Obie szóstki naraz - dwa nowe ataki.",
            "ios.rules.throw.ok3": "Albo szóstka i dziewiątka razem - obie wartości już tam leżą.",
            "ios.rules.throw.no1": "Na stole nie ma ósemki ani waleta - nie ma czego dorzucić.",
            "ios.rules.throw.no2": "Broniący się ma jedną kartę, a jeden atak już czeka - na kolejny nie ma miejsca.",
            "ios.rules.pickup.h": "Branie kart",
            "ios.rules.pickup.b": "Jeśli broniący się nie może przykryć wszystkich kart albo nie chce, może nacisnąć przycisk Bierz. Wtedy zabiera ze stołu każdą kartę, również te już przykryte. Traci też swoją kolej, więc w następnej rundzie atak zaczyna gracz po jego lewej. Dobrze się więc zastanów, zanim weźmiesz.",
            "ios.rules.pickup.cap": "Weź tutaj, a wszystkie trzy karty trafią do twojej ręki - przykryta para też.",
            "ios.rules.round.h": "Koniec rundy",
            "ios.rules.round.b": "Kiedy wszystkie karty są przykryte, a żaden atakujący nie chce już nic dorzucić, wszystko ze stołu idzie na stos odrzuconych. Potem gracze dobierają, zaczynając od pierwszego atakującego i idąc zgodnie z ruchem wskazówek zegara przez wszystkich atakujących, aż będą mieli po co najmniej 6 kart. Na końcu dobiera broniący się. Gra robi to sama. Kiedy talia się skończy, gracze mogą zacząć pozbywać się kart i uniknąć roli durnia. Runda kończy się też wtedy, gdy broniący się weźmie karty - atakujący dobierają wtedy tak samo.",
            "ios.rules.pass.h": "Odbijanie",
            "ios.rules.pass.b": "W grze, w której wolno stosować переводной, czyli \"odbijanie\", broniący się ma dodatkowo możliwość przerzucić atak od siebie na gracza po swojej lewej. Żeby to zrobić, żadna karta na stole nie może być przykryta, a on sam musi mieć kartę o tej samej WARTOŚCI co wszystkie karty ataku na stole. Wtedy kładzie tę kartę, a ikona broniącego się przesuwa się zgodnie z ruchem wskazówek zegara na gracza po jego lewej. Tak samo jak przy ataku obowiązuje tu limit, odbicia nie można wykonać, jeśli gracz po lewej ma mniej kart, niż byłoby ataków po odbiciu. Na przykład: jeśli na stole są dwie karty ataku, a gracz po lewej trzyma dwie karty, odbić się nie da, bo po odbiciu leżałyby co najmniej 3 karty (2 plus karta odbicia). To więcej, niż on ma w ręce, a więc jest niedozwolone. Żeby odbić, dotknij karty o pasującej wartości i naciśnij przycisk Odbij. Możesz też przeciągnąć tę kartę na puste miejsce na stole.",
            "ios.rules.pass.ok1": "Atakuje ósemka, a ty masz ósemkę - połóż ją, a tarcza idzie dalej.",
            "ios.rules.pass.no1": "Coś jest już przykryte - za późno na odbicie.",
            "ios.rules.pass.no2": "Nie masz ósemki - tę musisz odeprzeć sam.",
            "ios.rules.pass.no3": "Po odbiciu byłyby trzy ataki, a następny gracz ma tylko dwie karty.",
            "ios.rules.end.h": "Koniec gry",
            "ios.rules.end.b": "Kiedy talia się wyczerpie, gra toczy się dalej. Kto pozbędzie się wszystkich kart, ten jest bezpieczny i durniem nie zostanie. Durniem zostaje ostatni gracz, któremu wciąż zostały karty.",
            "ios.rules.lobby.h": "Jak działa poczekalnia",
            "ios.rules.lobby.b": "Wpisz pseudonim, żeby dołączyć. Kiedy dołączy co najmniej dwóch graczy, każdy może nacisnąć Zacznij grać. Po rozpoczęciu gry nikt już nie dołączy.",
            "ios.rules.variant.h": "Odbijanie",
            "ios.rules.variant.b": "Poczekalnia decyduje, w jakiego Duraka gra ten stół, a to okienko pokazuje, który wariant jest wybrany. Zaznaczone to gra z odbijaniem (pieriewodnoj): broniący się, który ma kartę o tej samej wartości co atak, może ją położyć i przerzucić cały atak na następnego gracza, a ten musi się teraz bronić. Odznaczone to gra z dorzucaniem (podkidnoj): odbijania nie ma, więc broniący się albo kryje każdą kartę na stole, albo bierze wszystko. Dopóki poczekalnia jest otwarta, każdy przy stole może to zmienić; z chwilą rozpoczęcia gry ustawienie jest stałe.",
            "ios.rules.fool.h": "Dureń za to płaci",
            "ios.rules.fool.b": "Zwykle o tym, kto atakuje pierwszy, decyduje najniższy atut. Jest jeden wyjątek i jest to najstarszy rodzaj sprawiedliwości przy tym stole: jeśli po zakończonej grze naciśniesz Nowa gra i przy stole usiądą dokładnie ci sami gracze, najniższy atut nie decyduje o niczym. Otwiera gracz siedzący po prawej od ostatniego durnia, co znaczy, że dureń jest atakowany jako pierwszy. Przegrasz, a następna gra rusza od razu na ciebie. Jeśli przed startem ktoś dołączy albo wyjdzie, stół się zmienił i wraca zwykła zasada.",
            "ios.lobby.passing": "Z odbijaniem",
            "ios.rules.lbl.table": "na stole",
            "ios.rules.lbl.hand": "twoja ręka",
            "ios.rules.defender": "Broniący się",
            "ios.rules.nextplayer": "Następny gracz",
            "ios.msg.nametaken": "ten pseudonim jest już zajęty w tej grze",
            "ios.a11y.attackfirst": "Zaczynasz atak",
            "ios.a11y.on": "włączone",
