            "ios.tut_1": "Witaj w Duraku. Najniższy atut decyduje, kto atakuje pierwszy. Atut bije każdy inny kolor.",
            "ios.tut_2": "Żeby zaatakować, dotknij karty w swojej ręce. Przeciwnik musi ją przebić - albo wziąć wszystko.",
