            "ios.rej.addrank": "Підкинути можна лише те значення, яке вже є на столі.",
            "ios.rej.cover": "Це не поб’є - покрийте старшою картою тієї самої масті або козирем.",
            "ios.rej.capacity": "Забагато атак - у захисника стільки карт немає.",
            "ios.rej.passrank": "Перевести можна лише картою того самого значення.",
            "ios.rej.mustattack": "Перший нападник має атакувати.",
            "ios.rej.alreadygood": "Ви вже сказали бито.",
            "ios.rej.notake": "Немає чого брати.",
            "ios.help": "Правила",
            "ios.settings.title": "Налаштування",
            "ios.settings.table": "Стіл",
            "ios.settings.table.wool": "Вовна",
            "ios.settings.table.felt": "Зелене сукно",
            "ios.rules.title": "Як грати",
            "ios.rules.goal.h": "Мета гри",
            "ios.rules.goal.b": "Мета гри - якнайшвидше позбутися всіх своїх карт. Хто наприкінці лишається з картами, той і є дурень.",
            "ios.rules.setup.h": "Підготовка",
            "ios.rules.setup.b": "Якщо гравців четверо або менше, грають лише картами від 6 до туза. Двійки, трійки, четвірки і п’ятірки вилучають з колоди. Туз тут найстарший. Кожному роздають по 6 карт, потім тягнуть ще одну, кладуть її відкрито (сорочкою донизу) і засувають під колоду. МАСТЬ цієї відкритої карти і є козирною. Ця масть особлива, і чому - пояснено в розділі про захист.",
            "ios.rules.setup.cap": "Одна карта лежить відкритою під колодою - її масть козирна. У всіх прикладах на цій сторінці це чирви.",
            "ios.rules.start.h": "Початок гри",
            "ios.rules.start.b": "Починає той, у кого наймолодший козир. За справжнім столом це з’ясовують, питаючи, чи є в когось шістка, потім сімка і так далі. Тут гра робить це сама. Ця людина - перший нападник у раунді.",
            "ios.rules.sword": "Меч позначає нападника, який відкриває раунд.",
            "ios.rules.shield": "Щит позначає захисника.",
            "ios.rules.attack.h": "Атака",
            "ios.rules.attack.b": "Перший нападник раунду, позначений мечем, може обрати з руки будь-яку карту - або будь-який набір карт того самого ЗНАЧЕННЯ - і покласти їх перед гравцем ліворуч від себе (за годинниковою стрілкою). Цей гравець стає тим, хто захищається, він позначений щитом і має впоратися з атакою. Щоб атакувати, торкніться карт, аби їх обрати, і натисніть «Атака», що з’являється, коли обране є припустимим ходом. Або просто перетягніть карти з руки на стіл.",
            "ios.rules.attack.ok1": "Цей гравець може атакувати своєю дамою.",
            "ios.rules.attack.ok2": "Він також може атакувати двома королями одразу, бо в них однакове значення.",
            "ios.rules.attack.no1": "Він НЕ може атакувати сімкою і десяткою разом, бо це різні значення.",
            "ios.rules.defend.h": "Захист",
            "ios.rules.defend.b": "Гравець, якого зараз атакують і який позначений щитом, - це захисник. Він завжди один, і всі карти, покладені іншими, - його клопіт. Він може лише крити, взяти карти або перевести (якщо це дозволено). Захисник НЕ МОЖЕ атакувати. Усі інші - нападники, і вони можуть лише атакувати. Нападники НЕ МОЖУТЬ крити жодної карти на столі.",
            "ios.rules.defend.b.nopass": "Гравець, якого зараз атакують і який позначений щитом, - це захисник. Він завжди один, і всі карти, покладені іншими, - його клопіт. Він може лише крити або взяти карти. Захисник НЕ МОЖЕ атакувати. Усі інші - нападники, і вони можуть лише атакувати. Нападники НЕ МОЖУТЬ крити жодної карти на столі.",
            "ios.rules.cover.h": "Криття",
            "ios.rules.cover.b": "Захисник криє карти на столі, накриваючи кожну старшою картою тієї самої масті або будь-яким козирем. Саме це робить козирну масть особливою. Щоб крити, оберіть карту і натисніть «Крити». Або перетягніть карту з руки на ту, яку хочете накрити. Поширена помилка - думати, що вже криту карту можна накрити третьою. Гра працює не так. Ви ніколи не побачите на столі стосів по три карти. Уявіть карту атаки як меч, а карту захисту як щит: атаку зупинено, отже, її завершено. Можливі лише нові атаки, окремими стосами.",
            "ios.rules.cover.ok1": "Старша карта тієї самої масті криє.",
            "ios.rules.cover.ok2": "Будь-який козир криє будь-яку іншу масть - навіть молодшим значенням.",
            "ios.rules.cover.no1": "Козирну атаку треба крити старшим козирем - ця сімка замолода.",
            "ios.rules.cover.no2": "Значення старше, але масть не та - це нічого не криє.",
            "ios.rules.throw.h": "Підкидання",
            "ios.rules.throw.b": "Поки захисник криє, будь-який інший гравець може «підкинути» додаткові карти атаки, які захисникові теж доведеться крити. Правило просте, хоча звикнути до нього треба. Якщо ви бачите на столі ЗНАЧЕННЯ (наприклад, туз, 6, 10) карти, що є у вас на руках, і ви нападник, ви можете додати цю карту як окрему нову атаку. Про масті не думайте ВЗАГАЛІ. Єдине обмеження - кількість карт, які захисник тримає в руці. Некритих атак на столі не може бути більше, ніж карт у нього на руках. Уявіть, що захисник має відповісти на кожну карту атаки однією картою захисту; якщо атак забагато, це фізично неможливо, а отже, не дозволено. Ви можете подумати, що так кількість карт атаки почне швидко множитися. Саме так, і в цьому частина принади гри. Щоб атакувати, торкніться карти - або набору, де значення кожної карти вже є на столі, - і натисніть атаку. Або перетягніть карти з руки на стіл.",
            "ios.rules.throw.ok1": "На столі є дев’ятка, тож ваша дев’ятка теж піде - масті не мають значення.",
            "ios.rules.throw.ok2": "Обидві шістки одразу - дві нові атаки.",
            "ios.rules.throw.ok3": "Або шістка й дев’ятка разом - обидва значення вже на столі.",
            "ios.rules.throw.no1": "На столі немає ні вісімки, ні валета - підкидати нічого.",
            "ios.rules.throw.no2": "У захисника одна карта, а одна атака вже чекає - місця для ще однієї немає.",
            "ios.rules.pickup.h": "Взяття карт",
            "ios.rules.pickup.b": "Якщо захисник не може накрити всі карти або не хоче, він може натиснути кнопку «Взяти». Тоді він забирає зі столу кожну карту, навіть уже криту. І його хід пропускають, тож у наступному раунді атаку починає гравець ліворуч від нього. Тому добре подумайте, перш ніж брати.",
            "ios.rules.pickup.cap": "Візьміть тут - і всі три карти підуть вам у руку, крита пара теж.",
            "ios.rules.round.h": "Кінець раунду",
            "ios.rules.round.b": "Коли всі карти криті й жоден нападник більше не хоче підкидати, усе зі столу йде у відбій. Далі гравці добирають карти, починаючи з першого нападника і рухаючись за годинниковою стрілкою через усіх нападників, доки в кожного не стане щонайменше 6 карт. Останнім добирає захисник. Гра робить це сама. Коли колода закінчиться, гравці можуть почати виходити з карт і уникнути ролі дурня. Раунд також закінчується, якщо захисник бере карти, - нападники тоді добирають так само.",
            "ios.rules.pass.h": "Перевід",
            "ios.rules.pass.b": "У грі з переводом (переводний Дурень) захисник має ще й змогу перевести атаку від себе на гравця ліворуч. Для цього жодна карта на столі не має бути критою, а в нього має бути карта того самого ЗНАЧЕННЯ, що й усі карти атаки на столі. Тоді він кладе цю карту, і значок захисника переходить за годинниковою стрілкою до гравця ліворуч. Проте, так само як є межа кількості карт атаки, перевести не можна, якщо в гравця ліворуч менше карт, ніж було б атак після переводу. Наприклад: якщо на столі дві карти атаки, а гравець ліворуч тримає дві карти, перевести не вийде, бо після переводу там було б щонайменше 3 карти (2 плюс ще одна). Це більше, ніж у нього на руках, а отже, не дозволено. Щоб перевести, торкніться карти з відповідним значенням і натисніть «Перевести». Або перетягніть цю карту на вільне місце на столі.",
            "ios.rules.pass.ok1": "Атакує вісімка, і у вас є вісімка - покладіть її, і щит піде далі.",
            "ios.rules.pass.no1": "Щось уже крите - переводити пізно.",
            "ios.rules.pass.no2": "Вісімки на руках немає - цю атаку доведеться крити вам.",
            "ios.rules.pass.no3": "Після переводу було б три атаки, а наступний гравець тримає лише дві карти.",
            "ios.rules.end.h": "Кінець гри",
            "ios.rules.end.b": "Коли колода порожня, гра триває далі. Хто позбувся всіх карт, той у безпеці й дурнем не стане. Дурнем стає останній гравець, у якого ще лишилися карти.",
            "ios.rules.lobby.h": "Як працює лобі",
            "ios.rules.lobby.b": "Додайте своє ім’я, щоб приєднатися. Щойно приєднаються принаймні двоє гравців, будь-хто може натиснути «Почати грати». Після початку гри більше ніхто приєднатися не зможе.",
            "ios.rules.variant.h": "Перевід",
            "ios.rules.variant.b": "Лобі вирішує, в якого Дурня грає цей стіл, і прапорець показує, в якого. Позначено - це гра з переводом (переводний): захисник, у якого є карта того самого значення, що й атака, може покласти її й перевести всю атаку на наступного гравця, і тепер захищатися має він. Знято - це гра з підкиданням (підкидний): переводу немає, тож захисник або криє кожну карту на столі, або забирає все. Поки лобі відкрите, змінити це може будь-хто за столом; щойно гра почалася, налаштування зафіксовано.",
            "ios.rules.fool.h": "Дурень за це платить",
            "ios.rules.fool.b": "Зазвичай наймолодший козир вирішує, хто атакує першим. Є один виняток, і це найдавніший різновид справедливості в Дурні: якщо після закінченої гри натиснути «Нова гра» і за стіл сядуть точно ті самі гравці, наймолодший козир не вирішує нічого. Натомість починає гравець праворуч від останнього дурня, а отже, дурня атакують першим. Програєте - і наступна гра піде просто на вас. Якщо перед початком хтось приєднається або вийде, стіл змінився, і повертається звичайне правило.",
            "ios.lobby.passing": "З переводом",
