            "ios.tut_done": "Почати грати",
            "ios.tut_1": "Вітаємо в Дурні. Наймолодший козир вирішує, хто атакує першим. Козир б’є будь-яку іншу масть.",
            "ios.tut_2": "Щоб атакувати, торкніться карти на руках. Суперник має її побити - або забрати все.",
            "ios.tut_3": "Щоб захищатися, торкніться своєї карти, а потім атаки, яку вона б’є. Криє старша карта тієї самої масті або будь-який козир.",
            "ios.tut_4": "Не можете або не хочете захищатися? Торкніться «Взяти», щоб забрати карти. Закінчили атакувати? Торкніться «Бито».",
            "ios.tut_5": "Позбудьтеся карт раніше за інших. Останній гравець з картами - дурень. Успіху!",
