            "ios.rej.defending": "Savunuyorsun - saldırıyı kapat ya da kartları al.",
            "ios.rej.notyours": "O kart elinde değil.",
            "ios.rej.addrank": "Yalnızca masada olan bir değeri ekleyebilirsin.",
