            "ios.rej.passrank": "Aktarmak için aynı değerde bir kart gerekir.",
            "ios.rej.mustattack": "İlk saldıran saldırmak zorunda.",
            "ios.rej.alreadygood": "Zaten bitti dedin.",
            "ios.rej.notake": "Alınacak bir şey yok.",
            "ios.help": "Kurallar",
            "ios.settings.title": "Ayarlar",
            "ios.settings.table": "Masa",
            "ios.settings.table.wool": "Yün",
            "ios.settings.table.felt": "Yeşil çuha",
            "ios.rules.title": "Nasıl oynanır",
            "ios.rules.goal.h": "Amaç",
            "ios.rules.goal.b": "Oyunun amacı, elindeki bütün kartlardan olabildiğince çabuk kurtulmaktır. Sonunda elinde kart kalan kişi, Rusçada 'aptal' anlamına gelen дурак olur.",
            "ios.rules.setup.h": "Hazırlık",
            "ios.rules.setup.b": "Dört ya da daha az oyuncu varsa yalnızca 6'dan asa kadar olan kartlarla oynanır. 2'ler, 3'ler, 4'ler ve 5'ler desteden çıkarılır. Bu oyunda as en yüksek karttır. Her oyuncuya 6 kart dağıtılır, sonra bir kart daha çekilip yüzü açık olarak çekme destesinin altına konur. Açılan bu kartın RENGİ koz rengini belirler. Bu koz rengi özeldir; nedeni savunma bölümünde anlatılıyor.",
            "ios.rules.setup.cap": "Destenin altında yüzü açık duran bir kart var - onun rengi kozdur. Bu sayfadaki bütün örneklerde kupa.",
            "ios.rules.start.h": "Oyunun başlangıcı",
            "ios.rules.start.b": "Elinde en küçük koz olan başlar. Gerçek masada bu, kimde 6 var diye, sonra kimde 7 var diye sorularak bulunur. Burada bunu oyun otomatik olarak yapar. Bu kişi elin ilk saldıranıdır.",
            "ios.rules.sword": "Kılıç, eli açan saldıranı gösterir.",
            "ios.rules.shield": "Kalkan, savunanı gösterir.",
            "ios.rules.attack.h": "Saldırmak",
            "ios.rules.attack.b": "Kılıç simgesiyle işaretli, elin ilk saldıranı, elinden herhangi bir kartı - ya da hepsi aynı DEĞERDE olan bir kart grubunu - seçip solundaki oyuncuya doğru (saat yönünde) koyabilir. O oyuncu artık kalkan simgesiyle işaretli savunandır ve saldırıyla başa çıkmak zorundadır. Saldırmak için kartlara dokunup seç ve seçim geçerli bir hamle olduğunda beliren Saldır düğmesine bas. Ya da kartları elinden masaya sürükle.",
            "ios.rules.attack.ok1": "Bu oyuncu elindeki kızla saldırabilir.",
            "ios.rules.attack.ok2": "İki papazıyla aynı anda da saldırabilir, çünkü değerleri aynı.",
            "ios.rules.attack.no1": "7'si ve 10'uyla birlikte SALDIRAMAZ, çünkü değerleri farklı.",
            "ios.rules.defend.h": "Savunmak",
            "ios.rules.defend.b": "Kalkan simgesiyle işaretli, o an saldırıya uğrayan oyuncu savunandır. Aynı anda tek bir savunan olur ve diğerlerinin koyduğu bütün kartlar onun işidir. Savunan yalnızca kapatabilir, kartları alabilir ya da (izin veriliyorsa) aktarabilir. Savunan SALDIRAMAZ. Diğer herkes saldırandır ve yalnızca saldırabilir. Saldıranlar masadaki hiçbir kartı KAPATAMAZ.",
            "ios.rules.defend.b.nopass": "Kalkan simgesiyle işaretli, o an saldırıya uğrayan oyuncu savunandır. Aynı anda tek bir savunan olur ve diğerlerinin koyduğu bütün kartlar onun işidir. Savunan yalnızca kapatabilir ya da kartları alabilir. Savunan SALDIRAMAZ. Diğer herkes saldırandır ve yalnızca saldırabilir. Saldıranlar masadaki hiçbir kartı KAPATAMAZ.",
            "ios.rules.cover.h": "Kapatmak",
            "ios.rules.cover.b": "Savunan, masadaki kartların her birini aynı renkten daha yüksek bir kartla ya da herhangi bir kozla kapatabilir. Koz rengini özel yapan da budur. Kapatmak için bir kart seçip Kapat düğmesine bas. Ya da elindeki kartı masada kapatmak istediğin kartın üstüne sürükle. Sık yapılan bir hata, zaten kapatılmış bir kartın üçüncü bir kartla yeniden kapatılabileceğini sanmaktır. Oyun böyle işlemez. Masada asla üçlü yığın görmezsin. Saldırı kartını kılıç, kapatan kartı kalkan gibi düşün: saldırı durdurulmuştur, yani bitmiştir. Yalnızca ayrı yığınlar hâlinde yeni saldırılar yapılabilir.",
            "ios.rules.cover.ok1": "Aynı renkten daha yüksek bir kart kapatır.",
            "ios.rules.cover.ok2": "Herhangi bir koz, başka her rengi kapatır - değeri düşük olsa bile.",
            "ios.rules.cover.no1": "Koz saldırısı için daha yüksek bir koz gerekir - bu 7 fazla düşük.",
            "ios.rules.cover.no2": "Değer yüksek ama renk yanlış - bu hiçbir şeyi kapatmaz.",
            "ios.rules.throw.h": "Kart atmak",
            "ios.rules.throw.b": "Savunan kapatırken, diğer bütün oyuncular savunanın ayrıca kapatması gereken yeni saldırı kartları \"atabilir\". Kural basit, ama oturması biraz zaman alabilir. Elinde olan bir kartın DEĞERİNİ (örneğin A, 6, 10) masada görüyorsan ve saldıransan, o kartı ayrı yeni bir saldırı olarak masaya ekleyebilirsin. Renkleri HİÇ düşünme. Tek sınır, savunanın o anda elinde bulunan kart sayısıdır. Masadaki kapatılmamış saldırıların sayısı, savunanın elindeki kart sayısını geçemez. Savunanın her saldırı kartına tek bir savunma kartıyla karşılık verebilmesi gerektiğini düşün; saldırı sayısı fazlaysa bu fiziksel olarak imkânsızdır, bu yüzden de izin verilmez. Bu yolla saldırı kartlarının hızla çoğalabileceğini düşünüyorsan haklısın ve bu, oyunun tadının bir parçası. Saldırmak için bir karta - ya da her kartının değeri masada bulunan bir gruba - dokunup Saldır düğmesine bas. Ya da kartları elinden masaya sürükle.",
            "ios.rules.throw.ok1": "Masada bir 9 var, yani seninki de girebilir - renklerin önemi yok.",
            "ios.rules.throw.ok2": "İki 6 birden - iki yeni saldırı.",
            "ios.rules.throw.ok3": "Ya da 6 ile 9 birlikte - iki değer de zaten masada.",
            "ios.rules.throw.no1": "Masada ne 8 var ne vale - atacak bir şey yok.",
            "ios.rules.throw.no2": "Savunanın elinde bir kart var ve bir saldırı zaten bekliyor - bir tane daha atmaya yer yok.",
            "ios.rules.pickup.h": "Kartları almak",
            "ios.rules.pickup.b": "Savunan bütün kartları kapatamıyorsa ya da kapatmak istemiyorsa Al düğmesine basabilir. Böylece masadaki her kartı, zaten kapatılmış olanları bile alır. Ayrıca sırası atlanır, yani sonraki elde saldırıyı solundaki oyuncu açar. Bu yüzden almadan önce iyi düşün.",
            "ios.rules.pickup.cap": "Burada alırsan üç kart da sana geçer - kapatılmış çift de dahil.",
            "ios.rules.round.h": "Elin sonu",
            "ios.rules.round.b": "Bütün kartlar kapatıldığında ve saldıranların hiçbiri artık kart atmak istemediğinde, masadaki her şey ıskarta yığınına gider. Sonra ilk saldırandan başlayıp saat yönünde bütün saldıranlar, elleri 6 karta tamamlanana kadar kart çeker. En son savunan çeker. Bunu oyun otomatik olarak yapar. Deste bittiğinde oyuncular kartlarından kurtulup aptal olmaktan kaçınmaya başlayabilir. Savunan kartları alırsa da el biter; saldıranlar yine aynı şekilde çeker.",
            "ios.rules.pass.h": "Aktarmak",
            "ios.rules.pass.b": "переводной, yani \"aktarma\" izinli oynanan bir oyunda savunanın bir seçeneği daha vardır: saldırıyı üstünden atıp solundaki oyuncuya aktarmak. Bunun için masadaki hiçbir kartın kapatılmamış olması ve elinde, masadaki bütün saldırı kartlarıyla aynı DEĞERDE bir kart bulunması gerekir. O zaman kartı masaya koyar ve kalkan simgesi saat yönünde solundaki oyuncuya geçer. Ne var ki, saldırı kartı sayısında olduğu gibi burada da bir sınır vardır: soldaki oyuncunun elindeki kart sayısı, aktarmadan sonra masada olacak saldırı sayısından azsa aktarma yapılamaz. Örneğin masada iki saldırı kartı varsa ve soldaki oyuncunun elinde iki kart varsa, aktarma mümkün değildir; çünkü aktarma sonucunda masada en az 3 kart olurdu (2 artı aktarılan 1). Bu, onun elindekinden fazladır ve bu yüzden izin verilmez. Aktarmak için aynı değerdeki karta dokunup Aktar düğmesine bas. Ya da o kartı masadaki boş bir yere sürükle.",
            "ios.rules.pass.ok1": "Bir 8 saldırıyor ve elinde 8 var - koy, kalkan bir sonrakine geçsin.",
            "ios.rules.pass.no1": "Bir kart çoktan kapatılmış - aktarmak için geç kaldın.",
            "ios.rules.pass.no2": "Elinde 8 yok - bunu senin savunman gerek.",
            "ios.rules.pass.no3": "Aktarsan masada üç saldırı olurdu; sonraki oyuncunun elindeyse yalnızca iki kart var.",
            "ios.rules.end.h": "Oyunun sonu",
            "ios.rules.end.b": "Çekme destesi bittikten sonra oyun sürer. Bütün kartlarından kurtulan artık aptal olamaz. Elinde hâlâ kart bulunan son oyuncu aptal olur.",
            "ios.rules.lobby.h": "Lobi nasıl işler",
            "ios.rules.lobby.b": "Katılmak için adını yaz. En az iki oyuncu katıldığında herkes Başlat'a basabilir. Oyun başladıktan sonra kimse katılamaz.",
            "ios.rules.variant.h": "Aktarma",
            "ios.rules.variant.b": "Bu masanın hangi Durak'ı oynadığına lobi karar verir, kutucuk da hangisi olduğunu söyler. İşaretliyse aktarmalı oyundur (perevodnoy): elinde saldırıyla aynı değerde kart bulunan savunan, onu koyup bütün saldırıyı sıradaki oyuncuya aktarabilir; artık savunma sırası ondadır. İşaretsizse kart atmalı oyundur (podkidnoy): aktarma yoktur, yani savunan ya masadaki her kartı kapatır ya da hepsini alır. Lobi açık olduğu sürece masadaki herkes bunu değiştirebilir; oyun başladığında sabitlenir.",
            "ios.rules.fool.h": "Bedelini aptal öder",
            "ios.rules.fool.b": "Normalde ilk kimin saldıracağına en küçük koz karar verir. Bir istisna var ve bu, Durak adaletinin en eski hâli: bir oyun bittikten sonra Yeni oyun'a basarsan ve masaya tam olarak aynı oyuncular oturursa, en küçük koz hiçbir şeye karar vermez. Bunun yerine son aptalın sağındaki oyuncu açar, yani ilk saldırıya uğrayan aptal olur. Kaybedersen, sonraki oyun dosdoğru sana gelir. Başlat'tan önce biri katılır ya da ayrılırsa masa değişmiş olur ve normal kural geri gelir.",
            "ios.lobby.passing": "Aktarmalı",
            "ios.rules.lbl.table": "masada",
            "ios.rules.lbl.hand": "senin elin",
