            "ios.tut_done": "Oynamaya başla",
            "ios.tut_1": "Durak'a hoş geldin. En küçük koz kartı kimin ilk saldıracağını belirler. Koz, diğer bütün renkleri geçer.",
            "ios.tut_2": "Saldırmak için elindeki bir karta dokun. Rakibin ya onu geçecek ya da hepsini alacak.",
            "ios.tut_3": "Savunmak için önce kendi kartına, sonra onun geçtiği saldırıya dokun. Aynı renkten yüksek bir kart ya da herhangi bir koz onu kapatır.",
