            "ios.rej.alreadygood": "Kamu sudah bilang selesai.",
            "ios.rej.notake": "Tidak ada yang bisa diambil.",
            "ios.help": "Aturan",
            "ios.settings.title": "Pengaturan",
            "ios.settings.table": "Meja",
            "ios.settings.table.wool": "Kain wol",
            "ios.settings.table.felt": "Kain hijau",
            "ios.rules.title": "Cara bermain",
            "ios.rules.goal.h": "Tujuannya",
            "ios.rules.goal.b": "Tujuan permainan ini adalah menghabiskan semua kartumu secepat mungkin. Siapa yang masih pegang kartu di akhir permainan dialah дурак, Si Bodoh dalam bahasa Rusia.",
            "ios.rules.setup.h": "Persiapan",
            "ios.rules.setup.b": "Kalau pemainnya empat orang atau kurang, permainan memakai kartu 6 sampai As saja. Kartu 2, 3, 4, dan 5 dikeluarkan. As adalah kartu tertinggi di permainan ini. Setiap pemain dibagi 6 kartu, lalu satu kartu lagi ditarik, dibuka, dan diselipkan di bawah tumpukan penarikan. JENIS kartu yang dibuka itu menentukan jenis truf. Jenis truf ini istimewa, dan penjelasannya ada di bagian bertahan.",
            "ios.rules.setup.cap": "Satu kartu dibuka di bawah tumpukan - jenisnya adalah truf. Hati, di semua contoh pada halaman ini.",
            "ios.rules.start.h": "Awal permainan",
            "ios.rules.start.b": "Yang memegang kartu truf terkecil main duluan. Di meja sungguhan, ini ditentukan dengan bertanya siapa yang punya 6, lalu 7, dan seterusnya. Di sini permainan melakukannya sendiri. Orang ini menjadi penyerang pertama pada ronde tersebut.",
            "ios.rules.sword": "Pedang menandai penyerang yang membuka ronde.",
            "ios.rules.shield": "Perisai menandai pemain yang bertahan.",
            "ios.rules.attack.h": "Menyerang",
            "ios.rules.attack.b": "Penyerang pertama pada satu ronde, ditandai ikon pedang, boleh memilih kartu apa saja - atau beberapa kartu yang semuanya bernilai SAMA - dari tangannya, lalu meletakkannya ke arah pemain di sebelah kirinya (searah jarum jam). Pemain itu kini menjadi yang bertahan, ditandai ikon perisai, dan harus mengurus serangan itu. Untuk menyerang, ketuk kartu untuk memilihnya lalu tekan tombol serang yang muncul saat pilihanmu sudah sah. Atau cukup seret kartu dari tanganmu ke meja.",
            "ios.rules.attack.ok1": "Pemain ini boleh menyerang dengan Ratunya.",
            "ios.rules.attack.ok2": "Dia juga boleh menyerang dengan dua Raja sekaligus, karena nilainya sama.",
            "ios.rules.attack.no1": "Dia TIDAK boleh menyerang dengan 7 dan 10 sekaligus, karena nilainya berbeda.",
            "ios.rules.defend.h": "Bertahan",
            "ios.rules.defend.b": "Pemain yang sedang diserang, ditandai ikon perisai, adalah pemain bertahan. Hanya ada satu pemain bertahan pada satu waktu, dan semua kartu yang diletakkan pemain lain menjadi urusannya. Pemain bertahan hanya boleh menutup, mengambil kartu, atau mengoper (kalau diizinkan). Pemain bertahan TIDAK BOLEH menyerang. Semua pemain lain adalah penyerang dan hanya boleh menyerang. Penyerang TIDAK BOLEH menutup kartu apa pun di meja.",
            "ios.rules.defend.b.nopass": "Pemain yang sedang diserang, ditandai ikon perisai, adalah pemain bertahan. Hanya ada satu pemain bertahan pada satu waktu, dan semua kartu yang diletakkan pemain lain menjadi urusannya. Pemain bertahan hanya boleh menutup atau mengambil kartu. Pemain bertahan TIDAK BOLEH menyerang. Semua pemain lain adalah penyerang dan hanya boleh menyerang. Penyerang TIDAK BOLEH menutup kartu apa pun di meja.",
            "ios.rules.cover.h": "Menutup kartu",
            "ios.rules.cover.b": "Pemain bertahan menutup kartu di meja dengan menimpa setiap kartu memakai kartu berjenis sama yang nilainya lebih tinggi, atau memakai truf apa pun. Inilah yang membuat jenis truf istimewa. Untuk menutup, pilih sebuah kartu lalu ketuk tombol tutup. Bisa juga dengan menyeret kartu di tanganmu ke kartu yang ingin kamu tutup di meja. Kesalahan yang sering terjadi adalah mengira kartu yang sudah tertutup masih bisa ditutup lagi oleh kartu ketiga. Permainan ini tidak begitu. Kamu tidak akan pernah melihat tumpukan bertiga di meja. Bayangkan kartu serangan sebagai pedang dan kartu penutup sebagai perisai: serangannya sudah ditahan, jadi sudah selesai. Yang bisa dilakukan hanyalah serangan baru, di tumpukan terpisah.",
            "ios.rules.cover.ok1": "Kartu berjenis sama dengan nilai lebih tinggi bisa menutup.",
            "ios.rules.cover.ok2": "Truf apa pun bisa menutup jenis lain - bahkan kalau nilainya lebih kecil.",
            "ios.rules.cover.no1": "Serangan truf harus ditutup dengan truf yang lebih tinggi - 7 ini terlalu kecil.",
            "ios.rules.cover.no2": "Nilainya lebih tinggi tapi jenisnya salah - itu tidak menutup apa pun.",
            "ios.rules.throw.h": "Ikut menyerang",
            "ios.rules.throw.b": "Selagi pemain bertahan menutup kartu, semua pemain lain boleh \"melempar\" kartu serangan tambahan yang juga harus ditutup. Aturannya sederhana, meski perlu waktu untuk terbiasa. Kalau kamu melihat NILAI (misalnya A, 6, 10) dari kartu yang ada di tanganmu sudah ada di meja, dan kamu penyerang, kamu boleh menambahkan kartu itu sebagai serangan baru yang terpisah. Jangan pusingkan jenis kartunya SAMA SEKALI. Satu-satunya batas adalah jumlah kartu yang sedang dipegang pemain bertahan. Jumlah serangan yang belum tertutup di meja tidak boleh lebih banyak daripada kartu di tangannya. Bayangkan pemain bertahan harus bisa membalas setiap kartu serangan dengan satu kartu penutup; kalau serangannya terlalu banyak, itu mustahil, jadi tidak diperbolehkan. Mungkin kamu bertanya-tanya apakah jumlah kartu serangan bisa berlipat dengan cepat. Betul, dan itu bagian dari serunya permainan ini. Untuk menyerang, ketuk sebuah kartu - atau beberapa kartu yang nilainya sudah ada di meja semua - lalu tekan serang. Bisa juga dengan menyeret kartu dari tanganmu ke meja.",
            "ios.rules.throw.ok1": "Ada 9 di meja, jadi 9 milikmu boleh ikut - jenisnya tidak penting.",
            "ios.rules.throw.ok2": "Dua kartu 6 sekaligus - dua serangan baru.",
            "ios.rules.throw.ok3": "Atau 6 dan 9 bersamaan - kedua nilainya sudah ada di meja.",
            "ios.rules.throw.no1": "Tidak ada 8 dan tidak ada Jack di meja - tidak ada yang bisa dilempar.",
            "ios.rules.throw.no2": "Pemain bertahan pegang satu kartu dan satu serangan sudah menunggu - tidak ada ruang untuk yang lain.",
            "ios.rules.pickup.h": "Mengambil kartu",
            "ios.rules.pickup.b": "Kalau pemain bertahan tidak bisa menutup semua kartu atau tidak mau menutup, dia boleh menekan tombol ambil. Semua kartu di meja lalu masuk ke tangannya, termasuk yang sudah tertutup. Gilirannya juga dilewati, jadi pemain di sebelah kirinya yang mulai menyerang pada ronde berikutnya. Jadi pikirkan baik-baik sebelum memilih ambil.",
            "ios.rules.pickup.cap": "Ambil di sini dan ketiga kartunya masuk ke tanganmu - termasuk pasangan yang sudah tertutup.",
            "ios.rules.round.h": "Akhir ronde",
            "ios.rules.round.b": "Kalau semua kartu sudah tertutup dan tidak ada penyerang yang mau melempar lagi, semua kartu di meja masuk ke tumpukan buangan. Setelah itu pemain menarik kartu, mulai dari penyerang pertama lalu searah jarum jam melewati semua penyerang, sampai kartu masing-masing kembali menjadi 6. Pemain bertahan menarik terakhir. Permainan mengurusnya secara otomatis. Kalau tumpukan habis, pemain bisa mulai menghabiskan kartunya dan terhindar dari jadi Si Bodoh. Ronde juga berakhir kalau pemain bertahan memilih mengambil kartu; para penyerang tetap menarik kartu dengan cara yang sama.",
            "ios.rules.pass.h": "Mengoper",
            "ios.rules.pass.b": "Dalam permainan yang mengizinkan переводной alias \"oper\", pemain bertahan punya pilihan tambahan: mengoper serangan itu menjauh darinya, ke pemain di sebelah kirinya. Untuk itu, tidak boleh ada satu pun kartu di meja yang sudah tertutup, dan dia harus punya kartu dengan NILAI yang sama dengan semua kartu serangan di meja. Kartu itu lalu diletakkan, dan ikon bertahan berpindah searah jarum jam ke pemain di sebelah kirinya. Namun, sama seperti ada batas berapa kartu yang boleh menyerang, mengoper tidak boleh dilakukan kalau pemain di sebelah kiri punya kartu lebih sedikit daripada jumlah serangan yang akan ada setelah dioper. Misalnya, kalau ada dua kartu serangan di meja dan pemain di sebelah kiri pegang dua kartu, mengoper tidak mungkin, karena setelah dioper akan ada paling sedikit 3 kartu (2 ditambah 1 kartu operan). Itu lebih banyak daripada kartu di tangannya, jadi tidak diperbolehkan. Untuk mengoper, ketuk kartu yang nilainya sama lalu tekan tombol oper. Atau seret kartu itu ke bagian meja yang kosong.",
            "ios.rules.pass.ok1": "Kartu 8 sedang menyerang dan kamu pegang 8 - letakkan, dan perisainya pindah.",
            "ios.rules.pass.no1": "Sudah ada yang tertutup - terlambat untuk mengoper.",
            "ios.rules.pass.no2": "Tidak ada 8 di tanganmu - yang ini harus kamu tahan sendiri.",
            "ios.rules.pass.no3": "Mengoper akan membuat tiga serangan, sedangkan pemain berikutnya cuma pegang dua kartu.",
            "ios.rules.end.h": "Akhir permainan",
            "ios.rules.end.b": "Setelah tumpukan penarikan habis, permainan tetap berjalan. Siapa pun yang kartunya habis aman dari jadi Si Bodoh. Pemain terakhir yang masih punya kartu menjadi Si Bodoh.",
            "ios.rules.lobby.h": "Cara kerja lobi",
            "ios.rules.lobby.b": "Tulis namamu untuk gabung. Begitu ada minimal dua pemain, siapa saja boleh menekan Mulai main. Setelah permainan dimulai, tidak ada lagi yang bisa gabung.",
            "ios.rules.variant.h": "Mengoper",
            "ios.rules.variant.b": "Lobi menentukan Durak versi mana yang dimainkan meja ini, dan kotaknya menunjukkan yang mana. Tercentang berarti permainan pakai oper (perevodnoy): pemain bertahan yang punya kartu bernilai sama dengan serangan boleh meletakkannya dan mengoper seluruh serangan ke pemain berikutnya, yang sekarang harus bertahan. Kosong berarti permainan lempar kartu (podkidnoy): tidak ada oper, jadi pemain bertahan harus menutup semua kartu di meja atau mengambil semuanya. Siapa pun di meja boleh mengubahnya selama lobi masih terbuka; begitu permainan dimulai, pilihan itu terkunci.",
            "ios.rules.fool.h": "Si Bodoh yang kena getahnya",
            "ios.rules.fool.b": "Biasanya kartu truf terkecil yang menentukan siapa menyerang lebih dulu. Ada satu pengecualian, dan ini bentuk keadilan Durak yang paling tua: kalau kamu menekan Permainan baru setelah satu permainan selesai dan pemainnya persis sama, kartu truf terkecil tidak menentukan apa-apa. Yang membuka justru pemain di sebelah kanan Si Bodoh sebelumnya, artinya Si Bodoh yang pertama diserang. Kalah, dan permainan berikutnya langsung mengincarmu. Kalau ada yang gabung atau keluar sebelum Mulai main, mejanya sudah berubah dan aturan biasa berlaku lagi.",
            "ios.lobby.passing": "Pakai oper",
