            "ios.tut_1": "Selamat datang di Durak. Kartu truf terkecil menentukan siapa yang menyerang lebih dulu. Truf mengalahkan semua jenis lain.",
            "ios.tut_2": "Untuk menyerang, ketuk sebuah kartu di tanganmu. Lawanmu harus mengalahkannya - atau mengambil semuanya.",
            "ios.tut_3": "Untuk bertahan, ketuk salah satu kartumu, lalu ketuk serangan yang bisa ditutupi kartu itu. Kartu berjenis sama yang nilainya lebih tinggi, atau truf apa pun, bisa menutupnya.",
