            "ios.rules.setup.h": "การจัดเกม",
            "ios.rules.setup.b": "ถ้ามีผู้เล่นสี่คนหรือน้อยกว่า จะเล่นด้วยไพ่ตั้งแต่ 6 ถึงเอซเท่านั้น ไพ่ 2 3 4 และ 5 เอาออกจากกอง เอซเป็นไพ่ที่ใหญ่ที่สุดในเกมนี้ ผู้เล่นแต่ละคนได้ไพ่คนละ 6 ใบ จากนั้นจั่วอีกหนึ่งใบ หงายขึ้น แล้วสอดไว้ใต้กองจั่ว ดอกของไพ่ที่หงายใบนี้คือดอกทรัมป์ ดอกทรัมป์นี้พิเศษ และจะอธิบายไว้ในหัวข้อการป้อง",
            "ios.rules.setup.cap": "มีไพ่หงายอยู่หนึ่งใบใต้กองจั่ว ดอกของไพ่ใบนั้นคือทรัมป์ ในหน้านี้ทุกตัวอย่างใช้โพแดง",
            "ios.rules.start.h": "การเริ่มเกม",
            "ios.rules.start.b": "คนที่ถือไพ่ทรัมป์แต้มต่ำที่สุดเริ่มก่อน ถ้าเล่นกันจริงบนโต๊ะ จะถามกันว่าใครมี 6 ไหม แล้วก็ 7 ไล่ไปเรื่อย ๆ ที่นี่เกมจัดการให้เอง คนนี้คือคนโจมตีคนแรกของรอบ",
            "ios.rules.sword": "รูปดาบบอกว่าใครเป็นคนโจมตีที่เปิดรอบ",
            "ios.rules.shield": "รูปโล่บอกว่าใครเป็นคนป้อง",
            "ios.rules.attack.h": "การโจมตี",
            "ios.rules.attack.b": "คนโจมตีคนแรกของรอบซึ่งมีเครื่องหมายดาบ จะเลือกไพ่ใบไหนก็ได้จากในมือ หรือเลือกหลายใบที่มีแต้มเท่ากันทั้งหมด แล้ววางไปทางผู้เล่นที่นั่งทางซ้าย ตามเข็มนาฬิกา ผู้เล่นคนนั้นกลายเป็นคนป้อง มีเครื่องหมายโล่ และต้องจัดการกับไพ่ที่โจมตีมา วิธีโจมตีคือแตะไพ่เพื่อเลือก แล้วกดปุ่มโจมตีที่โผล่ขึ้นมาเมื่อไพ่ที่เลือกเป็นตาเดินที่ถูกกติกา หรือจะลากไพ่จากมือไปวางบนโต๊ะเลยก็ได้",
            "ios.rules.attack.ok1": "ผู้เล่นคนนี้โจมตีด้วยควีนได้",
            "ios.rules.attack.ok2": "จะโจมตีด้วยคิงสองใบพร้อมกันก็ได้ เพราะแต้มเท่ากัน",
            "ios.rules.attack.no1": "แต่โจมตีด้วย 7 กับ 10 พร้อมกันไม่ได้ เพราะแต้มไม่เท่ากัน",
            "ios.rules.defend.h": "การป้อง",
            "ios.rules.defend.b": "ผู้เล่นที่กำลังถูกโจมตีอยู่ตอนนี้ ซึ่งมีเครื่องหมายโล่ คือคนป้อง แต่ละครั้งจะมีคนป้องได้คนเดียวเท่านั้น และไพ่ทุกใบที่คนอื่นวางลงมาเป็นเรื่องที่คนป้องต้องจัดการ คนป้องทำได้แค่ป้อง เก็บไพ่ หรือส่งต่อ ถ้ากติกาอนุญาต คนป้องโจมตีไม่ได้ คนที่เหลือทั้งหมดเป็นคนโจมตี และทำได้แค่โจมตีเท่านั้น คนโจมตีจะป้องไพ่ใบใดบนโต๊ะไม่ได้",
            "ios.rules.defend.b.nopass": "ผู้เล่นที่กำลังถูกโจมตีอยู่ตอนนี้ ซึ่งมีเครื่องหมายโล่ คือคนป้อง แต่ละครั้งจะมีคนป้องได้คนเดียวเท่านั้น และไพ่ทุกใบที่คนอื่นวางลงมาเป็นเรื่องที่คนป้องต้องจัดการ คนป้องทำได้แค่ป้องหรือเก็บไพ่เท่านั้น คนป้องโจมตีไม่ได้ คนที่เหลือทั้งหมดเป็นคนโจมตี และทำได้แค่โจมตีเท่านั้น คนโจมตีจะป้องไพ่ใบใดบนโต๊ะไม่ได้",
            "ios.rules.cover.h": "การป้องไพ่",
            "ios.rules.cover.b": "คนป้องป้องไพ่บนโต๊ะได้ด้วยการวางไพ่ดอกเดียวกันที่แต้มสูงกว่าทับลงบนไพ่แต่ละใบ หรือจะใช้ไพ่ทรัมป์ใบไหนก็ได้ นี่แหละคือสิ่งที่ทำให้ดอกทรัมป์พิเศษ วิธีป้องคือเลือกไพ่แล้วแตะปุ่มป้อง หรือจะลากไพ่ในมือไปวางทับไพ่ที่ต้องการป้องบนโต๊ะก็ได้ คนมักเข้าใจผิดว่าไพ่ที่ถูกป้องไปแล้วยังเอาใบที่สามมาทับต่อได้อีก เกมนี้ไม่ได้เล่นแบบนั้น คุณจะไม่มีวันเห็นไพ่ซ้อนกันสามใบบนโต๊ะ ให้คิดว่าไพ่ที่โจมตีมาคือดาบ และไพ่ที่ใช้ป้องคือโล่ การโจมตีถูกสกัดแล้ว จึงถือว่าจบไป ทำได้แค่โจมตีใหม่เป็นกองแยกต่างหากเท่านั้น",
            "ios.rules.cover.ok1": "ไพ่ดอกเดียวกันที่แต้มสูงกว่าป้องได้",
            "ios.rules.cover.ok2": "ไพ่ทรัมป์ใบไหนก็ป้องไพ่ดอกอื่นได้ทั้งนั้น แม้แต้มจะต่ำกว่าก็ตาม",
            "ios.rules.cover.no1": "ไพ่ทรัมป์ที่โจมตีมาต้องป้องด้วยทรัมป์ที่สูงกว่า - ใบ 7 นี้ต่ำเกินไป",
            "ios.rules.cover.no2": "แต้มสูงกว่าก็จริง แต่ผิดดอก - แบบนี้ป้องอะไรไม่ได้เลย",
            "ios.rules.throw.h": "การโยนเพิ่ม",
            "ios.rules.throw.b": "ระหว่างที่คนป้องกำลังป้องอยู่ ผู้เล่นคนอื่นทุกคนโยนไพ่โจมตีเพิ่มเข้าไปได้ และคนป้องต้องป้องไพ่พวกนั้นด้วย กติกาง่ายมาก แต่ต้องใช้เวลาทำความเข้าใจสักหน่อย ถ้าคุณเห็นแต้มของไพ่ที่คุณมีในมือ เช่น A, 6, 10 อยู่บนโต๊ะแล้ว และคุณเป็นคนโจมตี คุณเอาไพ่ใบนั้นลงไปเป็นการโจมตีใหม่แยกกองได้เลย เรื่องดอกไม่ต้องสนใจเลยแม้แต่นิดเดียว ข้อจำกัดมีอย่างเดียวคือจำนวนไพ่ในมือของคนป้องตอนนั้น ไพ่โจมตีที่ยังไม่ถูกป้องบนโต๊ะจะมีมากกว่าจำนวนไพ่ในมือคนป้องไม่ได้ ให้นึกว่าคนป้องต้องตอบไพ่โจมตีแต่ละใบด้วยไพ่ป้องหนึ่งใบพอดี ถ้าไพ่โจมตีเยอะเกินไปก็ทำไม่ได้จริง ๆ กติกาจึงไม่อนุญาต คุณอาจสงสัยว่าแบบนี้จำนวนไพ่โจมตีจะทวีขึ้นเร็วมากหรือเปล่า ใช่แล้ว และนั่นก็เป็นเสน่ห์อย่างหนึ่งของเกมนี้ วิธีโจมตีคือแตะไพ่หนึ่งใบ หรือหลายใบที่แต้มของทุกใบมีอยู่บนโต๊ะแล้ว จากนั้นกดโจมตี หรือจะลากไพ่จากมือไปวางบนโต๊ะก็ได้",
            "ios.rules.throw.ok1": "บนโต๊ะมี 9 อยู่แล้ว ไพ่ 9 ของคุณจึงลงได้ - ดอกไม่เกี่ยว",
            "ios.rules.throw.ok2": "ลงไพ่ 6 ทั้งสองใบพร้อมกัน - เป็นการโจมตีใหม่สองครั้ง",
            "ios.rules.throw.ok3": "หรือจะลง 6 กับ 9 พร้อมกันก็ได้ - แต้มทั้งสองมีอยู่บนโต๊ะแล้ว",
            "ios.rules.throw.no1": "บนโต๊ะไม่มีทั้ง 8 และแจ็ค - ไม่มีอะไรให้โยนเพิ่ม",
            "ios.rules.throw.no2": "คนป้องเหลือไพ่ใบเดียว และมีไพ่โจมตีรออยู่แล้วหนึ่งใบ - ไม่มีที่ให้ใบต่อไป",
            "ios.rules.pickup.h": "การเก็บไพ่",
            "ios.rules.pickup.b": "ถ้าคนป้องป้องไพ่ทั้งหมดไม่ไหว หรือไม่อยากป้อง ก็กดปุ่มเก็บได้ คนป้องจะเก็บไพ่บนโต๊ะไปทุกใบ รวมถึงใบที่ถูกป้องไปแล้วด้วย แล้วตาของคนป้องจะถูกข้าม รอบถัดไปคนที่นั่งทางซ้ายจะเป็นคนเริ่มโจมตี ฉะนั้นคิดให้ดีก่อนตัดสินใจเก็บ",
            "ios.rules.pickup.cap": "ถ้าเก็บตรงนี้ ไพ่ทั้งสามใบจะเข้ามือคุณ - รวมถึงคู่ที่ถูกป้องไปแล้วด้วย",
            "ios.rules.round.h": "จบรอบ",
            "ios.rules.round.b": "เมื่อไพ่ทุกใบถูกป้องหมด และคนโจมตีทุกคนบอกว่าพอแล้ว ไพ่ทั้งหมดบนโต๊ะจะไปกองทิ้ง จากนั้นผู้เล่นจั่วไพ่ เริ่มจากคนโจมตีคนแรก ไล่ตามเข็มนาฬิกาไปจนครบทุกคนโจมตี จั่วจนมีไพ่ในมืออย่างน้อย 6 ใบ แล้วคนป้องจั่วเป็นคนสุดท้าย เกมจัดการให้เอง ถ้ากองจั่วหมดแล้วก็ไม่มีการจั่วอีก ผู้เล่นจะเริ่มทิ้งไพ่ในมือให้หมดเพื่อไม่ต้องเป็นคนโง่ รอบจะจบลงด้วยเมื่อคนป้องเลือกเก็บไพ่ กรณีนั้นไพ่บนโต๊ะจะเข้ามือคนป้องแทนที่จะไปกองทิ้ง แล้วจั่วต่อตามลำดับเดิม โดยคนป้องจั่วเป็นคนสุดท้าย ซึ่งตามปกติแล้วก็คือไม่ได้จั่วเลย เพราะถือไพ่เกินหกใบอยู่แล้ว",
            "ios.rules.pass.h": "การส่งต่อ",
            "ios.rules.pass.b": "ในเกมที่อนุญาตให้ переводной หรือการส่งต่อ คนป้องมีอีกทางเลือกหนึ่งคือส่งการโจมตีต่อไปให้ผู้เล่นทางซ้าย จะทำแบบนั้นได้ต้องยังไม่มีไพ่ใบไหนบนโต๊ะถูกป้อง และคนป้องต้องมีไพ่ที่แต้มเท่ากับไพ่โจมตีทุกใบบนโต๊ะ จากนั้นก็วางไพ่ใบนั้นลง แล้วเครื่องหมายคนป้องจะเลื่อนตามเข็มนาฬิกาไปยังผู้เล่นทางซ้าย แต่เช่นเดียวกับที่มีข้อจำกัดเรื่องจำนวนไพ่โจมตี การส่งต่อทำไม่ได้ถ้าผู้เล่นทางซ้ายมีไพ่ในมือน้อยกว่าจำนวนไพ่โจมตีที่จะมีหลังส่งต่อ เช่น ถ้าบนโต๊ะมีไพ่โจมตีสองใบ และผู้เล่นทางซ้ายถือไพ่อยู่สองใบ ก็ส่งต่อไม่ได้ เพราะหลังส่งต่อจะมีไพ่อย่างน้อย 3 ใบ คือ 2 ใบเดิมบวกอีกหนึ่งใบที่ส่งต่อ ซึ่งมากกว่าไพ่ในมือเขา กติกาจึงไม่อนุญาต วิธีส่งต่อคือแตะไพ่ที่แต้มตรงกันแล้วกดปุ่มส่งต่อ หรือจะลากไพ่ใบนั้นไปวางที่ว่างบนโต๊ะก็ได้",
            "ios.rules.pass.ok1": "ไพ่ 8 โจมตีมา และคุณก็มี 8 - วางลงไป แล้วโล่ก็เลื่อนต่อไป",
            "ios.rules.pass.no1": "มีไพ่ถูกป้องไปแล้ว - สายเกินกว่าจะส่งต่อ",
            "ios.rules.pass.no2": "ในมือไม่มี 8 - ใบนี้คุณต้องป้องเอง",
            "ios.rules.pass.no3": "ถ้าส่งต่อจะกลายเป็นไพ่โจมตีสามใบ แต่ผู้เล่นคนถัดไปถือไพ่อยู่แค่สองใบ",
            "ios.rules.end.h": "จบเกม",
            "ios.rules.end.b": "เมื่อกองจั่วหมดแล้ว เกมยังเล่นต่อไป ใครทิ้งไพ่ในมือหมดก่อนก็รอดพ้นจากการเป็นคนโง่ ผู้เล่นคนสุดท้ายที่ยังเหลือไพ่อยู่จะกลายเป็นคนโง่",
            "ios.rules.lobby.h": "ห้องรอทำงานยังไง",
            "ios.rules.lobby.b": "ใส่ชื่อของคุณเพื่อเข้าร่วม พอมีผู้เล่นอย่างน้อยสองคนแล้ว ใครก็กดเริ่มเล่นได้ เมื่อเกมเริ่มไปแล้วจะไม่มีใครเข้าร่วมได้อีก",
            "ios.rules.variant.h": "การส่งต่อ",
            "ios.rules.variant.b": "เลือกได้ในห้องรอว่าโต๊ะนี้จะเล่นดูรักแบบไหน และช่องนี้บอกว่าเลือกแบบไหนอยู่ ถ้าติ๊กไว้คือเล่นแบบส่งต่อได้ เรียกว่า perevodnoy คนป้องที่มีไพ่แต้มเท่ากับไพ่ที่โจมตีมา วางไพ่ใบนั้นลงแล้วส่งการโจมตีทั้งหมดต่อไปให้ผู้เล่นคนถัดไปได้ และคนนั้นต้องเป็นคนป้องแทน ถ้าไม่ติ๊กคือเล่นแบบโยนเพิ่ม เรียกว่า podkidnoy ไม่มีการส่งต่อ คนป้องจึงต้องป้องไพ่ทุกใบบนโต๊ะ ไม่ก็เก็บไปทั้งหมด ตราบใดที่ห้องรอยังเปิดอยู่ ใครก็ตามที่อยู่ที่โต๊ะนี้เปลี่ยนได้ พอเกมเริ่มแล้วจะล็อกไว้",
            "ios.rules.fool.h": "คนโง่ต้องชดใช้",
            "ios.rules.fool.b": "ปกติแล้วไพ่ทรัมป์แต้มต่ำสุดเป็นตัวตัดสินว่าใครโจมตีก่อน แต่มีข้อยกเว้นอยู่ข้อหนึ่ง และเป็นความยุติธรรมแบบดูรักที่เก่าแก่ที่สุด ถ้าคุณกดเกมใหม่หลังจบเกม แล้วผู้เล่นชุดเดิมเป๊ะ ๆ กลับมานั่งอีกครั้ง ไพ่ทรัมป์แต้มต่ำสุดจะไม่ตัดสินอะไรทั้งนั้น คนที่เปิดเกมคือผู้เล่นที่นั่งทางขวาของคนโง่คนล่าสุด ซึ่งแปลว่าคนโง่จะเป็นคนแรกที่ถูกโจมตี แพ้แล้วเกมต่อไปก็พุ่งมาหาคุณทันที ถ้ามีคนเข้าหรือออกก่อนเริ่มเกม ถือว่าโต๊ะเปลี่ยนไปแล้ว กติกาปกติก็กลับมาใช้เหมือนเดิม",
