            "ios.rej.pickone": "Kies eerst een kaart.",
            "ios.rej.defending": "Jij verdedigt - dek de aanval af of pak de kaarten.",
            "ios.rej.notyours": "Die kaart heb je niet in je hand.",
            "ios.rej.addrank": "Je mag alleen een kaart bijleggen waarvan de waarde al op tafel ligt.",
            "ios.rej.cover": "Daarmee dek je niet af - speel hoger in dezelfde kleur, of een troef.",
            "ios.rej.capacity": "Te veel aanvallen voor de hand van de verdediger.",
            "ios.rej.passrank": "Doorschuiven kan alleen met een kaart van dezelfde waarde.",
            "ios.rej.mustattack": "De eerste aanvaller moet aanvallen.",
            "ios.rej.alreadygood": "Je hebt al Klaar gezegd.",
            "ios.rej.notake": "Er is niets om te pakken.",
            "ios.help": "Regels",
            "ios.settings.title": "Instellingen",
            "ios.settings.table": "Tafel",
            "ios.settings.table.wool": "Wol",
            "ios.settings.table.felt": "Groen laken",
            "ios.rules.title": "Zo speel je",
            "ios.rules.goal.h": "Het doel",
            "ios.rules.goal.b": "Het doel van het spel is zo snel mogelijk al je kaarten kwijt te raken. Wie aan het eind nog kaarten heeft, is de дурак, Russisch voor sukkel.",
            "ios.rules.setup.h": "Opzet",
            "ios.rules.setup.b": "Met vier spelers of minder wordt er alleen gespeeld met de kaarten van 6 tot en met aas. De tweeën, drieën, vieren en vijven gaan eruit. De aas is de hoogste kaart. Iedere speler krijgt 6 kaarten, daarna wordt er nog een kaart getrokken, opengelegd en onder de stapel geschoven. De KLEUR van die open kaart is de troefkleur. Die kleur is bijzonder, en waarom staat bij het verdedigen.",
            "ios.rules.setup.cap": "Er ligt een open kaart onder de stapel - die kleur is troef. Harten, in alle voorbeelden op deze pagina.",
            "ios.rules.start.h": "Het begin",
            "ios.rules.start.b": "Wie de laagste troef heeft, begint. Aan een echte tafel zoek je dat uit door te vragen wie een 6 heeft, dan een 7, en zo verder. Hier doet het spel dat zelf. Deze persoon is de eerste aanvaller van de ronde.",
            "ios.rules.sword": "Het zwaard markeert de aanvaller die de ronde opent.",
            "ios.rules.shield": "Het schild markeert de verdediger.",
            "ios.rules.attack.h": "Aanvallen",
            "ios.rules.attack.b": "De eerste aanvaller van een ronde, gemarkeerd met een zwaard, mag uit zijn hand een willekeurige kaart kiezen - of meerdere kaarten met dezelfde WAARDE - en die voor de speler links van hem leggen (met de klok mee). Die speler is nu de verdediger, gemarkeerd met een schild, en moet iets met de aanval doen. Om aan te vallen tik je kaarten aan om ze te kiezen en druk je op de knop Aanvallen die verschijnt zodra je keuze een geldige zet is. Of sleep je de kaarten gewoon van je hand naar de tafel.",
            "ios.rules.attack.ok1": "Deze speler mag met de vrouw aanvallen.",
            "ios.rules.attack.ok2": "Hij mag ook met allebei de heren tegelijk aanvallen, want die hebben dezelfde waarde.",
            "ios.rules.attack.no1": "Hij mag NIET met de 7 en de 10 samen aanvallen, want dat zijn verschillende waarden.",
            "ios.rules.defend.h": "Verdedigen",
            "ios.rules.defend.b": "De speler die op dat moment wordt aangevallen, gemarkeerd met het schild, is de verdediger. Er is er altijd maar één tegelijk, en alle kaarten die de anderen neerleggen moet hij zien af te dekken. De verdediger mag alleen afdekken, de kaarten pakken of doorschuiven (als dat mag). De verdediger mag NIET aanvallen. Alle anderen zijn aanvallers en mogen alleen aanvallen. Aanvallers mogen GEEN enkele kaart op tafel afdekken.",
            "ios.rules.defend.b.nopass": "De speler die op dat moment wordt aangevallen, gemarkeerd met het schild, is de verdediger. Er is er altijd maar één tegelijk, en alle kaarten die de anderen neerleggen moet hij zien af te dekken. De verdediger mag alleen afdekken of de kaarten pakken. De verdediger mag NIET aanvallen. Alle anderen zijn aanvallers en mogen alleen aanvallen. Aanvallers mogen GEEN enkele kaart op tafel afdekken.",
            "ios.rules.cover.h": "Afdekken",
            "ios.rules.cover.b": "De verdediger kan de kaarten op tafel afdekken door op elke kaart een hogere kaart van dezelfde kleur te leggen, of een willekeurige troef. Dat is wat de troefkleur bijzonder maakt. Om af te dekken kies je een kaart en tik je op de knop Dekken. Je kunt ook een kaart uit je hand op de kaart slepen die je wilt afdekken. Een veelgemaakte denkfout is dat een al afgedekte kaart nog eens met een derde kaart afgedekt kan worden. Zo werkt het spel niet: je ziet nooit stapels van drie op tafel. Zie de aanvalskaart als een zwaard en de afdekkende kaart als een schild: de aanval is geblokkeerd en daarmee afgelopen. Alleen nieuwe aanvallen zijn mogelijk, op aparte stapeltjes.",
            "ios.rules.cover.ok1": "Een hogere kaart van dezelfde kleur dekt af.",
            "ios.rules.cover.ok2": "Elke troef dekt elke andere kleur af - ook met een lagere waarde.",
            "ios.rules.cover.no1": "Een troefaanval vraagt om een hogere troef - deze 7 is te laag.",
            "ios.rules.cover.no2": "Hogere waarde, verkeerde kleur - daarmee dek je niets af.",
            "ios.rules.throw.h": "Bijleggen",
            "ios.rules.throw.b": "Terwijl de verdediger aan het afdekken is, mag elke andere speler er aanvalskaarten \"bijleggen\" die de verdediger er ook nog bij moet afdekken. De regel is simpel, al kost het even om hem te pakken te krijgen. Zie je op tafel de WAARDE (bijvoorbeeld A, 6, 10) van een kaart die jij in je hand hebt, en ben je aanvaller, dan mag je die kaart erbij leggen als een losse nieuwe aanval. Om de kleuren hoef je je HELEMAAL niet te bekommeren. De enige grens is het aantal kaarten dat de verdediger op dat moment in zijn hand heeft: er mogen nooit meer niet-afgedekte aanvallen op tafel liggen dan hij kaarten heeft. Stel je voor dat de verdediger op elke aanvalskaart met precies één afdekkende kaart moet kunnen antwoorden; bij te veel aanvallen kan dat gewoon niet, en daarom mag het niet. Misschien vraag je je af of het aantal aanvalskaarten zo niet razendsnel oploopt. Precies, en dat is een deel van de lol van het spel. Om aan te vallen tik je een kaart aan - of meerdere kaarten waarvan elke waarde al op tafel ligt - en druk je op Aanvallen. Of je sleept de kaarten van je hand naar de tafel.",
            "ios.rules.throw.ok1": "Er ligt een 9 op tafel, dus jouw 9 mag erbij - de kleuren doen er niet toe.",
            "ios.rules.throw.ok2": "Allebei de zessen tegelijk - twee nieuwe aanvallen.",
            "ios.rules.throw.ok3": "Of de 6 en de 9 samen - allebei die waarden liggen er al.",
            "ios.rules.throw.no1": "Geen 8 en geen boer op tafel - er valt niets bij te leggen.",
            "ios.rules.throw.no2": "De verdediger heeft nog maar één kaart en er wacht al een aanval - er kan er geen meer bij.",
            "ios.rules.pickup.h": "Kaarten pakken",
            "ios.rules.pickup.b": "Kan de verdediger niet alle kaarten afdekken, of wil hij dat niet, dan kan hij op de knop Pakken drukken. Hij neemt dan elke kaart van tafel, ook de kaarten die al afgedekt waren. Bovendien wordt zijn beurt overgeslagen, dus de speler links van hem begint de volgende ronde met aanvallen. Denk dus goed na voor je pakt.",
            "ios.rules.pickup.cap": "Pak je hier, dan gaan alle drie de kaarten naar je hand - het afgedekte paar ook.",
            "ios.rules.round.h": "Einde van de ronde",
            "ios.rules.round.b": "Zijn alle kaarten afgedekt en wil geen enkele aanvaller er nog iets bij leggen, dan gaat alles van tafel naar de aflegstapel. Daarna wordt er bijgepakt, te beginnen bij de eerste aanvaller en met de klok mee langs alle aanvallers, tot iedereen weer minstens 6 kaarten heeft. De verdediger pakt als laatste bij. Het spel doet dat vanzelf. Is de stapel leeg, dan wordt er niet meer bijgepakt en kunnen spelers hun kaarten kwijtraken en zo aan de rol van sukkel ontkomen. De ronde eindigt ook als de verdediger de kaarten pakt: die gaan dan naar zijn hand in plaats van naar de aflegstapel, en daarna wordt er in dezelfde volgorde bijgepakt - de verdediger als laatste, wat meestal neerkomt op helemaal niet, want hij houdt er dan meer dan zes.",
            "ios.rules.pass.h": "Doorschuiven",
            "ios.rules.pass.b": "In een spel waarin de переводной, het \"doorschuiven\", is toegestaan, kan de verdediger de aanval ook van zich af schuiven naar de speler links van hem. Daarvoor mag geen enkele kaart op tafel afgedekt zijn, en moet hij een kaart hebben met dezelfde WAARDE als alle aanvalskaarten op tafel. Die legt hij dan neer, en het schild schuift met de klok mee door naar de speler links van hem. Net als er een grens is aan het aantal aanvalskaarten, kan doorschuiven niet als de speler links minder kaarten heeft dan er na het doorschuiven aanvallen zouden liggen. Liggen er bijvoorbeeld twee aanvalskaarten op tafel en heeft de speler links twee kaarten, dan kan doorschuiven niet: er zouden dan minstens 3 kaarten liggen (2 plus de doorgeschoven kaart). Dat is meer dan hij in zijn hand heeft, en dus mag het niet. Om door te schuiven tik je de kaart met de passende waarde aan en druk je op de knop Schuiven. Of je sleept die kaart naar een lege plek op tafel.",
            "ios.rules.pass.ok1": "Er valt een 8 aan en jij hebt een 8 - leg hem neer en het schild schuift door.",
            "ios.rules.pass.no1": "Er is al iets afgedekt - te laat om door te schuiven.",
            "ios.rules.pass.no2": "Geen 8 in je hand - deze moet je zelf verdedigen.",
            "ios.rules.pass.no3": "Doorschuiven zou drie aanvallen opleveren, en de volgende speler heeft maar twee kaarten.",
            "ios.rules.end.h": "Einde van het spel",
            "ios.rules.end.b": "Is de stapel leeg, dan gaat het spel gewoon door. Wie al zijn kaarten kwijtraakt, kan de sukkel niet meer worden. De laatste speler die nog kaarten heeft, wordt de sukkel.",
            "ios.rules.lobby.h": "Hoe de lobby werkt",
            "ios.rules.lobby.b": "Vul je naam in om mee te doen. Zodra er minstens twee spelers zijn, mag iedereen op Spel starten drukken. Als het spel eenmaal begonnen is, kan er niemand meer bij.",
            "ios.rules.variant.h": "Doorschuiven",
            "ios.rules.variant.b": "In de lobby wordt gekozen welke Durak er aan deze tafel gespeeld wordt, en het vakje laat zien welke. Aangevinkt is het spel met doorschuiven (perevodnoj): een verdediger met een kaart van dezelfde waarde als de aanval mag die neerleggen en de hele aanval doorschuiven naar de volgende speler, die zich nu moet verdedigen. Niet aangevinkt is het spel met bijleggen (podkidnoj): er wordt niet doorgeschoven, dus de verdediger dekt elke kaart op tafel af of pakt alles. Zolang de lobby open is mag iedereen aan tafel het wisselen; zodra het spel begint, ligt het vast.",
            "ios.rules.fool.h": "De sukkel betaalt ervoor",
            "ios.rules.fool.b": "Normaal bepaalt de laagste troef wie als eerste aanvalt. Er is een uitzondering, en dat is de oudste vorm van Durak-recht: druk je na afloop op Nieuw spel en gaan precies dezelfde spelers weer zitten, dan bepaalt de laagste troef niets. Dan opent de speler rechts van de vorige sukkel, en dat betekent dat de sukkel als eerste wordt aangevallen. Verlies je, dan komt het volgende spel meteen op je af. Doet er voor de start iemand mee of gaat er iemand weg, dan is de tafel veranderd en geldt de gewone regel weer.",
            "ios.lobby.passing": "Met doorschuiven",
            "ios.rules.lbl.table": "op tafel",
            "ios.rules.lbl.hand": "jouw hand",
