            "ios.rej.cover": "Det täcker inte - spela högre i samma färg, eller en trumf.",
            "ios.rej.capacity": "För många anfall för försvararens hand.",
            "ios.rej.passrank": "Du kan bara skicka vidare med ett kort av samma valör.",
            "ios.rej.mustattack": "Den första anfallaren måste anfalla.",
            "ios.rej.alreadygood": "Du har redan sagt Klar.",
            "ios.rej.notake": "Det finns inget att ta.",
            "ios.help": "Regler",
            "ios.settings.title": "Inställningar",
            "ios.settings.table": "Bord",
            "ios.settings.table.wool": "Ylle",
            "ios.settings.table.felt": "Grön filt",
            "ios.rules.title": "Så spelar du",
            "ios.rules.goal.h": "Målet",
            "ios.rules.goal.b": "Målet med spelet är att bli av med alla sina kort så fort som möjligt. Den som sitter kvar med kort på slutet är дурак - dumbommen, på ryska.",
            "ios.rules.setup.h": "Förberedelser",
            "ios.rules.setup.b": "Med fyra spelare eller färre spelas det bara med korten från 6 upp till ess. Tvåor, treor, fyror och femmor tas ur leken. Esset är högst i det här spelet. Varje spelare får 6 kort, sedan dras ytterligare ett kort som läggs med bilden upp under draghögen. FÄRGEN på det uppvända kortet är trumffärgen. Den färgen är speciell, och varför förklaras under försvaret.",
            "ios.rules.setup.cap": "Ett kort ligger uppvänt under draghögen - dess färg är trumf. Hjärter, i alla exempel på den här sidan.",
            "ios.rules.start.h": "Spelets början",
            "ios.rules.start.b": "Den som har den lägsta trumfen börjar. Vid ett riktigt bord tar man reda på det genom att fråga om någon har en 6:a, sedan en 7:a, och så vidare. Här sköter spelet det själv. Den personen är rondens första anfallare.",
            "ios.rules.sword": "Svärdet markerar anfallaren som öppnar ronden.",
            "ios.rules.shield": "Skölden markerar försvararen.",
            "ios.rules.attack.h": "Att anfalla",
            "ios.rules.attack.b": "Rondens första anfallare, markerad med ett svärd, får välja vilket kort som helst ur sin hand - eller flera kort som alla har samma VALÖR - och lägga det framför spelaren till vänster (medsols). Den spelaren är nu försvarare, markerad med en sköld, och måste ta hand om anfallet. För att anfalla trycker du på korten för att välja dem och sedan på knappen Anfall, som dyker upp när urvalet är ett giltigt drag. Eller så drar du helt enkelt korten från handen ut på bordet.",
            "ios.rules.attack.ok1": "Den här spelaren får anfalla med sin dam.",
            "ios.rules.attack.ok2": "Hen får också anfalla med båda kungarna samtidigt, eftersom de har samma valör.",
            "ios.rules.attack.no1": "Hen får INTE anfalla med sin 7:a och sin 10:a ihop, eftersom de har olika valör.",
            "ios.rules.defend.h": "Att försvara sig",
            "ios.rules.defend.b": "Spelaren som just nu anfalls, markerad med skölden, är försvararen. Det finns bara en försvarare åt gången, och alla kort de andra lägger ut är försvararens ensak. Försvararen får bara täcka, ta korten eller skicka vidare (om det är tillåtet). Försvararen får INTE anfalla. Alla andra är anfallare och får bara anfalla. Anfallare får INTE täcka något kort på bordet.",
            "ios.rules.defend.b.nopass": "Spelaren som just nu anfalls, markerad med skölden, är försvararen. Det finns bara en försvarare åt gången, och alla kort de andra lägger ut är försvararens ensak. Försvararen får bara täcka eller ta korten. Försvararen får INTE anfalla. Alla andra är anfallare och får bara anfalla. Anfallare får INTE täcka något kort på bordet.",
            "ios.rules.cover.h": "Att täcka",
            "ios.rules.cover.b": "Försvararen kan täcka korten på bordet genom att lägga ett högre kort i samma färg, eller vilken trumf som helst, på varje kort. Det är detta som gör trumffärgen speciell. För att täcka väljer du ett kort och trycker på knappen Täck. Du kan också dra ett kort från handen till kortet du vill täcka. Ett vanligt misstag är att tro att ett redan täckt kort kan täckas igen av ett tredje kort. Så fungerar inte spelet: du kommer aldrig att se högar om tre på bordet. Tänk på anfallskortet som ett svärd och det täckande kortet som en sköld: anfallet är stoppat och därmed avslutat. Bara nya anfall går att göra, i egna högar.",
            "ios.rules.cover.ok1": "Ett högre kort i samma färg täcker.",
            "ios.rules.cover.ok2": "Vilken trumf som helst täcker vilken annan färg som helst - även med lägre valör.",
            "ios.rules.cover.no1": "Ett trumfanfall kräver en högre trumf - den här 7:an räcker inte.",
            "ios.rules.cover.no2": "Högre valör, fel färg - det täcker ingenting.",
            "ios.rules.throw.h": "Att lägga till",
            "ios.rules.throw.b": "Medan försvararen täcker får alla andra spelare \"lägga till\" fler anfallskort som försvararen också måste täcka. Regeln är enkel, även om den tar ett tag att få grepp om. Ser du VALÖREN (till exempel A, 6, 10) på ett kort du har på hand redan ligga på bordet, och är du anfallare, får du lägga till det kortet som ett eget nytt anfall. Färgerna behöver du INTE bry dig om alls. Den enda gränsen är hur många kort försvararen har på hand just då: det får aldrig ligga fler otäckta anfall på bordet än försvararen har kort. Tänk dig att försvararen måste kunna svara på varje anfallskort med precis ett försvarskort; med för många anfall är det omöjligt, och därför inte tillåtet. Du undrar kanske om antalet anfallskort kan växa snabbt på det viset. Precis så, och det är en del av spelets tjusning. För att anfalla trycker du på ett kort - eller flera där varje valör redan ligger på bordet - och sedan på Anfall. Eller så drar du korten från handen ut på bordet.",
            "ios.rules.throw.ok1": "Det ligger en 9:a på bordet, så din 9:a får läggas till - färgerna spelar ingen roll.",
            "ios.rules.throw.ok2": "Båda sexorna på en gång - två nya anfall.",
            "ios.rules.throw.ok3": "Eller 6:an och 9:an ihop - båda valörerna ligger redan ute.",
            "ios.rules.throw.no1": "Ingen 8:a och ingen knekt på bordet - det finns inget att lägga till.",
            "ios.rules.throw.no2": "Försvararen har ett kort och ett anfall väntar redan - det finns inte plats för ett till.",
            "ios.rules.pickup.h": "Att ta korten",
            "ios.rules.pickup.b": "Om försvararen inte kan täcka alla kort, eller inte vill, går det att trycka på knappen Ta. Då tar försvararen upp varje kort från bordet, även de som redan är täckta. Dessutom hoppas turen över, så spelaren till vänster inleder anfallet i nästa rond. Tänk alltså efter innan du tar.",
            "ios.rules.pickup.cap": "Tar du här hamnar alla tre korten på din hand - även det täckta paret.",
            "ios.rules.round.h": "Rondens slut",
            "ios.rules.round.b": "När alla kort är täckta och ingen anfallare vill lägga till fler kort går allt på bordet till kasthögen. Sedan drar spelarna kort, med början hos den första anfallaren och medsols genom alla anfallare, tills var och en har minst 6 kort. Försvararen drar sist. Spelet sköter det automatiskt. När draghögen är tom dras inga fler kort, och spelarna kan börja göra sig av med sina kort och slippa bli dumbommen. Ronden tar också slut om försvararen tar korten: då går korten på bordet till försvararens hand i stället för till kasthögen, och sedan dras det i samma ordning - försvararen sist, vilket för det mesta betyder inte alls, eftersom hen redan håller fler än sex.",
            "ios.rules.pass.h": "Att skicka vidare",
            "ios.rules.pass.b": "I ett spel där переводной, att \"skicka vidare\", är tillåtet har försvararen dessutom möjligheten att skicka anfallet vidare från sig själv till spelaren till vänster. För det får inget kort på bordet vara täckt, och försvararen måste ha ett kort med samma VALÖR som alla anfallskort på bordet. Då läggs det kortet ut, och skölden flyttar medsols till spelaren till vänster. Precis som det finns en gräns för hur många kort som får anfalla går det inte att skicka vidare om spelaren till vänster har färre kort än det skulle finnas anfall efter bytet. Ligger det till exempel två anfallskort på bordet och spelaren till vänster har två kort går det inte: efteråt skulle det ligga minst 3 kort där (2 plus kortet som skickas vidare). Det är mer än vad den spelaren har på hand, och därför är det inte tillåtet. För att skicka vidare trycker du på kortet med rätt valör och sedan på knappen Skicka. Eller så drar du det kortet till en tom plats på bordet.",
            "ios.rules.pass.ok1": "En 8:a anfaller och du har en 8:a - lägg ut den så går skölden vidare.",
            "ios.rules.pass.no1": "Något är redan täckt - för sent att skicka vidare.",
            "ios.rules.pass.no2": "Ingen 8:a på hand - den här får du försvara själv.",
            "ios.rules.pass.no3": "Att skicka vidare skulle ge tre anfall, och nästa spelare har bara två kort.",
            "ios.rules.end.h": "Spelets slut",
            "ios.rules.end.b": "När draghögen är tom fortsätter spelet. Den som gör sig av med alla sina kort kan inte bli dumbommen. Den siste spelaren som fortfarande har kort blir dumbommen.",
            "ios.rules.lobby.h": "Så fungerar lobbyn",
            "ios.rules.lobby.b": "Skriv in ditt namn för att gå med. Så snart minst två spelare är med kan vem som helst trycka på Starta spelet. När spelet väl har börjat kan ingen mer gå med.",
            "ios.rules.variant.h": "Vidareskickning",
            "ios.rules.variant.b": "I lobbyn väljs vilken Durak det här bordet spelar, och rutan visar vilken. Ikryssad är spelet med vidareskickning (perevodnoj): en försvarare som har ett kort med samma valör som anfallet får lägga ut det och skicka hela anfallet vidare till nästa spelare, som nu måste försvara sig. Tom är spelet med tillägg (podkidnoj): ingen vidareskickning, så försvararen täcker varje kort på bordet eller tar allt. Så länge lobbyn är öppen får vem som helst vid bordet ändra det; när spelet börjar ligger det fast.",
            "ios.rules.fool.h": "Dumbommen får betala",
            "ios.rules.fool.b": "Normalt avgör den lägsta trumfen vem som anfaller först. Det finns ett undantag, och det är den äldsta sortens Durak-rättvisa: trycker du på Nytt spel när ett spel är slut och exakt samma spelare sätter sig igen, avgör den lägsta trumfen ingenting. I stället öppnar spelaren till höger om den förra dumbommen, vilket betyder att dumbommen anfalls först. Förlorar du kommer nästa spel rakt emot dig. Går någon med eller lämnar innan starten har bordet ändrats och den vanliga regeln gäller igen.",
            "ios.lobby.passing": "Med vidareskickning",
            "ios.rules.lbl.table": "på bordet",
            "ios.rules.lbl.hand": "din hand",
