            "ios.rej.turn": "Det er ikke din tur.",
            "ios.rej.pickone": "Vælg et kort først.",
            "ios.rej.defending": "Du forsvarer dig - dæk angrebet, eller tag kortene.",
            "ios.rej.notyours": "Det kort har du ikke på hånden.",
            "ios.rej.addrank": "Du må kun lægge et kort til, hvis værdien allerede ligger på bordet.",
            "ios.rej.cover": "Det dækker ikke - spil højere i samme farve, eller en trumf.",
            "ios.rej.capacity": "For mange angreb til forsvarerens hånd.",
            "ios.rej.passrank": "Du kan kun skubbe videre med et kort af samme værdi.",
            "ios.rej.mustattack": "Den første angriber skal angribe.",
            "ios.rej.alreadygood": "Du har allerede sagt Færdig.",
            "ios.rej.notake": "Der er ikke noget at tage.",
            "ios.help": "Regler",
            "ios.settings.title": "Indstillinger",
            "ios.settings.table": "Bord",
            "ios.settings.table.wool": "Uld",
            "ios.settings.table.felt": "Grønt klæde",
            "ios.rules.title": "Sådan spiller du",
            "ios.rules.goal.h": "Målet",
            "ios.rules.goal.b": "Målet med spillet er at komme af med alle sine kort så hurtigt som muligt. Den, der sidder tilbage med kort til sidst, er дурак - fjolset, på russisk.",
            "ios.rules.setup.h": "Klargøring",
            "ios.rules.setup.b": "Med fire spillere eller færre spilles der kun med kortene fra 6 op til es. Toere, treere, firere og femmere tages ud af spillet. Esset er højest her. Hver spiller får 6 kort, og derefter trækkes endnu et kort, som lægges med billedsiden op under trækbunken. FARVEN på det vendte kort er trumffarven. Den farve er noget særligt, og hvorfor står under forsvaret.",
            "ios.rules.setup.cap": "Et kort ligger vendt under bunken - dets farve er trumf. Hjerter, i alle eksempler på denne side.",
            "ios.rules.start.h": "Spillets begyndelse",
            "ios.rules.start.b": "Den med den laveste trumf begynder. Ved et rigtigt bord finder man ud af det ved at spørge, om nogen har en 6'er, så en 7'er, og så videre. Her klarer spillet det selv. Den person er rundens første angriber.",
            "ios.rules.sword": "Sværdet markerer den angriber, der åbner runden.",
            "ios.rules.shield": "Skjoldet markerer forsvareren.",
            "ios.rules.attack.h": "At angribe",
            "ios.rules.attack.b": "Rundens første angriber, markeret med et sværd, må vælge et hvilket som helst kort fra hånden - eller flere kort, der alle har samme VÆRDI - og lægge det foran spilleren til venstre (med uret). Den spiller er nu forsvarer, markeret med et skjold, og skal tage sig af angrebet. Tryk på kortene for at vælge dem, og tryk så på knappen Angrib, som dukker op, når valget er et gyldigt træk. Eller træk simpelthen kortene fra hånden ud på bordet.",
            "ios.rules.attack.ok1": "Denne spiller må angribe med sin dame.",
            "ios.rules.attack.ok2": "Spilleren må også angribe med begge konger på én gang, for de har samme værdi.",
            "ios.rules.attack.no1": "Spilleren må IKKE angribe med sin 7'er og sin 10'er sammen, for de har forskellig værdi.",
            "ios.rules.defend.h": "At forsvare sig",
            "ios.rules.defend.b": "Den spiller, der bliver angrebet lige nu, markeret med skjoldet, er forsvareren. Der er kun én forsvarer ad gangen, og alle kort, de andre lægger ud, er forsvarerens sag. Forsvareren må kun dække, tage kortene eller skubbe videre (hvis det er tilladt). Forsvareren må IKKE angribe. Alle andre er angribere og må kun angribe. Angribere må IKKE dække noget kort på bordet.",
            "ios.rules.defend.b.nopass": "Den spiller, der bliver angrebet lige nu, markeret med skjoldet, er forsvareren. Der er kun én forsvarer ad gangen, og alle kort, de andre lægger ud, er forsvarerens sag. Forsvareren må kun dække eller tage kortene. Forsvareren må IKKE angribe. Alle andre er angribere og må kun angribe. Angribere må IKKE dække noget kort på bordet.",
            "ios.rules.cover.h": "At dække",
            "ios.rules.cover.b": "Forsvareren kan dække kortene på bordet ved at lægge et højere kort i samme farve, eller en hvilken som helst trumf, oven på hvert enkelt kort. Det er dét, der gør trumffarven særlig. Vælg et kort og tryk på knappen Dæk for at dække. Du kan også trække et kort fra hånden hen på det kort, du vil dække. En almindelig misforståelse er, at et kort, der allerede er dækket, kan dækkes igen af et tredje kort. Sådan fungerer spillet ikke: du får aldrig bunker på tre at se på bordet. Tænk på angrebskortet som et sværd og det dækkende kort som et skjold: angrebet er standset og dermed slut. Kun nye angreb er mulige, i deres egne bunker.",
            "ios.rules.cover.ok1": "Et højere kort i samme farve dækker.",
            "ios.rules.cover.ok2": "En hvilken som helst trumf dækker enhver anden farve - også med lavere værdi.",
            "ios.rules.cover.no1": "Et trumfangreb kræver en højere trumf - denne 7'er er for lav.",
            "ios.rules.cover.no2": "Højere værdi, forkert farve - det dækker ingenting.",
            "ios.rules.throw.h": "At lægge til",
            "ios.rules.throw.b": "Mens forsvareren dækker, må alle de andre spillere \"lægge\" flere angrebskort \"til\", som forsvareren også skal dække. Reglen er enkel, selv om den tager lidt tid at få fat i. Ser du VÆRDIEN (for eksempel A, 6, 10) af et kort, du har på hånden, allerede ligge på bordet, og er du angriber, må du lægge det kort til som et selvstændigt nyt angreb. Farverne skal du SLET IKKE tænke på. Den eneste grænse er, hvor mange kort forsvareren har på hånden lige nu: der må aldrig ligge flere udækkede angreb på bordet, end forsvareren har kort. Forestil dig, at forsvareren skal kunne svare på hvert angrebskort med præcis ét forsvarskort; ved for mange angreb er det umuligt, og derfor er det ikke tilladt. Du tænker måske, at antallet af angrebskort kan vokse hurtigt på den måde. Helt rigtigt, og det er en del af spillets charme. Tryk på et kort - eller flere, hvor hver værdi allerede ligger på bordet - og tryk så på Angrib. Eller træk kortene fra hånden ud på bordet.",
            "ios.rules.throw.ok1": "Der ligger en 9'er på bordet, så din 9'er må lægges til - farverne betyder intet.",
            "ios.rules.throw.ok2": "Begge seksere på én gang - to nye angreb.",
            "ios.rules.throw.ok3": "Eller 6'eren og 9'eren sammen - begge værdier ligger der allerede.",
            "ios.rules.throw.no1": "Ingen 8'er og ingen knægt på bordet - der er ikke noget at lægge til.",
            "ios.rules.throw.no2": "Forsvareren har ét kort, og et angreb venter allerede - der er ikke plads til et mere.",
            "ios.rules.pickup.h": "At tage kortene",
            "ios.rules.pickup.b": "Hvis forsvareren ikke kan dække alle kortene, eller ikke vil, kan spilleren trykke på knappen Tag. Så tages hvert eneste kort på bordet op, også de kort der allerede var dækket. Samtidig springes turen over, så spilleren til venstre begynder angrebet i næste runde. Tænk dig derfor godt om, før du tager.",
            "ios.rules.pickup.cap": "Tager du her, ryger alle tre kort op på hånden - også det dækkede par.",
            "ios.rules.round.h": "Rundens slutning",
            "ios.rules.round.b": "Når alle kort er dækket, og ingen angriber vil lægge mere til, ryger alt på bordet over i kassebunken. Derefter trækker spillerne kort, med start hos den første angriber og med uret gennem alle angribere, indtil hver har mindst 6 kort. Forsvareren trækker sidst. Spillet klarer det automatisk. Når trækbunken er tom, trækkes der ikke flere kort, og spillerne kan begynde at komme af med deres kort og slippe for at blive fjolset. Runden slutter også, hvis forsvareren tager kortene: så ryger kortene fra bordet op på forsvarerens hånd i stedet for i kassebunken, og bagefter trækkes der i samme rækkefølge - forsvareren sidst, hvilket som regel vil sige slet ikke, for så sidder vedkommende med mere end seks.",
            "ios.rules.pass.h": "At skubbe videre",
            "ios.rules.pass.b": "I et spil, hvor переводной, altså at \"skubbe videre\", er tilladt, har forsvareren desuden mulighed for at skubbe angrebet fra sig selv videre til spilleren til venstre. Til det må intet kort på bordet være dækket, og forsvareren skal have et kort med samme VÆRDI som alle angrebskortene på bordet. Så lægges det kort ud, og skjoldet flytter med uret over til spilleren til venstre. Ligesom der er en grænse for, hvor mange kort der må angribe, kan man ikke skubbe videre, hvis spilleren til venstre har færre kort, end der ville være angreb bagefter. Ligger der for eksempel to angrebskort på bordet, og har spilleren til venstre to kort, kan det ikke lade sig gøre: bagefter ville der ligge mindst 3 kort (2 plus kortet, der skubbes videre). Det er mere, end den spiller har på hånden, og derfor er det ikke tilladt. Tryk på kortet med den matchende værdi og derefter på knappen Skub for at skubbe videre. Eller træk det kort hen på en tom plads på bordet.",
            "ios.rules.pass.ok1": "En 8'er angriber, og du har en 8'er - læg den ud, så går skjoldet videre.",
            "ios.rules.pass.no1": "Noget er allerede dækket - for sent at skubbe videre.",
            "ios.rules.pass.no2": "Ingen 8'er på hånden - den her skal du selv forsvare.",
            "ios.rules.pass.no3": "Et skub ville give tre angreb, og den næste spiller har kun to kort.",
            "ios.rules.end.h": "Spillets slutning",
            "ios.rules.end.b": "Når trækbunken er tom, fortsætter spillet. Den, der kommer af med alle sine kort, kan ikke blive fjolset. Den sidste spiller med kort tilbage bliver fjolset.",
            "ios.rules.lobby.h": "Sådan virker lobbyen",
            "ios.rules.lobby.b": "Skriv dit navn for at deltage. Så snart mindst to spillere er med, kan hvem som helst trykke på Start spillet. Når spillet først er begyndt, kan ingen komme til.",
            "ios.rules.variant.h": "Skub",
            "ios.rules.variant.b": "I lobbyen vælges det, hvilken Durak dette bord spiller, og feltet viser hvilken. Sat flueben er spillet med skub (perevodnoj): en forsvarer med et kort af samme værdi som angrebet må lægge det ud og skubbe hele angrebet videre til den næste spiller, som nu skal forsvare sig. Tomt er spillet med tillæg (podkidnoj): der skubbes ikke, så forsvareren dækker hvert kort på bordet eller tager det hele. Så længe lobbyen er åben, må alle ved bordet ændre det; når spillet begynder, ligger det fast.",
            "ios.rules.fool.h": "Fjolset betaler for det",
            "ios.rules.fool.b": "Normalt afgør den laveste trumf, hvem der angriber først. Der er én undtagelse, og den er den ældste slags Durak-retfærdighed: trykker du på Nyt spil, når et spil er slut, og sætter præcis de samme spillere sig igen, afgør den laveste trumf ingenting. I stedet åbner spilleren til højre for det forrige fjols, hvilket betyder, at fjolset bliver angrebet først. Taber du, kommer det næste spil lige imod dig. Kommer der nogen til eller går nogen, før der startes, har bordet ændret sig, og den normale regel gælder igen.",
            "ios.lobby.passing": "Med skub",
            "ios.rules.lbl.table": "på bordet",
