            "ios.tut_done": "Begynd at spille",
            "ios.tut_1": "Velkommen til Durak. Det laveste trumfkort afgør, hvem der angriber først. Trumf slår alle andre farver.",
            "ios.tut_2": "Tryk på et kort på hånden for at angribe. Din modstander skal dække det - eller tage det hele.",
            "ios.tut_3": "Tryk på et af dine kort og derefter på det angreb, det dækker, for at forsvare dig. Et højere kort i samme farve, eller en hvilken som helst trumf, dækker det.",
