            "ios.help": "Regler",
            "ios.settings.title": "Innstillinger",
            "ios.settings.table": "Bord",
            "ios.settings.table.wool": "Ull",
            "ios.settings.table.felt": "Grønn filt",
            "ios.rules.title": "Slik spiller du",
            "ios.rules.goal.h": "Målet",
            "ios.rules.goal.b": "Målet med spillet er å bli kvitt alle kortene sine så fort som mulig. Den som sitter igjen med kort til slutt, er дурак - dumringen, på russisk.",
            "ios.rules.setup.h": "Oppsett",
            "ios.rules.setup.b": "Med fire spillere eller færre spilles det bare med kortene fra 6 opp til ess. Toere, treere, firere og femmere tas ut av spillet. Esset er høyest her. Hver spiller får 6 kort, og så trekkes ett kort til som legges med billedsiden opp under trekkbunken. FARGEN på dette kortet er trumffargen. Den fargen er noe for seg selv, og hvorfor står under forsvaret.",
            "ios.rules.setup.cap": "Ett kort ligger med billedsiden opp under bunken - fargen på det er trumf. Hjerter, i alle eksemplene på denne siden.",
            "ios.rules.start.h": "Spillets begynnelse",
            "ios.rules.start.b": "Den med den laveste trumfen begynner. Ved et ekte bord finner man ut av det ved å spørre om noen har en 6-er, så en 7-er, og så videre. Her gjør spillet det selv. Den personen er rundens første angriper.",
            "ios.rules.sword": "Sverdet markerer angriperen som åpner runden.",
            "ios.rules.shield": "Skjoldet markerer forsvareren.",
            "ios.rules.attack.h": "Å angripe",
            "ios.rules.attack.b": "Rundens første angriper, markert med et sverd, kan velge hvilket som helst kort fra hånden - eller flere kort som alle har samme VERDI - og legge det foran spilleren til venstre (med klokken). Den spilleren er nå forsvarer, markert med et skjold, og må ta seg av angrepet. Trykk på kortene for å velge dem, og trykk så på knappen Angrip, som dukker opp når utvalget er et gyldig trekk. Eller dra rett og slett kortene fra hånden ut på bordet.",
            "ios.rules.attack.ok1": "Denne spilleren kan angripe med dama si.",
            "ios.rules.attack.ok2": "Spilleren kan også angripe med begge kongene samtidig, siden de har samme verdi.",
            "ios.rules.attack.no1": "Spilleren kan IKKE angripe med 7-eren og 10-eren sammen, siden de har ulik verdi.",
            "ios.rules.defend.h": "Å forsvare seg",
            "ios.rules.defend.b": "Spilleren som blir angrepet akkurat nå, markert med skjoldet, er forsvareren. Det er bare én forsvarer om gangen, og alle kort de andre legger ut, er forsvarerens sak. Forsvareren kan bare dekke, ta kortene eller skyve videre (hvis det er lov). Forsvareren kan IKKE angripe. Alle andre er angripere og kan bare angripe. Angripere kan IKKE dekke noe kort på bordet.",
            "ios.rules.defend.b.nopass": "Spilleren som blir angrepet akkurat nå, markert med skjoldet, er forsvareren. Det er bare én forsvarer om gangen, og alle kort de andre legger ut, er forsvarerens sak. Forsvareren kan bare dekke eller ta kortene. Forsvareren kan IKKE angripe. Alle andre er angripere og kan bare angripe. Angripere kan IKKE dekke noe kort på bordet.",
            "ios.rules.cover.h": "Å dekke",
            "ios.rules.cover.b": "Forsvareren kan dekke kortene på bordet ved å legge et høyere kort i samme farge, eller en hvilken som helst trumf, oppå hvert enkelt kort. Det er dette som gjør trumffargen spesiell. Velg et kort og trykk på knappen Dekk for å dekke. Du kan også dra et kort fra hånden bort på kortet du vil dekke. En vanlig misforståelse er at et kort som alt er dekket, kan dekkes på nytt av et tredje kort. Slik fungerer ikke spillet: du får aldri se bunker på tre på bordet. Tenk på angrepskortet som et sverd og det dekkende kortet som et skjold: angrepet er stanset, og dermed ferdig. Bare nye angrep er mulige, i egne bunker.",
            "ios.rules.cover.ok1": "Et høyere kort i samme farge dekker.",
            "ios.rules.cover.ok2": "Enhver trumf dekker enhver annen farge - også med lavere verdi.",
            "ios.rules.cover.no1": "Et trumfangrep krever en høyere trumf - denne 7-eren er for lav.",
            "ios.rules.cover.no2": "Høyere verdi, feil farge - det dekker ingenting.",
            "ios.rules.throw.h": "Å legge til",
            "ios.rules.throw.b": "Mens forsvareren dekker, kan alle de andre spillerne \"legge til\" flere angrepskort som forsvareren også må dekke. Regelen er enkel, selv om den tar litt tid å få tak på. Ser du VERDIEN (for eksempel A, 6, 10) på et kort du har på hånden, allerede ligge på bordet, og er du angriper, kan du legge det kortet til som et eget nytt angrep. Fargene trenger du IKKE bry deg om i det hele tatt. Den eneste grensen er hvor mange kort forsvareren har på hånden akkurat da: det kan aldri ligge flere udekkede angrep på bordet enn forsvareren har kort. Tenk deg at forsvareren må kunne svare på hvert angrepskort med nøyaktig ett forsvarskort; med for mange angrep er det umulig, og derfor ikke lov. Du lurer kanskje på om antallet angrepskort kan vokse fort på den måten. Nettopp, og det er en del av moroa i spillet. Trykk på et kort - eller flere der hver verdi alt ligger på bordet - og trykk så på Angrip. Eller dra kortene fra hånden ut på bordet.",
            "ios.rules.throw.ok1": "Det ligger en 9-er på bordet, så 9-eren din kan legges til - fargene betyr ingenting.",
            "ios.rules.throw.ok2": "Begge seksere på én gang - to nye angrep.",
            "ios.rules.throw.ok3": "Eller 6-eren og 9-eren sammen - begge verdiene ligger der alt.",
            "ios.rules.throw.no1": "Ingen 8-er og ingen knekt på bordet - det er ingenting å legge til.",
            "ios.rules.throw.no2": "Forsvareren har ett kort, og ett angrep venter alt - det er ikke plass til ett til.",
            "ios.rules.pickup.h": "Å ta kortene",
            "ios.rules.pickup.b": "Hvis forsvareren ikke klarer å dekke alle kortene, eller ikke vil, kan spilleren trykke på knappen Ta. Da tas hvert eneste kort på bordet opp, også de som alt var dekket. Samtidig hoppes turen over, så spilleren til venstre åpner angrepet i neste runde. Tenk deg derfor godt om før du tar.",
            "ios.rules.pickup.cap": "Tar du her, går alle tre kortene på hånden din - også det dekkede paret.",
            "ios.rules.round.h": "Slutten på runden",
            "ios.rules.round.b": "Når alle kort er dekket og ingen angriper vil legge til mer, går alt på bordet over i kastebunken. Så trekker spillerne kort, med start hos den første angriperen og med klokken gjennom alle angriperne, til hver har minst 6 kort på hånden. Forsvareren trekker sist. Spillet gjør det automatisk. Når trekkbunken er tom, trekkes det ikke flere kort, og spillerne kan begynne å bli kvitt kortene sine og slippe å bli dumringen. Runden tar også slutt hvis forsvareren tar kortene: da går kortene fra bordet på hånden til forsvareren i stedet for i kastebunken, og etterpå trekkes det i samme rekkefølge - forsvareren sist, noe som stort sett vil si ikke i det hele tatt, siden vedkommende da har mer enn seks.",
            "ios.rules.pass.h": "Å skyve videre",
            "ios.rules.pass.b": "I et spill der переводной, altså å \"skyve videre\", er lov, har forsvareren i tillegg muligheten til å skyve angrepet fra seg selv videre til spilleren til venstre. Da kan ingen kort på bordet være dekket, og forsvareren må ha et kort med samme VERDI som alle angrepskortene på bordet. Så legges det kortet ut, og skjoldet flytter med klokken til spilleren til venstre. Akkurat som det er en grense for hvor mange kort som kan angripe, går det ikke an å skyve videre hvis spilleren til venstre har færre kort enn det ville vært angrep etterpå. Ligger det for eksempel to angrepskort på bordet og spilleren til venstre har to kort, går det ikke: etterpå ville det ligget minst 3 kort der (2 pluss kortet som skyves videre). Det er mer enn den spilleren har på hånden, og derfor er det ikke lov. Trykk på kortet med samme verdi og deretter på knappen Skyv for å skyve videre. Eller dra det kortet til en ledig plass på bordet.",
            "ios.rules.pass.ok1": "En 8-er angriper og du har en 8-er - legg den ut, så går skjoldet videre.",
            "ios.rules.pass.no1": "Noe er alt dekket - for sent å skyve videre.",
            "ios.rules.pass.no2": "Ingen 8-er på hånden - denne må du forsvare selv.",
            "ios.rules.pass.no3": "Å skyve videre ville gitt tre angrep, og neste spiller har bare to kort.",
            "ios.rules.end.h": "Slutten på spillet",
            "ios.rules.end.b": "Når trekkbunken er tom, fortsetter spillet. Den som blir kvitt alle kortene sine, kan ikke bli dumringen. Den siste spilleren som fortsatt har kort, blir dumringen.",
            "ios.rules.lobby.h": "Slik virker lobbyen",
            "ios.rules.lobby.b": "Skriv navnet ditt for å bli med. Så snart minst to spillere er med, kan hvem som helst trykke på Start spillet. Når spillet først har begynt, kommer ingen flere til.",
            "ios.rules.variant.h": "Skyving",
            "ios.rules.variant.b": "I lobbyen velges det hvilken Durak dette bordet spiller, og ruten viser hvilken. Krysset av er spillet med skyving (perevodnoj): en forsvarer med et kort av samme verdi som angrepet kan legge det ut og skyve hele angrepet videre til neste spiller, som nå må forsvare seg. Tom er spillet med tillegg (podkidnoj): det skyves ikke, så forsvareren dekker hvert kort på bordet eller tar alt. Så lenge lobbyen er åpen, kan hvem som helst ved bordet endre det; når spillet begynner, ligger det fast.",
            "ios.rules.fool.h": "Dumringen betaler for det",
            "ios.rules.fool.b": "Vanligvis avgjør den laveste trumfen hvem som angriper først. Det finnes ett unntak, og det er den eldste sorten Durak-rettferdighet: trykker du på Nytt spill når et spill er slutt, og nøyaktig de samme spillerne setter seg igjen, avgjør den laveste trumfen ingenting. I stedet åpner spilleren til høyre for forrige dumring, noe som betyr at dumringen blir angrepet først. Taper du, kommer neste spill rett imot deg. Blir noen med eller går noen før starten, har bordet endret seg, og den vanlige regelen gjelder igjen.",
            "ios.lobby.passing": "Med skyving",
            "ios.rules.lbl.table": "på bordet",
            "ios.rules.lbl.hand": "hånden din",
            "ios.rules.defender": "Forsvarer",
