            "ios.tut_next": "Skjønner",
            "ios.tut_done": "Begynn å spille",
            "ios.tut_1": "Velkommen til Durak. Det laveste trumfkortet avgjør hvem som angriper først. Trumf slår alle andre farger.",
            "ios.tut_2": "Trykk på et kort på hånden for å angripe. Motstanderen din må dekke det - eller ta alt.",
            "ios.tut_3": "Trykk på et av kortene dine og deretter på angrepet det dekker, for å forsvare deg. Et høyere kort i samme farge, eller en hvilken som helst trumf, dekker det.",
            "ios.tut_4": "Kan eller vil du ikke forsvare deg? Trykk på Ta for å ta kortene. Ferdig med å angripe? Trykk på Ferdig.",
