            "ios.rej.mustattack": "Ensimmäisen hyökkääjän on hyökättävä.",
            "ios.rej.alreadygood": "Sanoit jo Valmis.",
            "ios.rej.notake": "Ei ole mitään otettavaa.",
            "ios.help": "Säännöt",
            "ios.settings.title": "Asetukset",
            "ios.settings.table": "Pöytä",
            "ios.settings.table.wool": "Villa",
            "ios.settings.table.felt": "Vihreä verka",
            "ios.rules.title": "Näin pelaat",
            "ios.rules.goal.h": "Tavoite",
            "ios.rules.goal.b": "Pelin tavoite on päästä eroon kaikista korteistaan mahdollisimman nopeasti. Se, jolle jää lopussa kortteja, on дурак - venäjäksi pölkkypää.",
            "ios.rules.setup.h": "Valmistelut",
            "ios.rules.setup.b": "Neljällä pelaajalla tai vähemmällä pelataan vain korteilla kuutosesta ässään. Kakkoset, kolmoset, neloset ja vitoset otetaan pois pakasta. Ässä on tässä pelissä korkein. Jokaiselle jaetaan 6 korttia, minkä jälkeen nostetaan vielä yksi kortti, käännetään kuvapuoli ylöspäin ja työnnetään nostopakan alle. Tämän käännetyn kortin MAA on valttimaa. Valttimaa on erityinen, ja miksi, se selviää torjumisen kohdalla.",
            "ios.rules.setup.cap": "Yksi kortti on käännettynä pakan alla - sen maa on valtti. Näillä sivuilla se on joka esimerkissä hertta.",
            "ios.rules.start.h": "Pelin alku",
            "ios.rules.start.b": "Aloittaa se, jolla on pienin valtti. Oikean pöydän ääressä se selvitetään kysymällä, onko jollakin kuutosta, sitten seiskaa, ja niin edelleen. Täällä peli hoitaa sen itse. Tämä pelaaja on kierroksen ensimmäinen hyökkääjä.",
            "ios.rules.sword": "Miekka merkitsee hyökkääjän, joka avaa kierroksen.",
            "ios.rules.shield": "Kilpi merkitsee torjujan.",
            "ios.rules.attack.h": "Hyökkääminen",
            "ios.rules.attack.b": "Kierroksen ensimmäinen hyökkääjä, jolla on miekan merkki, saa valita kädestään minkä tahansa kortin - tai useita samanARVOISIA kortteja - ja asettaa ne vasemmalla puolellaan istuvan pelaajan eteen (myötäpäivään). Tästä pelaajasta tulee torjuja, jolla on kilven merkki, ja hänen on hoidettava hyökkäys. Hyökkää napauttamalla kortit valituiksi ja painamalla Hyökkää-painiketta, joka ilmestyy, kun valinta on kelvollinen siirto. Voit myös yksinkertaisesti vetää kortit kädestäsi pöydälle.",
            "ios.rules.attack.ok1": "Tämä pelaaja saa hyökätä rouvallaan.",
            "ios.rules.attack.ok2": "Hän saa hyökätä myös molemmilla kuninkailla yhtä aikaa, koska niiden arvo on sama.",
            "ios.rules.attack.no1": "Hän EI saa hyökätä seiskalla ja kympillä yhdessä, koska niiden arvot ovat eri.",
            "ios.rules.defend.h": "Torjuminen",
            "ios.rules.defend.b": "Pelaaja, jota juuri nyt vastaan hyökätään ja jolla on kilven merkki, on torjuja. Torjujia on kerrallaan vain yksi, ja kaikki muiden pöytään laskemat kortit ovat hänen huolenaan. Torjuja saa vain torjua, ottaa kortit tai siirtää hyökkäyksen eteenpäin (jos se on sallittu). Torjuja EI SAA hyökätä. Kaikki muut ovat hyökkääjiä ja saavat vain hyökätä. Hyökkääjät EIVÄT SAA torjua yhtäkään pöydällä olevaa korttia.",
            "ios.rules.defend.b.nopass": "Pelaaja, jota juuri nyt vastaan hyökätään ja jolla on kilven merkki, on torjuja. Torjujia on kerrallaan vain yksi, ja kaikki muiden pöytään laskemat kortit ovat hänen huolenaan. Torjuja saa vain torjua tai ottaa kortit. Torjuja EI SAA hyökätä. Kaikki muut ovat hyökkääjiä ja saavat vain hyökätä. Hyökkääjät EIVÄT SAA torjua yhtäkään pöydällä olevaa korttia.",
            "ios.rules.cover.h": "Torjunta",
            "ios.rules.cover.b": "Torjuja voi torjua pöydällä olevat kortit asettamalla jokaisen päälle samaa maata olevan korkeamman kortin tai minkä tahansa valtin. Juuri tämä tekee valttimaasta erityisen. Torju valitsemalla kortti ja napauttamalla Torju-painiketta. Voit myös vetää kortin kädestäsi sen kortin päälle, jonka haluat torjua. Yleinen väärinkäsitys on, että jo torjutun kortin päälle voisi laittaa vielä kolmannen kortin. Peli ei toimi niin: pöydällä ei koskaan näy kolmen kortin pinoja. Ajattele hyökkäyskorttia miekkana ja torjuvaa korttia kilpenä: hyökkäys on pysäytetty ja siten ohi. Vain uusia hyökkäyksiä voi tehdä, omina pinoinaan.",
            "ios.rules.cover.ok1": "Samaa maata oleva korkeampi kortti torjuu.",
            "ios.rules.cover.ok2": "Mikä tahansa valtti torjuu minkä tahansa muun maan kortin - vaikka arvo olisi pienempi.",
            "ios.rules.cover.no1": "Valttihyökkäys vaatii korkeamman valtin - tämä seiska ei riitä.",
            "ios.rules.cover.no2": "Arvo on korkeampi mutta maa väärä - tuo ei torju mitään.",
            "ios.rules.throw.h": "Lisääminen",
            "ios.rules.throw.b": "Torjujan torjuessa kaikki muut pelaajat saavat \"lisätä\" pöytään hyökkäyskortteja, jotka torjujan on myös torjuttava. Sääntö on yksinkertainen, vaikka sen sisäistäminen vie hetken. Jos näet pöydällä sellaisen kortin ARVON (esimerkiksi A, 6, 10), joka sinulla on kädessä, ja olet hyökkääjä, saat lisätä sen kortin pöytään omana uutena hyökkäyksenä. Maista ei tarvitse välittää LAINKAAN. Ainoa raja on se, montako korttia torjujalla on juuri sillä hetkellä kädessä: pöydällä ei saa koskaan olla enempää torjumattomia hyökkäyksiä kuin torjujalla on kortteja. Kuvittele, että torjujan on pystyttävä vastaamaan jokaiseen hyökkäyskorttiin yhdellä torjuvalla kortilla; jos hyökkäyksiä on liikaa, se on mahdotonta, eikä siksi sallittua. Ehkä mietit, voiko hyökkäyskorttien määrä näin kasvaa nopeasti. Aivan, ja juuri siinä on osa pelin viehätystä. Hyökkää napauttamalla korttia - tai useampaa, joiden jokaisen arvo on jo pöydällä - ja painamalla Hyökkää. Voit myös vetää kortit kädestäsi pöydälle.",
            "ios.rules.throw.ok1": "Pöydällä on ysi, joten sinunkin ysisi käy - maalla ei ole väliä.",
            "ios.rules.throw.ok2": "Molemmat kuutoset kerralla - kaksi uutta hyökkäystä.",
            "ios.rules.throw.ok3": "Tai kuutonen ja ysi yhdessä - molemmat arvot ovat jo pöydällä.",
            "ios.rules.throw.no1": "Pöydällä ei ole kasia eikä sotilasta - lisättävää ei ole.",
            "ios.rules.throw.no2": "Torjujalla on yksi kortti ja yksi hyökkäys odottaa jo - toiselle ei ole tilaa.",
            "ios.rules.pickup.h": "Korttien ottaminen",
            "ios.rules.pickup.b": "Jos torjuja ei pysty torjumaan kaikkia kortteja tai ei halua, hän voi painaa Ota-painiketta. Silloin hän ottaa pöydältä jokaisen kortin, myös jo torjutut. Lisäksi hänen vuoronsa ohitetaan, joten seuraavalla kierroksella hyökkäyksen aloittaa hänen vasemmalla puolellaan istuva pelaaja. Mieti siis tarkkaan, ennen kuin otat.",
            "ios.rules.pickup.cap": "Jos otat tässä, kaikki kolme korttia siirtyvät käteesi - myös torjuttu pari.",
            "ios.rules.round.h": "Kierroksen loppu",
            "ios.rules.round.b": "Kun kaikki kortit on torjuttu eikä yksikään hyökkääjä halua enää lisätä, kaikki pöydällä oleva siirtyy poistopakkaan. Sitten nostetaan kortteja: ensin ensimmäinen hyökkääjä ja siitä myötäpäivään kaikki hyökkääjät, kunnes jokaisella on vähintään 6 korttia. Torjuja nostaa viimeisenä. Peli hoitaa tämän itse. Kun pakka on tyhjä, kortteja ei enää nosteta, ja pelaajat alkavat päästä korteistaan eroon ja välttyä pölkkypään roolilta. Kierros päättyy myös silloin, kun torjuja ottaa kortit: silloin pöydän kortit menevät poistopakan sijaan torjujan käteen, ja sen jälkeen nostetaan samassa järjestyksessä - torjuja viimeisenä, mikä yleensä tarkoittaa, ettei hän nosta lainkaan, koska kortteja on jo yli kuusi.",
            "ios.rules.pass.h": "Siirtäminen",
            "ios.rules.pass.b": "Pelissä, jossa переводной eli \"siirtäminen\" on sallittu, torjujalla on lisäksi mahdollisuus siirtää hyökkäys itseltään vasemmalla puolellaan istuvalle pelaajalle. Tämä onnistuu vain, jos yhtäkään pöydän korttia ei ole vielä torjuttu ja torjujalla on kortti, jonka ARVO on sama kuin kaikkien pöydällä olevien hyökkäyskorttien. Hän laskee sen kortin pöytään, ja kilpi siirtyy myötäpäivään vasemmalla istuvalle pelaajalle. Aivan kuten hyökkäyskorttien määrällä on rajansa, siirtäminen ei onnistu, jos vasemmalla istuvalla on vähemmän kortteja kuin hyökkäyksiä olisi siirron jälkeen. Jos esimerkiksi pöydällä on kaksi hyökkäyskorttia ja vasemmalla istuvalla on kaksi korttia, siirtäminen ei käy: sen jälkeen pöydässä olisi vähintään 3 korttia (2 plus siirretty kortti). Se on enemmän kuin hänen kädessään, eikä siksi ole sallittua. Siirrä napauttamalla samanarvoista korttia ja painamalla Siirrä-painiketta. Voit myös vetää sen kortin tyhjään kohtaan pöydällä.",
            "ios.rules.pass.ok1": "Hyökkäyksenä on kasi ja sinulla on kasi - laske se pöytään, niin kilpi siirtyy eteenpäin.",
            "ios.rules.pass.no1": "Jokin on jo torjuttu - siirtämiseen on myöhäistä.",
            "ios.rules.pass.no2": "Kädessäsi ei ole kasia - tämä on sinun torjuttavasi.",
            "ios.rules.pass.no3": "Siirto tekisi kolme hyökkäystä, ja seuraavalla pelaajalla on vain kaksi korttia.",
            "ios.rules.end.h": "Pelin loppu",
            "ios.rules.end.b": "Kun nostopakka on tyhjä, peli jatkuu. Se, joka pääsee eroon kaikista korteistaan, ei voi enää jäädä pölkkypääksi. Pölkkypääksi jää viimeinen pelaaja, jolla on vielä kortteja.",
            "ios.rules.lobby.h": "Näin aula toimii",
            "ios.rules.lobby.b": "Kirjoita nimesi, niin pääset mukaan. Kun mukana on vähintään kaksi pelaajaa, kuka tahansa voi painaa Aloita peli. Kun peli on kerran alkanut, mukaan ei enää pääse.",
            "ios.rules.variant.h": "Siirtäminen",
            "ios.rules.variant.b": "Aulassa valitaan, mitä Durakia tässä pöydässä pelataan, ja ruutu kertoo kumpaa. Rastittuna on siirtopeli (perevodnoj): torjuja, jolla on hyökkäyksen kanssa samanarvoinen kortti, saa laskea sen pöytään ja siirtää koko hyökkäyksen seuraavalle pelaajalle, jonka on nyt torjuttava se. Tyhjänä on lisäyspeli (podkidnoj): siirtoa ei ole, joten torjuja joko torjuu jokaisen pöydän kortin tai ottaa kaikki. Niin kauan kuin aula on auki, kuka tahansa pöydässä voi vaihtaa asetusta; pelin alkaessa se lukittuu.",
            "ios.rules.fool.h": "Pölkkypää maksaa sen",
            "ios.rules.fool.b": "Yleensä pienin valtti ratkaisee, kuka hyökkää ensin. Yksi poikkeus on, ja se on vanhinta Durak-oikeutta: jos painat pelin päätyttyä Uusi peli ja pöytään istuu täsmälleen sama porukka, pienin valtti ei ratkaise mitään. Sen sijaan aloittaa edellisen pölkkypään oikealla puolella istuva pelaaja, mikä tarkoittaa, että pölkkypäätä vastaan hyökätään ensimmäisenä. Jos häviät, seuraava peli tulee suoraan sinua kohti. Jos joku liittyy tai lähtee ennen aloitusta, pöytä on muuttunut ja tavallinen sääntö palaa voimaan.",
            "ios.lobby.passing": "Siirto sallittu",
            "ios.rules.lbl.table": "pöydällä",
            "ios.rules.lbl.hand": "kätesi",
            "ios.rules.defender": "Torjuja",
