            "ios.tut_next": "Selvä",
            "ios.tut_done": "Aloita pelaaminen",
            "ios.tut_1": "Tervetuloa Durakiin. Pienin valttikortti ratkaisee, kuka hyökkää ensin. Valtti voittaa kaikki muut maat.",
            "ios.tut_2": "Hyökkää napauttamalla korttia kädessäsi. Vastustajan on torjuttava se - tai otettava kaikki.",
            "ios.tut_3": "Torju napauttamalla omaa korttiasi ja sitten sitä hyökkäystä, jonka se torjuu. Torjuntaan käy samaa maata oleva korkeampi kortti tai mikä tahansa valtti.",
            "ios.tut_4": "Etkö voi tai halua torjua? Napauta Ota, niin saat kortit. Hyökkäys valmis? Napauta Valmis.",
            "ios.tut_5": "Tyhjennä kätesi ennen muita. Viimeinen pelaaja, jolla on kortteja, on pölkkypää. Onnea matkaan!",
