            "ios.rej.turn": "Nejsi na tahu.",
            "ios.rej.pickone": "Nejdřív vyber kartu.",
            "ios.rej.defending": "Bráníš se - kryj útok, nebo si karty vezmi.",
            "ios.rej.notyours": "Tuhle kartu v ruce nemáš.",
            "ios.rej.addrank": "Přidat můžeš jen kartu té hodnoty, která už na stole leží.",
            "ios.rej.cover": "Tímhle to nepřebiješ - zahraj vyšší kartu téže barvy, nebo trumf.",
            "ios.rej.capacity": "Na ruku obránce je útoků moc.",
            "ios.rej.passrank": "Posunout jde jen kartou stejné hodnoty.",
            "ios.rej.mustattack": "První útočník musí zaútočit.",
            "ios.rej.alreadygood": "Hotovo už máš řečené.",
            "ios.rej.notake": "Není co brát.",
            "ios.help": "Pravidla",
            "ios.settings.title": "Nastavení",
            "ios.settings.table": "Stůl",
            "ios.settings.table.wool": "Vlna",
            "ios.settings.table.felt": "Zelené sukno",
            "ios.rules.title": "Jak se hraje",
            "ios.rules.goal.h": "Cíl hry",
            "ios.rules.goal.b": "Cílem hry je zbavit se všech svých karet co nejrychleji. Kdo na konci zůstane s kartami, ten je дурак - rusky hlupák.",
            "ios.rules.setup.h": "Příprava",
            "ios.rules.setup.b": "Při čtyřech a méně hráčích se hraje jen s kartami od šestky po eso. Dvojky, trojky, čtyřky a pětky jdou z balíčku pryč. Eso je tu nejvyšší. Každý hráč dostane 6 karet, pak se lízne ještě jedna karta, otočí se lícem nahoru a zasune se pod dobírací balíček. BARVA téhle otočené karty určuje trumfovou barvu. Proč je ta barva výjimečná, se dozvíš u krytí.",
            "ios.rules.setup.cap": "Pod balíčkem leží jedna otočená karta - její barva je trumf. Na téhle stránce jsou to ve všech příkladech srdce.",
            "ios.rules.start.h": "Začátek hry",
            "ios.rules.start.b": "Začíná ten, kdo má nejnižší trumf. U opravdového stolu se to zjistí tak, že se zeptáš, jestli má někdo šestku, potom sedmičku a tak dál. Tady to hra udělá sama. Tenhle hráč je první útočník kola.",
            "ios.rules.sword": "Meč označuje útočníka, který kolo otevírá.",
            "ios.rules.shield": "Štít označuje obránce.",
            "ios.rules.attack.h": "Útok",
            "ios.rules.attack.b": "První útočník kola, označený mečem, si může z ruky vybrat kteroukoli kartu - nebo libovolnou skupinu karet stejné HODNOTY - a položit ji před hráče po své levici (po směru hodinových ručiček). Ten hráč je teď obránce, označený štítem, a musí se s útokem vypořádat. Zaútočíš tak, že karty klepnutím vybereš a stiskneš tlačítko Útoč, které se objeví, jakmile je výběr platným tahem. Nebo prostě karty přetáhneš z ruky na stůl.",
            "ios.rules.attack.ok1": "Tenhle hráč může zaútočit svou dámou.",
            "ios.rules.attack.ok2": "Může zaútočit i oběma králi naráz, protože mají stejnou hodnotu.",
            "ios.rules.attack.no1": "NEMŮŽE zaútočit sedmičkou a desítkou dohromady, protože mají různou hodnotu.",
            "ios.rules.defend.h": "Obrana",
            "ios.rules.defend.b": "Hráč, na kterého se právě útočí a který je označený štítem, je obránce. V jednu chvíli je vždycky jen jeden a všechny karty, které ostatní vyloží, jsou jeho starost. Obránce může jen krýt, vzít si karty, nebo útok posunout dál (pokud je to dovolené). Obránce NESMÍ útočit. Všichni ostatní jsou útočníci a mohou jen útočit. Útočníci NESMĚJÍ krýt žádnou kartu na stole.",
            "ios.rules.defend.b.nopass": "Hráč, na kterého se právě útočí a který je označený štítem, je obránce. V jednu chvíli je vždycky jen jeden a všechny karty, které ostatní vyloží, jsou jeho starost. Obránce může jen krýt nebo si vzít karty. Obránce NESMÍ útočit. Všichni ostatní jsou útočníci a mohou jen útočit. Útočníci NESMĚJÍ krýt žádnou kartu na stole.",
            "ios.rules.cover.h": "Krytí",
            "ios.rules.cover.b": "Obránce kryje karty na stole tak, že na každou z nich položí vyšší kartu téže barvy nebo libovolný trumf. Právě tím je trumfová barva výjimečná. Kryješ tak, že vybereš kartu a klepneš na tlačítko Kryj. Nebo přetáhneš kartu z ruky na tu, kterou chceš krýt. Častý omyl je, že už krytou kartu jde krýt ještě třetí kartou. Tak hra nefunguje: na stole nikdy neuvidíš hromádky po třech. Představ si útočnou kartu jako meč a krycí kartu jako štít: útok je zastavený, a tím pádem skončil. Dělat se dají jen nové útoky, na samostatných hromádkách.",
            "ios.rules.cover.ok1": "Kryje vyšší karta téže barvy.",
            "ios.rules.cover.ok2": "Libovolný trumf kryje kteroukoli jinou barvu - i s nižší hodnotou.",
            "ios.rules.cover.no1": "Trumfový útok chce vyšší trumf - tahle sedmička je málo.",
            "ios.rules.cover.no2": "Vyšší hodnota, špatná barva - tímhle nekryješ nic.",
            "ios.rules.throw.h": "Přihazování",
            "ios.rules.throw.b": "Zatímco obránce kryje, každý další hráč může \"přihodit\" další útočné karty, které bude muset obránce krýt taky. Pravidlo je jednoduché, i když chvíli trvá, než ho člověk pobere. Když na stole uvidíš HODNOTU (třeba A, 6, 10) karty, kterou máš v ruce, a jsi útočník, můžeš tu kartu přidat jako samostatný nový útok. Barvami se NEMUSÍŠ zabývat vůbec. Jediné omezení je počet karet, které má obránce zrovna v ruce: nekrytých útoků na stole nesmí být víc, než kolik má obránce karet. Představ si, že obránce musí umět na každou útočnou kartu odpovědět právě jednou krycí; při příliš mnoha útocích to fyzicky nejde, a proto se to nesmí. Možná tě napadne, jestli takhle počet útočných karet nezačne rychle růst. Přesně tak, a v tom je kus kouzla téhle hry. Zaútočíš tak, že klepneš na kartu - nebo na skupinu, kde každá hodnota už na stole je - a stiskneš Útoč. Nebo karty přetáhneš z ruky na stůl.",
            "ios.rules.throw.ok1": "Na stole leží devítka, takže tvoje devítka může jít taky - na barvách nezáleží.",
            "ios.rules.throw.ok2": "Obě šestky naráz - dva nové útoky.",
            "ios.rules.throw.ok3": "Nebo šestka a devítka dohromady - obě hodnoty už na stole jsou.",
            "ios.rules.throw.no1": "Na stole není osmička ani kluk - není co přihodit.",
            "ios.rules.throw.no2": "Obránce má jednu kartu a jeden útok už čeká - na další není místo.",
            "ios.rules.pickup.h": "Braní karet",
            "ios.rules.pickup.b": "Když obránce nemůže pokrýt všechny karty nebo krýt nechce, může stisknout tlačítko Ber. Tím si vezme ze stolu každou kartu, i tu, která už byla krytá. Navíc se jeho tah přeskočí, takže v dalším kole začíná útočit hráč po jeho levici. Rozmysli si tedy dobře, jestli si karty vzít.",
            "ios.rules.pickup.cap": "Když si vezmeš tady, půjdou ti do ruky všechny tři karty - i krytá dvojice.",
            "ios.rules.round.h": "Konec kola",
            "ios.rules.round.b": "Když jsou všechny karty kryté a žádný útočník už nechce přihazovat, jde všechno ze stolu do odhazovacího balíčku. Pak se dobírá: nejdřív první útočník a po směru hodinových ručiček všichni útočníci, dokud nemá každý aspoň 6 karet. Obránce dobírá poslední. Hra to udělá sama. Jakmile je balíček prázdný, už se nedobírá a hráči se můžou začít zbavovat karet a uniknout roli hlupáka. Kolo skončí i tehdy, když si obránce karty vezme: karty ze stolu pak jdou do jeho ruky místo do odhazovacího balíčku a dobírá se dál ve stejném pořadí - obránce poslední, což většinou znamená vůbec, protože jich drží víc než šest.",
            "ios.rules.pass.h": "Posouvání",
            "ios.rules.pass.b": "Ve hře, kde je dovolený переводной, tedy \"posouvání\", má obránce navíc možnost posunout útok od sebe dál na hráče po své levici. K tomu nesmí být na stole žádná karta krytá a on sám musí mít kartu stejné HODNOTY, jakou mají všechny útočné karty na stole. Tu pak položí a ikona obránce se posune po směru hodinových ručiček na hráče po jeho levici. Stejně jako je omezený počet útočných karet, posunout nejde, pokud má hráč po levici míň karet, než kolik by po posunu bylo útoků. Když třeba na stole leží dvě útočné karty a hráč po levici drží dvě karty, posunout nejde: ležely by tam pak nejmíň 3 karty (2 plus posunutá). To je víc, než kolik má v ruce, a proto se to nesmí. Posunout můžeš tak, že klepneš na kartu odpovídající hodnoty a stiskneš tlačítko Posuň. Nebo tu kartu přetáhneš na volné místo na stole.",
            "ios.rules.pass.ok1": "Útočí osmička a ty osmičku máš - polož ji a štít jde dál.",
            "ios.rules.pass.no1": "Něco už je kryté - na posunutí je pozdě.",
            "ios.rules.pass.no2": "Osmičku v ruce nemáš - tuhle si musíš ubránit.",
            "ios.rules.pass.no3": "Po posunutí by byly tři útoky a další hráč drží jen dvě karty.",
            "ios.rules.end.h": "Konec hry",
            "ios.rules.end.b": "Jakmile je dobírací balíček prázdný, hraje se dál. Kdo se zbaví všech svých karet, ten už hlupákem být nemůže. Hlupákem se stane poslední hráč, kterému karty zbyly.",
            "ios.rules.lobby.h": "Jak funguje čekárna",
            "ios.rules.lobby.b": "Napiš svoje jméno a přidej se. Jakmile jsou uvnitř aspoň dva hráči, může kdokoli stisknout Začít hrát. Po začátku hry se už nikdo nepřidá.",
            "ios.rules.variant.h": "Posouvání",
            "ios.rules.variant.b": "V čekárně se vybírá, jaký Durak se u tohohle stolu hraje, a políčko říká, který to je. Zaškrtnuto je hra s posouváním (perevodnoj): obránce, který má kartu stejné hodnoty jako útok, ji může položit a posunout celý útok na dalšího hráče, a ten se teď musí bránit. Prázdné je hra s přihazováním (podkidnoj): posouvat nejde, takže obránce buď pokryje každou kartu na stole, nebo si vezme všechno. Dokud je čekárna otevřená, může to kdokoli u stolu změnit; jakmile hra začne, je to dané.",
            "ios.rules.fool.h": "Hlupák to zaplatí",
            "ios.rules.fool.b": "Obvykle rozhoduje o tom, kdo útočí první, nejnižší trumf. Jedna výjimka ale je, a je to nejstarší druh durakovské spravedlnosti: když po konci hry stiskneš Nová hra a ke stolu si sednou přesně titíž hráči, nejnižší trumf nerozhoduje o ničem. Otevírá místo toho hráč po pravici posledního hlupáka, což znamená, že hlupák je první, na koho se útočí. Prohraješ - a další hra jde rovnou po tobě. Když se před startem někdo přidá nebo odejde, stůl se změnil a platí zase běžné pravidlo.",
            "ios.lobby.passing": "S posouváním",
            "ios.rules.lbl.table": "na stole",
            "ios.rules.lbl.hand": "tvoje ruka",
            "ios.rules.defender": "Obránce",
