            "ios.rej.notyours": "Cartea aceea nu este în mâna ta.",
            "ios.rej.addrank": "Poți adăuga doar o carte a cărei valoare se află deja pe masă.",
            "ios.rej.cover": "Așa nu acoperi - joacă mai mare pe aceeași culoare sau un atu.",
            "ios.rej.capacity": "Prea multe atacuri pentru cărțile din mâna apărătorului.",
            "ios.rej.passrank": "Poți pasa doar cu o carte de aceeași valoare.",
            "ios.rej.mustattack": "Primul atacant trebuie să atace.",
            "ios.rej.alreadygood": "Ai spus deja Gata.",
            "ios.rej.notake": "Nu este nimic de luat.",
            "ios.help": "Reguli",
            "ios.settings.title": "Setări",
            "ios.settings.table": "Masă",
            "ios.settings.table.wool": "Lână",
            "ios.settings.table.felt": "Postav verde",
            "ios.rules.title": "Cum se joacă",
            "ios.rules.goal.h": "Scopul",
            "ios.rules.goal.b": "Scopul jocului este să scapi de toate cărțile tale cât mai repede. Cine rămâne cu cărți la final este дурак - prostul, în rusă.",
            "ios.rules.setup.h": "Pregătirea",
            "ios.rules.setup.b": "La patru jucători sau mai puțini se joacă doar cu cărțile de la 6 până la as. Cărțile de la 2 la 5 sunt scoase din pachet. Asul este cea mai mare carte aici. Fiecare jucător primește 6 cărți, apoi se mai trage o carte, se întoarce cu fața în sus și se pune sub pachetul de tras. CULOAREA acestei cărți întoarse dă culoarea de atu. Culoarea aceasta este specială, iar de ce, se explică la apărare.",
            "ios.rules.setup.cap": "O carte stă întoarsă sub pachet - culoarea ei este atu. Cupă, în toate exemplele de pe pagina aceasta.",
            "ios.rules.start.h": "Începutul jocului",
            "ios.rules.start.b": "Începe cel care are cel mai mic atu. La o masă adevărată afli asta întrebând dacă are cineva un 6, apoi un 7 și tot așa. Aici jocul o face singur. Persoana aceasta este primul atacant al rundei.",
            "ios.rules.sword": "Spada îl marchează pe atacantul care deschide runda.",
            "ios.rules.shield": "Scutul îl marchează pe apărător.",
            "ios.rules.attack.h": "Atacul",
            "ios.rules.attack.b": "Primul atacant al rundei, marcat cu o spadă, poate alege din mână orice carte - sau orice grup de cărți care au toate aceeași VALOARE - și o pune în fața jucătorului din stânga lui (în sensul acelor de ceas). Jucătorul acela este acum apărător, marcat cu un scut, și trebuie să se descurce cu atacul. Ca să ataci, atinge cărțile ca să le selectezi și apasă butonul Atacă, care apare atunci când selecția este o mutare validă. Sau pur și simplu trage cărțile din mână pe masă.",
            "ios.rules.attack.ok1": "Jucătorul acesta poate ataca cu dama lui.",
            "ios.rules.attack.ok2": "Poate ataca și cu ambii regi deodată, pentru că au aceeași valoare.",
            "ios.rules.attack.no1": "NU poate ataca cu 7 și cu 10 împreună, pentru că au valori diferite.",
            "ios.rules.defend.h": "Apărarea",
            "ios.rules.defend.b": "Jucătorul atacat în acest moment, marcat cu scutul, este apărătorul. Există un singur apărător la un moment dat, iar toate cărțile puse de ceilalți sunt treaba lui. Apărătorul poate doar să acopere, să ia cărțile sau să paseze (dacă este permis). Apărătorul NU POATE ataca. Toți ceilalți sunt atacanți și pot doar să atace. Atacanții NU POT acoperi nicio carte de pe masă.",
            "ios.rules.defend.b.nopass": "Jucătorul atacat în acest moment, marcat cu scutul, este apărătorul. Există un singur apărător la un moment dat, iar toate cărțile puse de ceilalți sunt treaba lui. Apărătorul poate doar să acopere sau să ia cărțile. Apărătorul NU POATE ataca. Toți ceilalți sunt atacanți și pot doar să atace. Atacanții NU POT acoperi nicio carte de pe masă.",
            "ios.rules.cover.h": "Acoperirea",
            "ios.rules.cover.b": "Apărătorul poate acoperi cărțile de pe masă punând peste fiecare o carte mai mare de aceeași culoare sau orice atu. Tocmai asta face culoarea de atu specială. Ca să acoperi, selectează o carte și atinge butonul Acoperă. Sau trage o carte din mână peste cea pe care vrei să o acoperi. O greșeală des întâlnită este să crezi că o carte deja acoperită mai poate fi acoperită de o a treia. Jocul nu funcționează așa: nu vei vedea niciodată grămezi de câte trei pe masă. Gândește-te la cartea de atac ca la o spadă și la cartea care acoperă ca la un scut: atacul a fost oprit și, prin urmare, s-a încheiat. Se pot face doar atacuri noi, în grămezi separate.",
            "ios.rules.cover.ok1": "O carte mai mare de aceeași culoare acoperă.",
            "ios.rules.cover.ok2": "Orice atu acoperă orice altă culoare - chiar și cu o valoare mai mică.",
            "ios.rules.cover.no1": "Un atac cu atu cere un atu mai mare - acest 7 este prea mic.",
            "ios.rules.cover.no2": "Valoare mai mare, culoare greșită - așa nu acoperi nimic.",
            "ios.rules.throw.h": "Adăugarea de cărți",
            "ios.rules.throw.b": "În timp ce apărătorul acoperă, oricare dintre ceilalți jucători poate \"adăuga\" alte cărți de atac, pe care apărătorul va trebui să le acopere și pe acelea. Regula este simplă, chiar dacă îți ia puțin până o prinzi. Dacă vezi pe masă VALOAREA (de exemplu A, 6, 10) unei cărți pe care o ai în mână și ești atacant, poți pune cartea aceea ca un atac nou, separat. De culori nu trebuie să îți pese DELOC. Singura limită este numărul de cărți pe care apărătorul le are în mână chiar atunci: pe masă nu pot fi mai multe atacuri neacoperite decât cărți are apărătorul. Imaginează-ți că apărătorul trebuie să poată răspunde fiecărei cărți de atac cu exact o carte de apărare; dacă atacurile sunt prea multe, este fizic imposibil și de aceea nu este permis. Poate te întrebi dacă numărul cărților de atac poate crește repede așa. Exact, și asta face parte din farmecul jocului. Ca să ataci, atinge o carte - sau un grup în care fiecare valoare se află deja pe masă - și apasă Atacă. Sau trage cărțile din mână pe masă.",
            "ios.rules.throw.ok1": "Pe masă este un 9, deci poți pune și tu un 9 - culorile nu contează.",
            "ios.rules.throw.ok2": "Ambele cărți de 6 deodată - două atacuri noi.",
            "ios.rules.throw.ok3": "Sau 6 și 9 împreună - ambele valori sunt deja pe masă.",
            "ios.rules.throw.no1": "Niciun 8 și niciun valet pe masă - nu ai ce adăuga.",
            "ios.rules.throw.no2": "Apărătorul are o carte și un atac deja așteaptă - nu mai este loc pentru încă unul.",
            "ios.rules.pickup.h": "Luarea cărților",
            "ios.rules.pickup.b": "Dacă apărătorul nu poate acoperi toate cărțile sau nu vrea, poate apăsa butonul Ia. Atunci ia de pe masă fiecare carte, chiar și pe cele deja acoperite. În plus, rândul lui este sărit, așa că în runda următoare atacă jucătorul din stânga lui. Gândește-te bine înainte să iei.",
            "ios.rules.pickup.cap": "Dacă iei aici, toate cele trei cărți ajung în mâna ta - și perechea acoperită.",
            "ios.rules.round.h": "Sfârșitul rundei",
            "ios.rules.round.b": "Când toate cărțile sunt acoperite și niciun atacant nu mai vrea să adauge, tot ce este pe masă merge la cărțile scoase din joc. Apoi jucătorii trag cărți, începând cu primul atacant și mergând în sensul acelor de ceas prin toți atacanții, până când fiecare are cel puțin 6 cărți. Apărătorul trage ultimul. Jocul face asta singur. Când pachetul se termină, nu se mai trage, iar jucătorii pot începe să scape de cărțile lor și să evite rolul prostului. Runda se încheie și dacă apărătorul ia cărțile: atunci cărțile de pe masă ajung în mâna lui, nu la cărțile scoase din joc, iar apoi se trage în aceeași ordine - apărătorul ultimul, ceea ce de obicei înseamnă deloc, fiindcă are deja mai mult de șase.",
            "ios.rules.pass.h": "Pasarea",
            "ios.rules.pass.b": "Într-un joc în care переводной, adică \"pasarea\", este permisă, apărătorul mai are o opțiune: să paseze atacul de la el mai departe, la jucătorul din stânga. Pentru asta, pe masă nu are voie să existe nicio carte acoperită, iar el trebuie să aibă o carte de aceeași VALOARE cu toate cărțile de atac de pe masă. Atunci pune cartea jos, iar scutul se mută în sensul acelor de ceas la jucătorul din stânga lui. Însă, la fel cum există o limită pentru câte cărți pot ataca, pasarea nu se poate face dacă jucătorul din stânga are mai puține cărți decât ar fi atacuri după pasare. De exemplu, dacă pe masă sunt două cărți de atac și jucătorul din stânga are două cărți, pasarea nu este posibilă: după ea ar fi cel puțin 3 cărți acolo (2 plus cartea pasată). Este mai mult decât are el în mână și de aceea nu este permis. Ca să pasezi, atinge cartea cu valoarea potrivită și apasă butonul Pasează. Sau trage cartea aceea într-un loc gol de pe masă.",
            "ios.rules.pass.ok1": "Atacă un 8 și tu ai un 8 - pune-l jos și scutul merge mai departe.",
            "ios.rules.pass.no1": "Ceva este deja acoperit - prea târziu ca să mai pasezi.",
            "ios.rules.pass.no2": "Niciun 8 în mâna ta - pe acesta trebuie să îl aperi singur.",
            "ios.rules.pass.no3": "Pasarea ar face trei atacuri, iar jucătorul următor are doar două cărți.",
            "ios.rules.end.h": "Sfârșitul jocului",
            "ios.rules.end.b": "După ce pachetul se golește, jocul continuă. Cine scapă de toate cărțile lui nu mai poate fi prostul. Prostul devine ultimul jucător rămas cu cărți.",
            "ios.rules.lobby.h": "Cum funcționează sala",
            "ios.rules.lobby.b": "Scrie-ți numele ca să intri. Odată ce au intrat cel puțin doi jucători, oricine poate apăsa Începe să joci. După ce jocul a început, nu mai intră nimeni.",
            "ios.rules.variant.h": "Pasarea",
            "ios.rules.variant.b": "În sală se alege ce fel de Durak joacă masa aceasta, iar căsuța spune care. Bifată înseamnă jocul cu pasare (perevodnoi): un apărător care are o carte de aceeași valoare cu atacul o poate pune jos și pasa tot atacul jucătorului următor, care acum trebuie să se apere. Nebifată înseamnă jocul cu adăugare (podkidnoi): nu există pasare, deci apărătorul fie acoperă fiecare carte de pe masă, fie ia tot. Cât timp sala este deschisă, oricine de la masă poate schimba asta; odată ce jocul începe, rămâne fix.",
            "ios.rules.fool.h": "Prostul plătește pentru asta",
            "ios.rules.fool.b": "De obicei cel mai mic atu hotărăște cine atacă primul. Există o excepție și este cel mai vechi fel de dreptate din Durak: dacă apeși Joc nou după ce o partidă s-a terminat și se așază exact aceiași jucători, cel mai mic atu nu hotărăște nimic. Deschide în schimb jucătorul din dreapta ultimului prost, ceea ce înseamnă că prostul este primul atacat. Pierzi, și partida următoare vine drept spre tine. Dacă intră sau iese cineva înainte de start, masa s-a schimbat și revine regula obișnuită.",
            "ios.lobby.passing": "Cu pasare",
            "ios.rules.lbl.table": "pe masă",
            "ios.rules.lbl.hand": "mâna ta",
            "ios.rules.defender": "Apărător",
            "ios.rules.nextplayer": "Jucătorul următor",
