            "ios.tut_done": "Începe să joci",
            "ios.tut_1": "Bine ai venit la Durak. Cel mai mic atu hotărăște cine atacă primul. Atuul bate orice altă culoare.",
            "ios.tut_2": "Ca să ataci, atinge o carte din mâna ta. Adversarul trebuie să o acopere - sau să ia tot.",
