            "ios.rules.title": "איך משחקים",
            "ios.rules.goal.h": "המטרה",
            "ios.rules.goal.b": "מטרת המשחק היא להיפטר מכל הקלפים שלך מהר ככל האפשר. מי שנשאר עם קלפים בסוף הוא дурак - השוטה, ברוסית.",
            "ios.rules.setup.h": "הכנה",
            "ios.rules.setup.b": "בארבעה שחקנים או פחות משחקים רק בקלפים מ-6 ועד אס. ה-2, ה-3, ה-4 וה-5 יוצאים מהחפיסה. האס הוא הקלף הגבוה ביותר במשחק הזה. כל שחקן מקבל 6 קלפים, ואז נשלף עוד קלף אחד, נחשף כלפי מעלה ומוכנס מתחת לערימת המשיכה. הצורה של הקלף החשוף הזה היא צורת השליט. הצורה הזאת מיוחדת, וההסבר נמצא בפרק ההגנה.",
            "ios.rules.setup.cap": "קלף אחד מונח חשוף מתחת לערימה - הצורה שלו היא השליט. לב, בכל הדוגמאות בעמוד הזה.",
            "ios.rules.start.h": "תחילת המשחק",
            "ios.rules.start.b": "מי שמחזיק את השליט הנמוך ביותר מתחיל. סביב שולחן אמיתי מבררים את זה בשאלה מי מחזיק 6, אחר כך 7, וכן הלאה. כאן המשחק עושה זאת בעצמו. השחקן הזה הוא התוקף הראשון של הסיבוב.",
            "ios.rules.sword": "החרב מסמנת את התוקף שפותח את הסיבוב.",
            "ios.rules.shield": "סמל המגן מסמן את השחקן המתגונן.",
            "ios.rules.attack.h": "התקפה",
            "ios.rules.attack.b": "התוקף הראשון של הסיבוב, המסומן בחרב, יכול לבחור מהיד כל קלף שהוא - או כמה קלפים בעלי אותו ערך - ולהניח אותם מול השחקן משמאלו (עם כיוון השעון). אותו שחקן הופך למגן, מסומן בסמל המגן, וחייב להתמודד עם ההתקפה. כדי לתקוף הקש על הקלפים כדי לבחור אותם ולחץ על כפתור תקוף שמופיע ברגע שהבחירה היא מהלך חוקי. או פשוט גרור קלפים מהיד אל השולחן.",
            "ios.rules.attack.ok1": "השחקן הזה יכול לתקוף עם המלכה שלו.",
            "ios.rules.attack.ok2": "הוא יכול לתקוף גם עם שני המלכים יחד, כי הערך שלהם זהה.",
            "ios.rules.attack.no1": "הוא לא יכול לתקוף עם ה-7 וה-10 יחד, כי הערכים שלהם שונים.",
            "ios.rules.defend.h": "הגנה",
            "ios.rules.defend.b": "השחקן שתחת התקפה כרגע, המסומן בסמל המגן, הוא המגן. יש מגן אחד בלבד בכל רגע נתון, וכל הקלפים שהאחרים מניחים הם עניינו. המגן יכול רק לכסות, לקחת את הקלפים או להעביר הלאה (אם זה מותר). המגן אינו יכול לתקוף. כל השאר הם תוקפים ויכולים רק לתקוף. תוקפים אינם יכולים לכסות אף קלף על השולחן.",
            "ios.rules.defend.b.nopass": "השחקן שתחת התקפה כרגע, המסומן בסמל המגן, הוא המגן. יש מגן אחד בלבד בכל רגע נתון, וכל הקלפים שהאחרים מניחים הם עניינו. המגן יכול רק לכסות או לקחת את הקלפים. המגן אינו יכול לתקוף. כל השאר הם תוקפים ויכולים רק לתקוף. תוקפים אינם יכולים לכסות אף קלף על השולחן.",
            "ios.rules.cover.h": "כיסוי",
            "ios.rules.cover.b": "המגן יכול לכסות את הקלפים שעל השולחן בכך שיניח על כל אחד מהם קלף גבוה יותר מאותה צורה, או שליט כלשהו. זה בדיוק מה שהופך את צורת השליט למיוחדת. כדי לכסות בחר קלף והקש על כפתור כסה. אפשר גם לגרור קלף מהיד אל הקלף שברצונך לכסות. טעות נפוצה היא לחשוב שאפשר לכסות קלף מכוסה בקלף שלישי. המשחק לא עובד כך: לעולם לא תראה ערימות של שלושה קלפים על השולחן. חשוב על קלף ההתקפה כעל חרב ועל הקלף המכסה כעל מגן: ההתקפה נחסמה, ולכן הסתיימה. אפשר רק לתקוף מחדש, בערימות נפרדות.",
            "ios.rules.cover.ok1": "קלף גבוה יותר מאותה צורה מכסה.",
            "ios.rules.cover.ok2": "כל שליט מכסה כל צורה אחרת - גם בערך נמוך יותר.",
            "ios.rules.cover.no1": "התקפת שליט דורשת שליט גבוה יותר - ה-7 הזה נמוך מדי.",
            "ios.rules.cover.no2": "ערך גבוה יותר, צורה לא נכונה - זה לא מכסה כלום.",
            "ios.rules.throw.h": "הוספת קלפים",
            "ios.rules.throw.b": "בזמן שהמגן מכסה, כל שאר השחקנים יכולים להוסיף קלפי התקפה נוספים שהמגן יצטרך לכסות גם אותם. הכלל פשוט, אף שלוקח קצת זמן להפנים אותו. אם אתה רואה על השולחן את הערך (למשל A, 6, 10) של קלף שיש לך ביד, ואתה תוקף, מותר לך להוסיף את הקלף הזה כהתקפה חדשה ונפרדת. אין צורך להתייחס לצורות כלל. המגבלה היחידה היא מספר הקלפים שביד המגן באותו רגע: לא יכולות להיות על השולחן יותר התקפות לא מכוסות ממספר הקלפים שבידו. תאר לעצמך שהמגן חייב להיות מסוגל לענות לכל קלף התקפה בקלף הגנה אחד; אם ההתקפות רבות מדי, זה פשוט בלתי אפשרי, ולכן אסור. אולי אתה תוהה אם כך מספר קלפי ההתקפה יכול לגדול במהירות. בדיוק כך, וזה חלק מהכיף של המשחק. כדי לתקוף הקש על קלף - או על כמה קלפים שהערך של כל אחד מהם כבר נמצא על השולחן - ולחץ על תקוף. אפשר גם לגרור קלפים מהיד אל השולחן.",
            "ios.rules.throw.ok1": "יש 9 על השולחן, ולכן גם ה-9 שלך יכול להיכנס - הצורות לא משנות.",
            "ios.rules.throw.ok2": "שני ה-6 יחד - שתי התקפות חדשות.",
            "ios.rules.throw.ok3": "או ה-6 וה-9 יחד - שני הערכים כבר על השולחן.",
            "ios.rules.throw.no1": "אין 8 ואין נסיך על השולחן - אין מה להוסיף.",
            "ios.rules.throw.no2": "למגן נשאר קלף אחד וכבר מחכה התקפה אחת - אין מקום לעוד אחת.",
            "ios.rules.pickup.h": "לקיחת הקלפים",
            "ios.rules.pickup.b": "אם המגן אינו יכול לכסות את כל הקלפים, או שאינו רוצה, הוא יכול ללחוץ על כפתור קח. אז הוא לוקח כל קלף מהשולחן, גם קלפים שכבר כוסו. בנוסף, התור שלו מדולג, כך שהשחקן משמאלו יפתח בהתקפה בסיבוב הבא. לכן כדאי לחשוב היטב לפני שלוקחים.",
            "ios.rules.pickup.cap": "אם תיקח כאן, כל שלושת הקלפים יעברו לידך - גם הזוג המכוסה.",
            "ios.rules.round.h": "סוף הסיבוב",
            "ios.rules.round.b": "כשכל הקלפים מכוסים ואף תוקף אינו רוצה להוסיף עוד, כל מה שעל השולחן עובר לערימת ההשלכה. אחר כך מושכים קלפים, החל מהתוקף הראשון ועם כיוון השעון דרך כל התוקפים, עד שיש לכל אחד לפחות 6 קלפים. המגן מושך אחרון. המשחק עושה זאת בעצמו. כשהחפיסה נגמרת כבר לא מושכים, והשחקנים יכולים להתחיל להיפטר מהקלפים שלהם ולחמוק מתפקיד השוטה. הסיבוב מסתיים גם כאשר המגן לוקח את הקלפים: במקרה כזה הקלפים מהשולחן עוברים לידו במקום לערימת ההשלכה, ואחר כך מושכים באותו סדר - המגן אחרון, ובדרך כלל זה אומר שהוא כלל לא מושך, כי יש בידו יותר משישה.",
            "ios.rules.pass.h": "העברה",
            "ios.rules.pass.b": "במשחק שבו переводной, כלומר ההעברה, מותרת, למגן יש אפשרות נוספת: להעביר את ההתקפה ממנו הלאה אל השחקן משמאלו. לשם כך אסור שאף קלף על השולחן יהיה מכוסה, ועליו להחזיק קלף בעל אותו ערך כמו כל קלפי ההתקפה שעל השולחן. אז הוא מניח את הקלף, וסמל המגן עובר עם כיוון השעון אל השחקן משמאלו. אבל, בדיוק כפי שיש מגבלה על מספר קלפי ההתקפה, אי אפשר להעביר אם לשחקן משמאל יש פחות קלפים ממספר ההתקפות שיהיו אחרי ההעברה. למשל, אם על השולחן שני קלפי התקפה ולשחקן משמאל שני קלפים, אי אפשר להעביר, כי אחרי ההעברה יהיו שם לפחות 3 קלפים (2 ועוד הקלף שהועבר). זה יותר ממה שיש בידו, ולכן אסור. כדי להעביר הקש על הקלף בעל הערך המתאים ולחץ על כפתור העבר. או גרור את הקלף למקום פנוי על השולחן.",
            "ios.rules.pass.ok1": "תוקפים אותך ב-8 ויש לך 8 - הנח אותו והמגן עובר הלאה.",
            "ios.rules.pass.no1": "משהו כבר מכוסה - מאוחר מדי להעביר.",
            "ios.rules.pass.no2": "אין 8 בידך - על זה תצטרך להגן בעצמך.",
            "ios.rules.pass.no3": "העברה תיצור שלוש התקפות, ולשחקן הבא יש רק שני קלפים.",
            "ios.rules.end.h": "סוף המשחק",
            "ios.rules.end.b": "אחרי שערימת המשיכה מתרוקנת המשחק ממשיך. מי שסיים את הקלפים שלו כבר לא יכול להיות השוטה. השחקן האחרון שנשאר עם קלפים הופך לשוטה.",
            "ios.rules.lobby.h": "איך הלובי עובד",
            "ios.rules.lobby.b": "הוסף את שמך כדי להצטרף. ברגע שהצטרפו לפחות שני שחקנים, כל אחד יכול ללחוץ על התחל משחק. אחרי שהמשחק מתחיל אף אחד לא יכול להצטרף.",
            "ios.rules.variant.h": "העברה",
            "ios.rules.variant.b": "בלובי נקבע איזה דוראק השולחן הזה משחק, והתיבה מראה איזה. מסומן פירושו המשחק עם העברה (perevodnoy): מגן שמחזיק קלף באותו ערך כמו ההתקפה יכול להניח אותו ולהעביר את כל ההתקפה לשחקן הבא, שעכשיו חייב להגן עליה. לא מסומן פירושו משחק ההוספה (podkidnoy): אין העברה, ולכן המגן מכסה כל קלף על השולחן או לוקח את הכול. כל עוד הלובי פתוח כל אחד סביב השולחן יכול לשנות זאת; ברגע שהמשחק מתחיל ההגדרה ננעלת.",
            "ios.rules.fool.h": "השוטה משלם על זה",
            "ios.rules.fool.b": "בדרך כלל השליט הנמוך ביותר קובע מי תוקף ראשון. יש יוצא דופן אחד, והוא הסוג העתיק ביותר של צדק בדוראק: אם תלחץ על משחק חדש בתום משחק ובדיוק אותם שחקנים יתיישבו שוב, השליט הנמוך ביותר לא קובע דבר. במקומו פותח השחקן שיושב מימין לשוטה הקודם, ומשמעות הדבר שהשוטה הוא הראשון שתוקפים אותו. תפסיד, והמשחק הבא בא ישר עליך. אם מישהו מצטרף או עוזב לפני ההתחלה, השולחן השתנה והכלל הרגיל חוזר.",
