            "ios.settings.table.wool": "صوف",
            "ios.settings.table.felt": "جوخ أخضر",
            "ios.rules.title": "طريقة اللعب",
            "ios.rules.goal.h": "الهدف",
            "ios.rules.goal.b": "هدف اللعبة هو التخلص من كل أوراقك بأسرع ما يمكن. ومن يبقى في يده أوراق في النهاية هو «دوراك» (дурак)، ومعناها بالروسية: الأحمق.",
            "ios.rules.setup.h": "التحضير",
            "ios.rules.setup.b": "مع أربعة لاعبين أو أقل يُلعب بالأوراق من 6 إلى الآس فقط. تُرفع أوراق 2 و3 و4 و5 من المجموعة. الآس هو الأعلى في هذه اللعبة. يأخذ كل لاعب 6 أوراق، ثم تُسحب ورقة أخرى وتُقلب مكشوفة وتوضع تحت كومة السحب. نوع هذه الورقة المكشوفة هو نوع الحكم. هذا النوع مميز، وسبب ذلك مشروح في باب الدفاع.",
            "ios.rules.setup.cap": "ورقة واحدة موضوعة مكشوفة تحت الكومة - نوعها هو الحكم. الكبة، في كل الأمثلة في هذه الصفحة.",
            "ios.rules.start.h": "بداية اللعبة",
            "ios.rules.start.b": "يبدأ من يملك أدنى ورقة حكم. على طاولة حقيقية يُعرف ذلك بالسؤال عمن معه 6، ثم 7، وهكذا. هنا تتولى اللعبة ذلك بنفسها. هذا اللاعب هو المهاجم الأول في الجولة.",
            "ios.rules.sword": "السيف يشير إلى المهاجم الذي يفتتح الجولة.",
            "ios.rules.shield": "الدرع يشير إلى المدافع.",
            "ios.rules.attack.h": "الهجوم",
            "ios.rules.attack.b": "المهاجم الأول في الجولة، المميّز بالسيف، يمكنه أن يختار من يده أي ورقة - أو أي مجموعة أوراق لها القيمة نفسها - ويضعها أمام اللاعب الذي على يساره (مع عقارب الساعة). هذا اللاعب صار الآن المدافع، مميّزًا بالدرع، وعليه أن يتصرف مع الهجوم. لكي تهاجم انقر على الأوراق لتختارها ثم اضغط زر الهجوم الذي يظهر حين تصبح النقلة صحيحة. أو اسحب الأوراق ببساطة من يدك إلى الطاولة.",
            "ios.rules.attack.ok1": "يستطيع هذا اللاعب أن يهاجم ببنته.",
            "ios.rules.attack.ok2": "ويستطيع أن يهاجم بالملكين معًا في الوقت نفسه، لأن قيمتهما واحدة.",
            "ios.rules.attack.no1": "ولا يستطيع أن يهاجم بورقة 7 وورقة 10 معًا، لأن قيمتيهما مختلفتان.",
            "ios.rules.defend.h": "الدفاع",
            "ios.rules.defend.b": "اللاعب الذي يتعرض للهجوم الآن، المميّز بالدرع، هو المدافع. لا يوجد إلا مدافع واحد في كل لحظة، وكل ورقة يضعها الآخرون على الطاولة تقع على عاتقه هو. لا يستطيع المدافع إلا أن يغطي أو يأخذ الأوراق أو يمرر الهجوم (إن كان مسموحًا). لا يجوز للمدافع أن يهاجم. أما البقية فكلهم مهاجمون ولا يستطيعون إلا الهجوم. ولا يجوز للمهاجمين أن يغطوا أي ورقة على الطاولة.",
            "ios.rules.defend.b.nopass": "اللاعب الذي يتعرض للهجوم الآن، المميّز بالدرع، هو المدافع. لا يوجد إلا مدافع واحد في كل لحظة، وكل ورقة يضعها الآخرون على الطاولة تقع على عاتقه هو. لا يستطيع المدافع إلا أن يغطي أو يأخذ الأوراق. لا يجوز للمدافع أن يهاجم. أما البقية فكلهم مهاجمون ولا يستطيعون إلا الهجوم. ولا يجوز للمهاجمين أن يغطوا أي ورقة على الطاولة.",
            "ios.rules.cover.h": "التغطية",
            "ios.rules.cover.b": "يستطيع المدافع أن يغطي الأوراق التي على الطاولة بأن يضع على كل ورقة ورقة أعلى منها من النوع نفسه، أو أي ورقة حكم. هذا بالضبط ما يجعل نوع الحكم مميزًا. لكي تغطي اختر ورقة وانقر زر التغطية. أو اسحب ورقة من يدك إلى الورقة التي تريد تغطيتها على الطاولة. من الأخطاء الشائعة الظن بأن الورقة المغطاة يمكن تغطيتها مرة أخرى بورقة ثالثة. اللعبة لا تسير هكذا: لن ترى أبدًا كومة من ثلاث أوراق على الطاولة. تخيّل ورقة الهجوم سيفًا وورقة التغطية درعًا: الهجوم صُدّ، وبذلك انتهى. ولا يمكن إلا شن هجمات جديدة، في أكوام منفصلة.",
            "ios.rules.cover.ok1": "ورقة أعلى من النوع نفسه تغطي.",
            "ios.rules.cover.ok2": "أي ورقة حكم تغطي أي نوع آخر - حتى لو كانت قيمتها أقل.",
            "ios.rules.cover.no1": "الهجوم بورقة حكم يحتاج إلى حكم أعلى - وهذه الـ7 أقل من اللازم.",
            "ios.rules.cover.no2": "القيمة أعلى لكن النوع خطأ - وهذه لا تغطي شيئًا.",
            "ios.rules.throw.h": "إضافة الأوراق",
            "ios.rules.throw.b": "بينما يغطي المدافع، يستطيع كل لاعب آخر أن يضيف أوراق هجوم جديدة على المدافع أن يغطيها كذلك. القاعدة بسيطة، وإن كانت تحتاج بعض الوقت لتستقر في الذهن. إذا كانت قيمة ورقةٍ في يدك موجودة على الطاولة - كالآس أو الستة أو العشرة - وكنت مهاجمًا، جاز لك أن تضع تلك الورقة هجومًا جديدًا مستقلًا. ولا حاجة للاهتمام بالأنواع إطلاقًا. القيد الوحيد هو عدد الأوراق التي في يد المدافع في تلك اللحظة: لا يجوز أن تكون الهجمات غير المغطاة على الطاولة أكثر من الأوراق التي بيده. تخيّل أن على المدافع أن يستطيع الرد على كل ورقة هجوم بورقة دفاع واحدة؛ فإذا كثرت الهجمات صار ذلك مستحيلًا، ولهذا لا يُسمح به. ولعلك تتساءل إن كان عدد أوراق الهجوم قد يتضاعف بسرعة على هذا النحو. هذا صحيح تمامًا، وهو جزء من متعة اللعبة. لكي تهاجم انقر على ورقة - أو على مجموعة قيمة كل ورقة فيها موجودة على الطاولة - ثم اضغط الهجوم. أو اسحب الأوراق من يدك إلى الطاولة.",
            "ios.rules.throw.ok1": "على الطاولة ورقة 9، فتستطيع إضافة الـ9 التي معك - والأنواع لا تهم.",
            "ios.rules.throw.ok2": "ورقتا الـ6 معًا - هجومان جديدان.",
            "ios.rules.throw.ok3": "أو الـ6 والـ9 معًا - كلتا القيمتين موجودة على الطاولة.",
            "ios.rules.throw.no1": "لا توجد 8 ولا ولد على الطاولة - فليس هناك ما يُضاف.",
            "ios.rules.throw.no2": "في يد المدافع ورقة واحدة وهناك هجوم ينتظر بالفعل - فلا مكان لهجوم آخر.",
            "ios.rules.pickup.h": "أخذ الأوراق",
            "ios.rules.pickup.b": "إذا لم يستطع المدافع تغطية كل الأوراق، أو لم يرد ذلك، فبإمكانه الضغط على زر خذ. عندها يأخذ كل ورقة على الطاولة، حتى ما غُطي منها. كما يُتخطى دوره، فيبدأ اللاعب الذي على يساره الهجوم في الجولة التالية. ففكّر جيدًا قبل أن تأخذ.",
            "ios.rules.pickup.cap": "إن أخذت هنا انتقلت الأوراق الثلاث كلها إلى يدك - بما فيها الزوج المغطى.",
            "ios.rules.round.h": "نهاية الجولة",
            "ios.rules.round.b": "حين تُغطى كل الأوراق ولا يريد أي مهاجم أن يضيف المزيد، ينتقل كل ما على الطاولة إلى كومة الحرق. ثم يسحب اللاعبون، بدءًا بالمهاجم الأول وباتجاه عقارب الساعة عبر كل المهاجمين، حتى يصير مع كل واحد 6 أوراق على الأقل. ومن كانت بيده ست أو أكثر فلا يسحب. ويسحب المدافع أخيرًا. تتولى اللعبة ذلك تلقائيًا. وحين تنفد كومة السحب لا سحب بعدها، ويبدأ اللاعبون في التخلص من أوراقهم هربًا من دور الأحمق. وتنتهي الجولة كذلك إذا اختار المدافع أخذ الأوراق: عندها تذهب أوراق الطاولة إلى يده بدل كومة الحرق، ثم يُسحب بالترتيب نفسه - والمدافع أخيرًا، وهو في الغالب لا يسحب شيئًا لأن بيده أكثر من ست.",
            "ios.rules.pass.h": "التمرير",
            "ios.rules.pass.b": "في لعبة يُسمح فيها بـпереводной، أي التمرير، يملك المدافع خيارًا إضافيًا: أن يمرر الهجوم عنه إلى اللاعب الذي على يساره. ولذلك يجب ألا تكون أي ورقة على الطاولة مغطاة، وأن تكون معه ورقة لها القيمة نفسها التي لكل أوراق الهجوم على الطاولة. عندها يضع تلك الورقة، وتنتقل علامة المدافع مع عقارب الساعة إلى اللاعب الذي على يساره. غير أنه، تمامًا كما أن لعدد أوراق الهجوم حدًا، لا يجوز التمرير إذا كان مع اللاعب الذي على اليسار أوراق أقل من عدد الهجمات التي ستكون بعد التمرير. فمثلًا، إذا كان على الطاولة ورقتا هجوم وكان مع اللاعب الذي على اليسار ورقتان، تعذّر التمرير، لأنه سيصير هناك بعده 3 أوراق على الأقل (2 زائد الورقة الممررة). وهذا أكثر مما في يده، ولهذا لا يُسمح به. لكي تمرر انقر على الورقة ذات القيمة المطابقة ثم اضغط زر التمرير. أو اسحب تلك الورقة إلى مكان خالٍ على الطاولة.",
            "ios.rules.pass.ok1": "يهاجمك 8 ومعك 8 - ضعها ينتقل الدرع إلى التالي.",
            "ios.rules.pass.no1": "هناك ورقة مغطاة بالفعل - فات أوان التمرير.",
            "ios.rules.pass.no2": "ليس معك 8 - هذا الهجوم عليك أن تردّه بنفسك.",
            "ios.rules.pass.no3": "التمرير سيجعلها ثلاث هجمات، واللاعب التالي معه ورقتان فقط.",
            "ios.rules.end.h": "نهاية اللعبة",
            "ios.rules.end.b": "بعد أن تفرغ كومة السحب تستمر اللعبة. ومن تخلّص من كل أوراقه لم يعد بإمكانه أن يكون الأحمق. ويصير الأحمق آخر لاعب تبقى في يده أوراق.",
            "ios.rules.lobby.h": "كيف تعمل الردهة",
            "ios.rules.lobby.b": "أضف اسمك لتنضم. وحين ينضم لاعبان على الأقل يستطيع أي واحد أن يضغط ابدأ اللعب. وبعد أن تبدأ اللعبة لا يستطيع أحد الانضمام.",
            "ios.rules.variant.h": "التمرير",
            "ios.rules.variant.b": "في الردهة يُختار أي دوراك تلعبه هذه الطاولة، والمربع يبيّن أيها. المؤشَّر عليه هو اللعب بالتمرير (perevodnoy): المدافع الذي معه ورقة بقيمة الهجوم نفسها يستطيع أن يضعها ويمرر الهجوم كله إلى اللاعب التالي، وعليه هو الآن أن يدافع. وغير المؤشَّر عليه هو لعب الإضافة (podkidnoy): لا تمرير فيه، فإما أن يغطي المدافع كل ورقة على الطاولة وإما أن يأخذها كلها. وما دامت الردهة مفتوحة يستطيع أي أحد على الطاولة تغييره؛ وحالما تبدأ اللعبة يثبت.",
            "ios.rules.fool.h": "الأحمق يدفع الثمن",
            "ios.rules.fool.b": "في العادة تحدد أدنى ورقة حكم من يهاجم أولًا. لكن هناك استثناء واحد، وهو أقدم صور العدالة في دوراك: إذا ضغطت لعبة جديدة بعد انتهاء لعبة وجلس اللاعبون أنفسهم تمامًا من جديد، فإن أدنى ورقة حكم لا تحدد شيئًا. بل يفتتح اللاعب الذي يجلس على يمين الأحمق السابق، ومعنى ذلك أن الأحمق هو أول من يُهاجَم. تخسر، فتأتيك اللعبة التالية مباشرة. وإذا انضم أحد أو غادر قبل البدء فقد تغيّرت الطاولة وعادت القاعدة المعتادة.",
            "ios.lobby.passing": "مع التمرير",
            "ios.rules.lbl.table": "على الطاولة",
