            "ios.tut_1": "أهلًا بك في دوراك. أدنى ورقة من نوع الحكم تحدد من يهاجم أولًا. الحكم يغلب كل نوع آخر.",
            "ios.tut_2": "لكي تهاجم انقر على ورقة في يدك. على خصمك أن يغطيها - أو يأخذ كل شيء.",
            "ios.tut_3": "لكي تدافع انقر على إحدى أوراقك ثم على الهجوم الذي تغطيه. تغطيه ورقة أعلى من النوع نفسه، أو أي ورقة حكم.",
            "ios.tut_4": "لا تستطيع الدفاع أو لا تريد؟ انقر على خذ لتأخذ الأوراق. انتهيت من الهجوم؟ انقر على انتهيت.",
